// Configure Monaco's bundled TypeScript language service so JS/TS files get
// real completions, hover, signature help, go-to-definition and live
// diagnostics — not just syntax highlighting. This needs no external language
// server, so it works in both the native app and the browser preview.
function configureLanguageService() {
  const ts = monaco.languages.typescript;
  const compilerOptions = {
    target: ts.ScriptTarget.ESNext,
    module: ts.ModuleKind.ESNext,
    moduleResolution: ts.ModuleResolutionKind.NodeJs,
    allowJs: true,
    checkJs: false,
    allowNonTsExtensions: true,
    esModuleInterop: true,
    jsx: ts.JsxEmit.ReactJSX,
    skipLibCheck: true,
    noEmit: true,
    baseUrl: ".",
  };
  for (const d of [ts.typescriptDefaults, ts.javascriptDefaults]) {
    d.setCompilerOptions(compilerOptions);
    d.setEagerModelSync(true);
    d.setDiagnosticsOptions({ noSemanticValidation: false, noSyntaxValidation: false });
  }
}
configureLanguageService();

// ---- backend abstraction (Tauri when available, mock in a plain browser) ----
const inTauri = typeof window !== "undefined" && "__TAURI_INTERNALS__" in window;
// Tauri can deliver an event after an invoke resolves or a PTY is closed. Its
// Channel dispatcher calls `onmessage.call(...)`, so replacing a finished
// callback with null turns an otherwise harmless late event into an app crash.
// Use a shared sink to release the captured render/terminal state safely.
const _TAURI_CHANNEL_SINK = () => {};
function _releaseTauriChannel(channel) {
  try { if (channel) channel.onmessage = _TAURI_CHANNEL_SINK; } catch {}
}
// Secondary editor windows are opened with ?w=sub. They share localStorage with the
// main window, so they must NOT restore or overwrite the main window's saved
// session/tabs/chat — they're independent working windows (open another project here).
const _isSecondaryWindow = typeof location !== "undefined" && /[?&]w=sub\b/.test(location.search || "");
// Reserve room for the macOS traffic-light buttons only when running natively on macOS.
if (inTauri) document.body.classList.add("is-tauri");
if (/Mac/i.test(navigator.platform || navigator.userAgent)) {
  document.body.classList.add("is-mac");
} else if (/Win/i.test(navigator.platform || navigator.userAgent)) {
  // 以前只有 is-mac，没有 is-win——于是没有任何钩子能给 Windows 单独调样式。
  // 两处必须靠它：① 自绘的窗口按钮只在 Windows 显示（那边关掉了原生标题栏）；
  // ② -webkit-font-smoothing 在 Windows 的 Blink 里是**空操作**（Chromium 只在 macOS
  //    实现它），而这套界面的字重字号是照着 mac 削细之后的观感调的，同一份样式到
  //    Windows 上整体偏粗偏糊——只有拿到这个钩子才补得回来。
  document.body.classList.add("is-win");
}
// `content-visibility: auto` is what keeps a long conversation from getting heavy — it skips
// layout and paint for everything off-screen. It is also, in WebKit, what leaves BLANK REGIONS
// behind when you scroll: the element is skipped for rendering and its placeholder is painted
// empty, so a scroll can land on a white page. On macOS this app runs in WKWebView and cannot
// avoid that engine; on Windows it runs in WebView2, which is Chromium and does not have the
// defect. So the optimization is granted rather than assumed — a class the engine has to earn,
// which also means a blank page is never the default while this line is loading.
try {
  const ua = navigator.userAgent || "";
  if (/AppleWebKit/.test(ua) && !/Chrome|Chromium|Edg\//.test(ua)) document.body.classList.add("is-webkit");
  else document.body.classList.add("cv-safe");
} catch { /* no navigator (tests) → stay on the safe side and skip the optimization */ }
const backend = inTauri ? await tauriBackend() : mockBackend();

// 网页版必须自己说清楚它是个演示工作区。
//
// `mockBackend()` 不是"少几个功能的真后端"，它是一整套模拟实现：项目树是写死的假工程，
// writeTextFile 写进一个 JS 对象，git 是想象出来的 HEAD，终端是七条硬编码命令的回放，
// 选文件夹的函数直接返回那个假根目录。刷新页面全部消失，网页端的对话记录也不落盘。
//
// 危险在于**它看起来是能用的**：桌面专属工具（抓包/自动化/读屏）在网页端被从工具表里
// 剥掉了，但 read/write/edit/git 没有——它们照常执行、照常回报成功，只是作用在假文件
// 系统上。本文件另一处注释已经记下这个形状：mock 的 invoke 返回 {}，智能体会拿着假的
// 成功继续往下做。
//
// 而 /app/ 不是内部预览：它在 auth_request 门禁后面，2026-08-22 实测当天 2,147 次
// /v1/chat/completions 里有 655 次来自浏览器 UA，全部按正常费率计费。在这条横幅之前，
// 界面上没有任何一个字告诉那些人"你刚才让它改的文件是假的"。
//
// 用注入的 <style> 而不是往 app.css（15,662 行）里加规则：这段和主题无关、只有一处用，
// 就近放着比散进大表更难被误删。sessionStorage 而不是 localStorage：关掉只管这一次会话，
// 下次打开还得再看见一遍——这是有意的，别改成永久静音。
if (!inTauri) {
  try {
    if (!sessionStorage.getItem("mdo_preview_notice_dismissed")) {
      const style = document.createElement("style");
      style.textContent = `
        .mdo-preview-notice{position:fixed;left:0;right:0;top:0;z-index:99999;display:flex;
          gap:10px;align-items:center;justify-content:center;flex-wrap:wrap;
          padding:9px 44px 9px 16px;box-sizing:border-box;
          font:500 13px/1.45 -apple-system,BlinkMacSystemFont,"Segoe UI",system-ui,sans-serif;
          color:#3a2a05;background:#ffd66b;border-bottom:1px solid rgba(0,0,0,.18);
          box-shadow:0 1px 6px rgba(0,0,0,.16)}
        .mdo-preview-notice b{font-weight:700}
        .mdo-preview-notice a{color:#1e3a73;font-weight:600;text-underline-offset:2px}
        .mdo-preview-notice button{position:absolute;right:8px;top:50%;transform:translateY(-50%);
          width:26px;height:26px;border:0;border-radius:6px;cursor:pointer;
          background:transparent;color:#3a2a05;font-size:17px;line-height:1}
        .mdo-preview-notice button:hover{background:rgba(0,0,0,.10)}
        .mdo-preview-notice button:focus-visible{outline:2px solid #1e3a73;outline-offset:1px}
        body.mdo-has-preview-notice #root{padding-top:38px;box-sizing:border-box}
        @media (prefers-reduced-motion:reduce){.mdo-preview-notice{transition:none}}
      `;
      document.head.appendChild(style);
      const bar = document.createElement("div");
      bar.className = "mdo-preview-notice";
      bar.setAttribute("role", "status");
      const text = document.createElement("span");
      // 说清楚三件事：这是演示、改动不真、去哪拿真的。不写"部分功能受限"这种话——
      // 用户会理解成"能用，只是少点东西"，而实际是文件根本没被改过。
      text.innerHTML =
        '<b>这是演示工作区</b>：文件、终端和 Git 都是模拟的，'
        + 'AI 在这里做的修改<b>不会写到任何真实文件</b>，刷新即消失。'
        + '要真正编辑项目，请使用 <a href="https://mrday.one/" target="_blank" rel="noopener">桌面版</a>。';
      const close = document.createElement("button");
      close.type = "button";
      close.textContent = "×";
      close.setAttribute("aria-label", "关闭本次提示");
      close.addEventListener("click", () => {
        try { sessionStorage.setItem("mdo_preview_notice_dismissed", "1"); } catch { /* 隐私模式 */ }
        bar.remove();
        document.body.classList.remove("mdo-has-preview-notice");
      });
      bar.append(text, close);
      document.body.appendChild(bar);
      document.body.classList.add("mdo-has-preview-notice");
    }
  } catch { /* 提示挂不上去也绝不能拖垮启动 */ }
}

// Multi-agent coordination is local to the current IDE run. The previous build
// opened a WebSocket to `/ws/subagents`, an endpoint that does not exist, and its
// context reader always returned null. Use the real workspace backend and the
// existing SharedStore instead of advertising a disconnected realtime layer.
window.collaborationEngine = getCollaborationEngine({
  store: _globalSharedStore,
  // mode 这里给什么都不影响：唯一的 startSession 调用点写死 lead_follower，
  // 而引擎现在也只剩这一种模式（shared_store 那条是 main.js 早就直接做了的第二套实现，
  // 已删）。留着这个字段只是为了不改构造器签名。
  mode: "lead_follower",
  // readFile 注入删了：它唯一的消费方是 extractFileSnippets，而那条链的入口
  // （enhanceContext 的 filesToInclude）在生产里恒为空数组，一次都没执行过。
  config: {
    // tokenBudget / warningThreshold / criticalThreshold / broadcastThreshold 四个也删了：
    // 读它们的那一族方法（trackTokenUsage 等五个）零调用点，已随之删除。
    maxContextSize: 8000,
  },
});

// ── Remote development ────────────────────────────────────────────────────────
// Connect to a `michael-remote-agent.py` daemon on another machine/server → the
// explorer AND the agent then read/write/run on THAT machine, transparently. No SSH,
// no scp. When `_remote.active`, the core file + command ops below route to the
// daemon's HTTP API instead of the local filesystem. (Git on remote works for free —
// the agent just runs git via run_cmd → /exec.)
const _remote = { active: false, url: "", token: "", root: "", host: "", platform: "" };
async function _remoteCall(ep, body) {
  const r = await fetch(_remote.url + ep, {
    method: "POST", cache: "no-store",
    headers: { Authorization: "Bearer " + _remote.token, "Content-Type": "application/json" },
    body: JSON.stringify(body || {}),
  });
  let j = {}; try { j = await r.json(); } catch {}
  if (!r.ok || (j && j.error)) throw new Error((j && j.error) || ("远程错误 HTTP " + r.status));
  return j;
}
async function connectRemote(url, token, root) {
  url = String(url || "").trim().replace(/\/+$/, "");
  if (!/^https?:\/\//.test(url)) url = "http://" + url;
  const prev = { ..._remote };
  Object.assign(_remote, { active: true, url, token: String(token || "").trim(), root: String(root || "").trim() });
  try {
    const ping = await _remoteCall("/ping", {});            // verify reachable + token
    _remote.host = ping.host || url;
    _remote.platform = ping.platform || "";
    _remote.root = _remote.root || ping.root || ".";
    try { showToast("已连接远程：" + _remote.host + "（" + _remote.root + "）"); } catch {}
    // Load the remote root into the explorer — readDir is now routed to the daemon, so
    // openFolder lists the REMOTE tree. (Local-only steps inside fail harmlessly.)
    try { await openFolder(_remote.root); } catch {}
    return { ok: true, host: _remote.host, root: _remote.root };
  } catch (e) {
    Object.assign(_remote, prev); // rollback on failure
    try { showToast("连远程失败：" + (e?.message || e)); } catch {}
    throw e;
  }
}
function disconnectRemote() { Object.assign(_remote, { active: false, url: "", token: "", root: "", host: "", platform: "" }); try { showToast("已断开远程"); } catch {} }
if (typeof window !== "undefined") { window.connectRemote = connectRemote; window.disconnectRemote = disconnectRemote; window._remote = _remote; }

// The remote daemon returns a compact flat hit list, while the editor and Agent
// consume the same grouped FileMatches shape as the native Rust backend. Normalize
// it once at the routing boundary so search, open, read and write keep one path
// identity regardless of which machine is active.
function _groupRemoteSearchHits(root, query, caseSensitive, hits) {
  const base = _normalizeFsPath(String(root || "")).replace(/\/+$/, "");
  const groups = new Map();
  let fallbackRegex = null;
  try { fallbackRegex = new RegExp(String(query || ""), caseSensitive ? "" : "i"); }
  catch { try { fallbackRegex = new RegExp(String(query || "").replace(/[.*+?^${}()|[\]\\]/g, "\\$&"), caseSensitive ? "" : "i"); } catch {} }
  for (const hit of Array.isArray(hits) ? hits : []) {
    const rel = _normalizeFsPath(String(hit?.rel || "")).replace(/^\/+/, "");
    if (!rel) continue;
    let group = groups.get(rel);
    if (!group) {
      group = {
        path: _coherentFilePath(String(hit?.path || "") || (base ? base + "/" + rel : rel)),
        name: rel.split("/").pop() || rel,
        rel,
        matches: [],
      };
      groups.set(rel, group);
    }
    const text = String(hit?.text || "");
    const fallback = fallbackRegex ? fallbackRegex.exec(text) : null;
    if (fallbackRegex) fallbackRegex.lastIndex = 0;
    const start = Number.isFinite(hit?.start) ? Math.max(0, Math.floor(hit.start)) : Math.max(0, fallback?.index || 0);
    const fallbackLength = fallback?.[0]?.length || String(query || "").length;
    const end = Number.isFinite(hit?.end) ? Math.max(start, Math.floor(hit.end)) : start + fallbackLength;
    group.matches.push({
      line: Number.isFinite(hit?.line) ? Math.max(1, Math.floor(hit.line)) : 1,
      column: Number.isFinite(hit?.column) ? Math.max(1, Math.floor(hit.column)) : start + 1,
      text,
      start,
      end,
    });
  }
  return [...groups.values()].sort((a, b) => a.rel.localeCompare(b.rel));
}

// Route the core file ops to the remote daemon when connected (else local backend).
{
  const _local = {
    readDir: backend.readDir, readTextFile: backend.readTextFile, readLogTail: backend.readLogTail, writeTextFile: backend.writeTextFile,
    writeTextFileIfUnchanged: backend.writeTextFileIfUnchanged,
    createFile: backend.createFile, createDir: backend.createDir, copyPath: backend.copyPath, renamePath: backend.renamePath,
    deletePath: backend.deletePath, deleteTextFileIfUnchanged: backend.deleteTextFileIfUnchanged,
    searchInProject: backend.searchInProject,
  };
  backend.readDir = (p) => _remote.active
    ? _remoteCall("/fs/list", { path: p }).then((j) => (j.entries || []).map((e) => ({
      name: e.name,
      path: _normalizeFsPath(String(p || "").replace(/\/+$/, "") + "/" + e.name),
      is_dir: e.is_dir,
      size: e.size,
    })))
    : _local.readDir(p);
  backend.readTextFile = (p) => _remote.active ? _remoteCall("/fs/read", { path: p }).then((j) => j.content || "") : _local.readTextFile(p);
  backend.readLogTail = (p, lines = 200, maxBytes = null) => _remote.active
    ? _remoteCall("/fs/read", { path: p }).then((j) => _tailText(j.content || "", lines))
    : _local.readLogTail(p, lines, maxBytes);
  backend.writeTextFile = (p, c) => _remote.active ? _remoteCall("/fs/write", { path: p, content: c }) : _local.writeTextFile(p, c);
  backend.writeTextFileIfUnchanged = (p, expectedContent, c) => _remote.active
    ? _remoteCall("/fs/write", { path: p, expected_content: expectedContent, content: c })
    : _local.writeTextFileIfUnchanged(p, expectedContent, c);
  backend.deleteTextFileIfUnchanged = (p, expectedContent) => _remote.active
    ? _remoteCall("/fs/delete", { path: p, expected_content: expectedContent })
    : _local.deleteTextFileIfUnchanged(p, expectedContent);
  backend.createFile = (p) => _remote.active ? _remoteCall("/fs/write", { path: p, expected_content: null, content: "" }) : _local.createFile(p);
  backend.createDir = (p) => _remote.active ? _remoteCall("/fs/mkdir", { path: p }) : _local.createDir(p);
  backend.copyPath = (from, to) => _remote.active ? _remoteCall("/fs/copy", { from, to }) : _local.copyPath(from, to);
  // 远程/网页壳没有这两个原生命令：类型探测退回「读得动就是目录」，导入退回普通复制。
  backend.pathKinds = (paths) => (_local.pathKinds ? _local.pathKinds(paths)
    : Promise.all((paths || []).map((p) => backend.readDir(p).then(() => 2).catch(() => 1))));
  backend.importPath = (from, to) => (_local.importPath ? _local.importPath(from, to) : backend.copyPath(from, to));
  backend.renamePath = (from, to) => _remote.active ? _remoteCall("/fs/rename", { from, to }) : _local.renamePath(from, to);
  backend.deletePath = (p) => _remote.active ? _remoteCall("/fs/delete", { path: p }) : _local.deletePath(p);
  backend.searchInProject = (root, query, cs, mode = "literal") => _remote.active
    ? _remoteCall("/fs/search", { root, query, case_sensitive: cs, mode }).then((j) => {
      // 截断信息也要带出来。本地那条把 truncated / scannedFiles 挂在数组对象上
      // （见 _local.searchInProject 的注释），远程这条原来只 return 一个纯数组——
      // 于是 _backendTruncated 恒 false、_scannedFiles 恒 0，「**这次没搜完**」那句话
      // 在远程工作区上一次都不会出现。后果就是那边注释写的假阴性：模型把一个任意
      // 子集当成全部，「所有调用点都改掉」只改了前面几十处。
      // 远端没报这两个字段时挂 undefined，让回执能区分「没截断」和「不知道」。
      const _hits = _groupRemoteSearchHits(root, query, cs, j.hits);
      _hits.truncated = !!j?.truncated;
      _hits.scannedFiles = Number.isFinite(Number(j?.scanned_files)) ? Number(j.scanned_files)
        : Number.isFinite(Number(j?.scannedFiles)) ? Number(j.scannedFiles) : undefined;
      _hits.scanScopeUnknown = _hits.scannedFiles === undefined;
      return _hits;
    })
    : _local.searchInProject(root, query, cs, mode);
}

// Reap any backend processes (shells / LSP servers / debug adapters) orphaned by
// a previous page session — runs before this session starts any of its own, so a
// webview reload no longer piles up zombie processes that eventually freeze the IDE.
// Fire-and-forget — do NOT `await`. This is a top-level await in an ES module, so
// awaiting it SUSPENDS evaluation of the entire rest of main.js (Monaco creation, all
// UI wiring, restoreSession at the bottom) until the IPC returns. cleanup_stale reaps
// orphaned shells/LSP/debug children with a blocking child.wait() per process; on a
// webview reload with heavy language servers that took seconds → the window "opened
// frozen". Letting it run in the background unblocks first paint immediately.
// 只有主窗口做这件事。cleanup_stale 收的是**进程级**的孤儿（终端、LSP、调试子进程），
// 它不区分这些东西属于哪个窗口 —— 副窗口一开（或 webview 一 reload）就会把主窗口正在用
// 的终端、语言服务器、调试会话全部杀掉。"reload 后收尸"的原意只在单窗口场景成立。
if (inTauri && !_isSecondaryWindow) {
  Promise.resolve().then(() => backend.invoke("cleanup_stale")).catch(() => { /* older backend without the command */ });
}

// Real LSP client manager (wired up after the workspace state exists below).
let lspManager = null;
// Debug Adapter Protocol manager (wired up alongside the LSP manager below).
let dapManager = null;
// Cached debug launch configurations discovered from launch.json (null = unloaded).
let _launchConfigsCache = null;

// Central backend base URL (overridable via localStorage michael_api).
function _michaelBase() {
  return (localStorage.getItem("michael_api") || (inTauri ? "https://code.mrday.one" : window.location.origin)).replace(/\/+$/, "");
}
/*
 * A stable name for this install, so Devices lists machines rather than sign-ins.
 *
 * Random, stored once, and not derived from anything about the computer. The server uses
 * it only to group rows and to replace this device's previous session when you sign in
 * again; it grants nothing.
 */
function _michaelDeviceId() {
  const KEY = "mrday.device_id";
  try {
    const saved = localStorage.getItem(KEY);
    if (saved) return saved;
  } catch (_) {}
  let id;
  try {
    id = crypto.randomUUID();
  } catch (_) {
    const b = new Uint8Array(16);
    crypto.getRandomValues(b);
    id = Array.from(b, (x) => x.toString(16).padStart(2, "0")).join("");
  }
  try { localStorage.setItem(KEY, id); } catch (_) {}
  return id;
}

// POST to the central auth API; returns a _finishLogin-shaped result.
//
// `device` is sent because the server cannot work this out on its own: a Tauri window
// reports the system webview's User-Agent, which is indistinguishable from Safari, so
// without the hint every desktop sign-in was filed as a browser. The same bundle also
// runs in a plain browser during development, and there it is honestly "web".
/**
 * 从本地取出待用的邀请码。
 *
 * 「点邀请链接 → 下载 App → 在 App 里注册」这条路以前整条丢失推荐关系：注册接口不收邀请码，
 * App 也从没读过这个键，而事后绑定那条路只存在于网页控制台里。桌面端和 gate 共用同一个域，
 * 所以 gate 存下的那份在这里读得到。
 */
function _michaelPendingRef() {
  let v = "";
  try { v = localStorage.getItem("mide_ref") || ""; } catch (_) {}
  if (!v) {
    try {
      const m = document.cookie.match(/(?:^|;\s*)mide_ref=([^;]+)/);
      v = m ? decodeURIComponent(m[1]) : "";
    } catch (_) {}
  }
  return /^[2-9A-HJ-NP-Z]{6,12}$/.test(v) ? v : "";
}

async function _michaelAuth(path, body) {
  // 只在注册时带上：登录不该改变一个已有账号的推荐关系，那正是产品规则要挡的事。
  const ref = path === "register" ? _michaelPendingRef() : "";
  const r = await fetch(_michaelBase() + "/api/auth/" + path, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      ...body,
      ...(ref ? { referral_code: ref } : {}),
      device: inTauri ? "desktop" : "web",
      device_id: _michaelDeviceId(),
    }),
  });
  const j = await r.json().catch(() => ({}));
  if (!r.ok) throw new Error(j.error || "操作失败");
  try { if (j.token) localStorage.setItem("michael_token", j.token); } catch (_) {}
  // 绑上了就把码清掉，别在下一个账号上再用一次。
  if (j.referred_by) {
    try { localStorage.removeItem("mide_ref"); } catch (_) {}
    try { document.cookie = "mide_ref=; Path=/; Max-Age=0; SameSite=Lax; Secure"; } catch (_) {}
  }
  return { success: true, message: "成功", email: body.email, token: j.token, user: j.user };
}

async function tauriBackend() {
  const core = await import("@tauri-apps/api/core");
  const dialog = await import("@tauri-apps/plugin-dialog");
  const opener = await import("@tauri-apps/plugin-opener");
  return {
    registerWorkspaceRoot: (path) => core.invoke("register_workspace_root", { path }),
    createProjectDir: (name) => core.invoke("create_project_dir", { name }),
    // Local-file URL for the webview (image / pdf preview) via the asset protocol.
    assetUrl: (p) => { try { return core.convertFileSrc(p); } catch { return p; } },
    readDir: async (path) => { const es = await core.invoke("read_dir", { path }); return Array.isArray(es) ? es.map((e) => (e && typeof e.path === "string" ? { ...e, path: _toPosix(e.path) } : e)) : es; },
    readTextFile: (path) => core.invoke("read_text_file", { path }),
    conversationSnapshotSave: (snapshot) => core.invoke("conversation_snapshot_save", { snapshot }),
    conversationSnapshotLoad: () => core.invoke("conversation_snapshot_load"),
    // 全部会话的轻量清单（只给 /sessions 列表用，不含 recent/transcript）。
    // 快照里的 closedSessions 在 Rust 侧封顶 200、前端又 slice(0,80)，关掉的会话过一阵
    // 就从清单里消失——而 conversation_sessions 表永不删除，这条路能看到全部。
    conversationSessionsIndex: () => core.invoke("conversation_sessions_index"),
    conversationSessionLoad: (sessionId) => core.invoke("conversation_session_load", { sessionId }),
    conversationTranscriptAppend: (session, message, sequence) => core.invoke("conversation_transcript_append", { session, message, sequence }),
    conversationTranscriptLoad: (sessionId) => core.invoke("conversation_transcript_load", { sessionId }),
    conversationTranscriptWindow: (sessionId, start, limit) => core.invoke("conversation_transcript_window", { sessionId, start, limit }),
    conversationTranscriptContentSlice: (sessionId, sequence, offset, limit) => core.invoke("conversation_transcript_content_slice", { sessionId, sequence, offset, limit }),
    conversationTranscriptTruncate: (sessionId, length) => core.invoke("conversation_transcript_truncate", { sessionId, length }),
    readLogTail: (path, lines = 200, maxBytes = null) => core.invoke("read_log_tail", { path, lines, maxBytes }),
    readFileDataUrl: (path) => core.invoke("read_file_data_url", { path }),
    inspectFile: (path, maxBytes = null) => core.invoke("inspect_file", { path, maxBytes }),
    reverseGeocodeCoordinates: (latitude, longitude, language) => core.invoke("reverse_geocode_coordinates", { latitude, longitude, language }),
    writeTextFile: (path, content) => core.invoke("write_text_file", { path, content }),
    writeTextFileIfUnchanged: (path, expectedContent, content) => core.invoke("write_text_file_if_unchanged", { path, expectedContent, content }),
    deleteTextFileIfUnchanged: (path, expectedContent) => core.invoke("delete_text_file_if_unchanged", { path, expectedContent }),
    // 同一个对象里 readDir / searchInProject 都过了 _toPosix，只有这一行漏了。
    // 后端 home_dir() 读的是 HOME 或 USERPROFILE，Windows 上只有后者、值是
    // `C:\Users\张三`（反斜杠）。原样存进 _cachedHomeDir 之后，_resolveRel 拼出
    // `C:\Users\张三/skills/x.md`，而那条判「是不是绝对路径」的正则要求冒号后面是
    // **正斜杠** —— 判据为假，整串被当成相对路径去拼工作区根。模型写 `~/…` 存技能
    // 会以一条难懂的 OS 错误失败。
    homeDir: async () => _toPosix(await core.invoke("home_dir")),
    createFile: (path) => core.invoke("create_file", { path }),
    createDir: (path) => core.invoke("create_dir", { path }),
    copyPath: (from, to) => core.invoke("copy_path", { from, to }),
    // 拖放导入专用：pathKinds 是 O(1) 的 stat（不像 read_dir 要枚举整个目录），
    // importPath 允许源在工作区外（用户拖进来的东西按定义就在外面），写入侧照旧受限。
    pathKinds: (paths) => core.invoke("path_kinds", { paths }),
    importPath: (from, to) => core.invoke("import_path", { from, to }),
    renamePath: (from, to) => core.invoke("rename_path", { from, to }),
    deletePath: (path) => core.invoke("delete_path", { path }),
    searchInProject: async (root, query, caseSensitive, mode = "literal") => {
      const raw = await core.invoke("search_in_project", { root, query, caseSensitive, mode });
      // 后端现在回的是 { files, scanned_files, truncated }。这里摊回数组，既有调用方
      // （UI 两处、智能体工具执行器、知识库检索）一行都不用改；截断信息挂在数组对象上
      // ——数组也是对象，`Array.isArray` 仍为真、`.length`/`.map` 全照旧。
      //
      // 为什么非要把 truncated 带出来：遍历会在 2000 条命中或 20000 个文件处 break，
      // 在此之前这个事实没有出口，「搜完了」和「没搜完」返回的东西一模一样。大仓里
      // 就会出现**假阴性**——符号明明在，界面说没有。
      const results = Array.isArray(raw) ? raw : (raw?.files ?? []);
      const mapped = results.map((result) =>
        result && typeof result.path === "string" ? { ...result, path: _toPosix(result.path) } : result);
      mapped.truncated = !Array.isArray(raw) && !!raw?.truncated;
      mapped.scannedFiles = Array.isArray(raw) ? undefined : raw?.scanned_files;
      return mapped;
    },
    gitStatus: (root) => core.invoke("git_status", { root }),
    gitWorktreeAdd: (root, name) => core.invoke("git_worktree_add", { root, name }),
    gitWorktreeList: (root) => core.invoke("git_worktree_list", { root }),
    gitWorktreeRemove: (root, path) => core.invoke("git_worktree_remove", { root, path }),
    gitFileHead: (root, rel) => core.invoke("git_file_head", { root, rel }),
    gitStage: (root, rel) => core.invoke("git_stage", { root, rel }),
    gitUnstage: (root, rel) => core.invoke("git_unstage", { root, rel }),
    gitStageAll: (root) => core.invoke("git_stage_all", { root }),
    gitUnstageAll: (root) => core.invoke("git_unstage_all", { root }),
    gitCommit: (root, message) => core.invoke("git_commit", { root, message }),
    gitPush: (root) => core.invoke("git_push", { root }),
    gitClone: (source, target) => core.invoke("git_clone", { source, target }),
    gitBranches: (root) => core.invoke("git_branches", { root }),
    gitCheckout: (root, branch, create) => core.invoke("git_checkout", { root, branch, create }),
    gitPull: (root) => core.invoke("git_pull", { root }),
    gitLog: (root, count, all) => core.invoke("git_log", { root, count, all: all ?? null }),
    gitFileLog: (root, rel, count) => core.invoke("git_file_log", { root, rel, count }),
    gitFileAt: (root, rel, rev) => core.invoke("git_file_at", { root, rel, rev }),
    uiDiff: (target, candidate) => core.invoke("ui_diff", { target, candidate }),
    browserExtractUi: (maxNodes) => core.invoke("browser_extract_ui", { maxNodes }),
    gitConflicts: (root) => core.invoke("git_conflicts", { root }),
    gitMergeVersions: (root, rel) => core.invoke("git_merge_versions", { root, rel }),
    gitResolveConflict: (root, rel, resolution) =>
      core.invoke("git_resolve_conflict", { root, rel, resolution }),
    lspList: () => core.invoke("lsp_list"),
    lspStart: (config, onEvent) => {
      const channel = new core.Channel();
      channel.onmessage = onEvent;
      return core.invoke("lsp_start", { config, onEvent: channel });
    },
    lspSend: (lang, message) => core.invoke("lsp_send", { lang, message }),
    lspStop: (lang) => core.invoke("lsp_stop", { lang }),
    // 作用域要和 lsp_start 一致：否则装在项目 node_modules/.bin 里的语言服务器
    // 启动得起来、这里却判「没装」，那张安装进度卡会每 2.5 秒问一次、转满 90 秒
    // 然后告诉用户「安装超时」——而他明明装成功了。
    lspCheckAvailable: (lang) => core.invoke("lsp_check_available", {
      lang,
      workspace: (workspaceRoots && workspaceRoots[0]) || rootPath || null,
      trustWorkspaceBinaries: isWorkspaceTrusted(),
    }),
    // 「这台机器上有没有这个命令」——两个平台同一套判据。前端不要再拼 `command -v`：
    // cmd 没有那个内建，返回 9009，于是 Windows 上答案永远是没有。
    whichCommand: (name, workspace) => core.invoke("which_command", { name, workspace: workspace || null }),
    writeTmpFile: (name, content) => core.invoke("write_tmp_file", { name, content }),
    /*
     * 这四条「取环境符号」的路会**在工作区里执行东西**：detect_python 直接跑
     * `<工作区>/.venv/bin/python`，node 那条 require() 工作区 node_modules 里的包
     * （等于跑它的顶层代码）。lsp_start 早就按工作区信任分了，这四条一直没有——
     * clone 一个别人的仓库、点开任意 .py/.ts 文件，仓库自带的可执行文件就跑起来了。
     *
     * 信任状态在**这一层**统一带上，不是在每个调用点：调用点有六处，漏一处这道门就是
     * 虚的。后端缺省 fail closed，所以这里传错方向只会让功能降级，不会让门失效。
     */
    lspDetectPython: (workspace) => core.invoke("lsp_detect_python", { workspace: workspace || null, trustWorkspaceBinaries: isWorkspaceTrusted() }),
    // 必须和 lsp_detect_python 用**同一个解释器**：那边把工作区 venv 的解释器交给了
    // pyright，这边如果还跑系统 python3，同一个编辑器里就会出现两套互相矛盾的
    // 「这个包存不存在」——pyright 认得项目里 pip 装的 requests，而补全一片空白。
    lspPythonEnvSymbols: (modules) => core.invoke("lsp_python_env_symbols", {
      modules,
      workspace: (workspaceRoots && workspaceRoots[0]) || rootPath || null,
      trustWorkspaceBinaries: isWorkspaceTrusted(),
    }),
    lspNodeEnvSymbols: (projectDir, modules) => core.invoke("lsp_node_env_symbols", { projectDir, modules, trustWorkspaceBinaries: isWorkspaceTrusted() }),
    // 抓包 (MITM capture proxy, mitmproxy-backed)
    proxyAvailable: () => core.invoke("proxy_available"),
    proxyStatus: () => core.invoke("proxy_status"),
    proxyStart: (port, onFlow) => {
      const channel = new core.Channel();
      channel.onmessage = onFlow;
      return core.invoke("proxy_start", { port, onFlow: channel });
    },
    proxyStop: () => core.invoke("proxy_stop"),
    proxyCaPath: () => core.invoke("proxy_ca_path"),
    proxySetSystemProxy: (enable, port) => core.invoke("proxy_set_system_proxy", { enable, port }),
    lspGoEnvSymbols: (projectDir) => core.invoke("lsp_go_env_symbols", { projectDir, trustWorkspaceBinaries: isWorkspaceTrusted() }),
    lspLangEnvSymbols: (lang, projectDir, modules) => core.invoke("lsp_lang_env_symbols", { lang, projectDir, modules, trustWorkspaceBinaries: isWorkspaceTrusted() }),
    dapList: () => core.invoke("dap_list"),
    dapStart: (config, onEvent) => {
      const channel = new core.Channel();
      channel.onmessage = onEvent;
      return core.invoke("dap_start", { config, onEvent: channel });
    },
    dapSend: (adapterId, message) => core.invoke("dap_send", { adapterId, message }),
    dapStop: (adapterId) => core.invoke("dap_stop", { adapterId }),
    marketplaceList: () => core.invoke("marketplace_list"),
    marketplaceSearch: (query) => core.invoke("marketplace_search", { query }),
    marketplaceInstall: (entry) => core.invoke("marketplace_install", { entry }),
    // dbMarketplaceList / dbMarketplaceUpsert 已删：这两个包装自己零调用点，
    // 而它们指向的 Rust 命令也随本机 auth.db 那套一起摘掉了（扩展列表现在走
    // ext_available_builtin，读的是真实内置扩展）。
    tasksList: (root) => core.invoke("tasks_list", { root }),
    // `sandbox` defaults to ON in Rust. Pass false ONLY for a user-approved escape after a
    // confined attempt was refused; IDE-internal probes (version checks, git plumbing) pass
    // nothing and stay confined like everything else.
    taskRunCapture: (cwd, command, options = {}) => core.invoke("task_run_capture", {
      cwd,
      command,
      timeoutSecs: options.timeoutSecs || null,
      sandbox: options.sandbox === false ? false : null,
    }),
    automationCall: (method, params) => core.invoke("automation_call", { method, params: params || {} }),
    pickFolder: () => dialog.open({ directory: true, multiple: false }),
    openUrl: (url) => opener.openUrl(url),
    revealItemInDir: (path) => opener.revealItemInDir(path),
    extractArchive: (path, dest, budget) => core.invoke("extract_archive", { path, dest, budget: budget ?? null }),
    readTableFile: (path, maxRows) => core.invoke("read_table_file", { path, maxRows: maxRows ?? null }),
    listRepositories: (kind, token) => core.invoke("list_repositories", { kind, token }),
    readArchiveEntry: (path, entry, maxBytes) =>
      core.invoke("read_archive_entry", { path, entry, maxBytes: maxBytes ?? null }),
    aiChat: (config, messages, onEvent) => {
      const channel = new core.Channel();
      channel.onmessage = onEvent;
      const p = core.invoke("ai_chat", { config: _stampPowerRoute(config), messages, onEvent: channel });
      // Tauri keeps Channel callbacks after invoke resolves. Replace this turn's
      // capture with a sink, rather than null, because a final event may be queued.
      const _free = () => _releaseTauriChannel(channel);
      p.then(_free, _free);
      return p;
    },
    aiChatWithTools: (config, messages, tools, onEvent) => {
      const channel = new core.Channel();
      channel.onmessage = onEvent;
      const p = core.invoke("ai_chat_with_tools", { config: _stampPowerRoute(config), messages, tools, onEvent: channel });
      const _free = () => _releaseTauriChannel(channel); // see aiChat
      p.then(_free, _free);
      return p;
    },
    aiComplete: (config, messages, maxTokens) =>
      core.invoke("ai_complete", { config: _stampPowerRoute(config), messages, maxTokens }),
    cancelAi: (requestId) => { try { return core.invoke("cancel_ai", { requestId }); } catch { return Promise.resolve(); } },
    termOpen: async (opts, onEvent) => {
      const channel = new core.Channel();
      channel.onmessage = onEvent;
      const id = await core.invoke("term_open", {
        cwd: opts.cwd ?? null,
        cols: opts.cols,
        rows: opts.rows,
        onEvent: channel,
      });
      // Return the channel too: closeTermTab replaces its callback with a sink so
      // captured xterm state can be collected without crashing on late PTY output.
      return { id, channel };
    },
    termWrite: (id, data) => core.invoke("term_write", { id, data }),
    termResize: (id, cols, rows) => core.invoke("term_resize", { id, cols, rows }),
    termClose: (id) => core.invoke("term_close", { id }),
    termRunningIds: () => core.invoke("term_running_ids"),
    termListCommands: () => core.invoke("term_list_commands"),
    termHistory: () => core.invoke("term_history"),
    envRefresh: () => core.invoke("env_refresh"),
    shellPlan: () => core.invoke("shell_plan"),
    fsWatch: (paths) => core.invoke("fs_watch", { paths }),
    fsUnwatch: (paths) => core.invoke("fs_unwatch", { paths }),
    replaceInFile: (filePath, query, replacement, caseSensitive) =>
      core.invoke("replace_in_file", { filePath, query, replacement, caseSensitive }),
    replaceInProject: (root, query, replacement, caseSensitive) =>
      core.invoke("replace_in_project", { root, query, replacement, caseSensitive }),
    gitStash: (root) => core.invoke("git_stash", { root }),
    gitStashPop: (root, index) => core.invoke("git_stash_pop", { root, index: index ?? null }),
    gitStashApply: (root, index) => core.invoke("git_stash_apply", { root, index }),
    gitStashDrop: (root, index) => core.invoke("git_stash_drop", { root, index }),
    gitStashList: (root) => core.invoke("git_stash_list", { root }),
    gitBlame: (root, rel) => core.invoke("git_blame", { root, rel }),
    // Auth goes through the central backend (Brevo email + unified accounts/credits),
    // NOT the local SQLite + QQ-SMTP path (which couldn't send codes).
    authLoginOrRegister: (email, password) => _michaelAuth("login", { email, password }),
    authLogin: (email, password) => _michaelAuth("login", { email, password }),
    authRegister: (email, password, code) => _michaelAuth("register", { email, password, code }),
    authCheckEmail: async (email) => {
      const r = await fetch(_michaelBase() + "/api/auth/check-email", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ email }) });
      const j = await r.json().catch(() => ({}));
      if (!r.ok) throw new Error(j.error || "检测邮箱失败");
      return !!j.exists;
    },
    authSendCode: async (email) => {
      const r = await fetch(_michaelBase() + "/api/auth/send-code", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ email }) });
      const j = await r.json().catch(() => ({}));
      if (!r.ok) throw new Error(j.error || "发送验证码失败");
      return j.message || "验证码已发送到邮箱（请查收，含垃圾箱）";
    },
    authVerifyCode: (email, code) => _michaelAuth("verify-code", { email, code }),
    invoke: (cmd, args) => core.invoke(cmd, args || {}),
  };
}

const _AI_MODEL_RETRY_LIMIT = 4;
// 产出前的瞬时线路失败（5xx/网络抖动）一轮里最多重试几次——**默认值**，真正生效的是
// boundedRetryLimit 里 min(10,…) 的调用方入参。以前默认 10：配上下面的退避，一次坏线路
// 会连打 10 次、拖住小半分钟才交还用户；而真正短暂的抖动 3-4 次内就恢复，连 4 次都不恢复
// 基本就是线路真不通，继续重发只是把同一个失败拖长、还在给已经在喘的上游加压。限流(429)
// 与已产出后的续传各走独立预算，不受这个数影响。
// 一轮里最多从断点续几次。给得少是故意的：连着断三次说明线路真的不通，
// 这时候继续续传只是把同一个失败拖长，不如把话说清楚交还给用户。
const _AI_MODEL_RESUME_LIMIT = 3;
/// 两次重试之间的间隔。
///
/// 以前是 0 —— `attemptIndex += 1; continue;` 中间什么都不等，10 次背靠背立刻重发。
/// 上游正忙不过来的时候，这等于对着一个已经在喘的服务连打十拳：网关日志里那种
/// "同一个请求 id 每两秒重来一次、连打六小时"就是这么来的（那两秒还只是请求本身的往返，
/// 不是我们在等）。间隔本身就是治疗——给上游喘一口的时间，比立刻重试更可能成功。
const _AI_MODEL_RETRY_DELAY_MS = 2_000;
/// 退避封顶：指数退避 base = DELAY × 2^n 增长，但单次等待不超过这个数。
const _AI_MODEL_RETRY_BACKOFF_CAP_MS = 30_000;
/// 撞限流时"等一会儿再来"的次数与起步退避。
///
/// 限流**不能**并进普通重试集合——见 _isRateLimitedAiError 上面那段：它每发一次都带完整
/// 上下文，既加深限流又实打实烧配额，历史上出过 25 秒 18 发的请求风暴。那条保护不动。
///
/// 但"直接判死"也不对：用户看到红字之后会自己发「继续」，那其实就是一次重试——只是来得
/// 更快（没有任何退避）、更贵（整轮从头再来）。所以给限流一条**独立的、预算极小、退避很长**
/// 的路：2 次，15 秒起步、逐次加倍，最长 60 秒。物理上造不出风暴，而绝大多数限流在这个
/// 时间尺度上已经放开了。
const _AI_MODEL_RATE_LIMIT_WAITS = 2;
const _AI_MODEL_RATE_LIMIT_DELAY_MS = 15_000;
const _AI_MODEL_ATTEMPT_TIMEOUT_MS = 60_000;
const _AI_RESPONSE_HEADERS_DEADLINE_MS = _AI_MODEL_ATTEMPT_TIMEOUT_MS;
const _AI_ERROR_BODY_DEADLINE_MS = 2_000;
const _AI_ERROR_BODY_MAX_BYTES = 64 * 1024;
const _AI_INCOMPLETE_STREAM_ERROR = "AI stream closed before data: [DONE]（连接提前结束）；响应可能被截断。";
const _GATEWAY_SETTLEMENT_TOTAL_DEADLINE_MS = 2_500;
const _GATEWAY_SETTLEMENT_FETCH_DEADLINE_MS = 1_200;

function _responseHeadersDeadlineError(budgetMs, elapsedMs = budgetMs) {
  const elapsed = Math.max(0, Math.min(Number(elapsedMs) || 0, Number(budgetMs) || 0));
  return new Error(`AI request timed out waiting for response headers after ${(elapsed / 1000).toFixed(1).replace(/\.0$/, "")} seconds (per-attempt ${Math.round(budgetMs / 1000)}-second deadline)`);
}

async function _readAiErrorResponseText(response, timeoutMs = _AI_ERROR_BODY_DEADLINE_MS, onTimeout = () => {}, maxBytes = _AI_ERROR_BODY_MAX_BYTES) {
  let timer = null;
  try {
    return await Promise.race([
      (async () => {
        if (!response?.body?.getReader) return String(await response.text()).slice(0, maxBytes);
        const reader = response.body.getReader();
        const chunks = [];
        let total = 0;
        for (;;) {
          const { done, value } = await reader.read();
          if (done) break;
          const bytes = value instanceof Uint8Array ? value : new Uint8Array(value || []);
          const remaining = Math.max(0, maxBytes - total);
          if (bytes.length > remaining) {
            if (remaining) chunks.push(bytes.subarray(0, remaining));
            total += remaining;
            try { await reader.cancel(); } catch {}
            break;
          }
          chunks.push(bytes);
          total += bytes.length;
          if (total >= maxBytes) {
            try { await reader.cancel(); } catch {}
            break;
          }
        }
        const merged = new Uint8Array(total);
        let offset = 0;
        for (const chunk of chunks) { merged.set(chunk, offset); offset += chunk.length; }
        return new TextDecoder().decode(merged);
      })(),
      new Promise((_, reject) => {
        timer = setTimeout(() => {
          try { onTimeout(); } catch {}
          reject(new Error(`AI error response body timed out after ${Math.round(timeoutMs / 1000)} seconds`));
        }, timeoutMs);
      }),
    ]);
  } finally {
    if (timer) clearTimeout(timer);
  }
}

function _browserAiStreamTimeouts(config = {}) {
  const effort = String(config.reasoningEffort || config.thinkingEffort || "").toLowerCase();
  const deep = effort === "max" || effort === "xhigh" || Number(config.thinkingBudget) > 0;
  if (deep) return { firstProgressMs: _AI_MODEL_ATTEMPT_TIMEOUT_MS, emptyStreamMs: _AI_MODEL_ATTEMPT_TIMEOUT_MS, stallMs: 120_000 };
  // `adaptive` is the only thinking shape modern Claude accepts (4.7+/5/Fable/Mythos reject
  // `enabled`+budget_tokens outright). Every tier now gets the same 60s pre-progress window;
  // only a stall after real output keeps the longer thinking-specific budget.
  const thinkingOn = config.thinking?.type === "enabled" || config.thinking?.type === "adaptive";
  const high = effort === "high" || thinkingOn || !!config.thinkingConfig;
  if (high) return { firstProgressMs: _AI_MODEL_ATTEMPT_TIMEOUT_MS, emptyStreamMs: _AI_MODEL_ATTEMPT_TIMEOUT_MS, stallMs: 90_000 };
  return { firstProgressMs: _AI_MODEL_ATTEMPT_TIMEOUT_MS, emptyStreamMs: _AI_MODEL_ATTEMPT_TIMEOUT_MS, stallMs: 60_000 };
}

// One browser fetch is one physical attempt. Retry ownership lives in
// _runModelRequestWithRetry so browser, desktop Chat, and Agent all follow the
// same rule without multiplying retries inside the transport or gateway.
async function _postAiOnce(post, body, options = {}) {
  if (options.signal?.aborted) throw new Error("AI request cancelled");
  return post(body);
}

const _browserAiControllers = new Map();

// Real AI over fetch+SSE for the BROWSER build (the desktop app streams via a
// Tauri Channel instead). Lets the hosted web demo show genuine agent behaviour
// (streaming, tool calls, live code-writing) against the central gateway — only
// the filesystem/terminal stay mocked, since a browser can't touch local files.
async function _realAiFetch(config, messages, tools, onEvent) {
  const turnController = typeof AbortController !== "undefined" ? new AbortController() : null;
  const requestId = String(config?.requestId || "");
  const cancelId = String(config?.cancelId || requestId);
  let activeAttemptController = null;
  if (cancelId && turnController) _browserAiControllers.set(cancelId, turnController);
  if (turnController) turnController.signal.addEventListener("abort", () => activeAttemptController?.abort(), { once: true });
  try {
    const streamStarted = Date.now();
    const streamMetric = (phase, extra = {}) => {
      try { onEvent({ kind: "streamMetric", phase, elapsedMs: Date.now() - streamStarted, ...extra }); } catch {}
    };
    streamMetric("requestStarted");
    let key = config.apiKey;
    const isGateway = _isGatewayConfig(config);
    // 网页构建没有 Rust 那条协议分叉：下面的请求体、端点、鉴权头全是 OpenAI 形状，而且
    // 浏览器直连 api.anthropic.com 还会被 CORS 挡。这里只能失败 —— 但要说清为什么，
    // 而不是让它去打一个错端点换回一句看不懂的 404/网络错误。
    const _proto = cmProtocol(config.protocol);
    if (_proto !== "openai") {
      const _msg = `「${CM_PROTOCOL_UI[_proto].label}」协议只在桌面版可用。请把这条自定义模型改成 OpenAI 兼容协议，或改用桌面版。`;
      try { onEvent({ kind: "error", message: _msg }); } catch {}
      throw new Error(_msg);
    }
    if (!key && isGateway) {
      // /api/ide-key now requires login (returns THIS user's own key) — pass the JWT.
      try { const tok = (typeof localStorage !== "undefined" && localStorage.getItem("michael_token")) || ""; const r = await fetch(config.baseUrl + "/api/ide-key", { headers: tok ? { Authorization: "Bearer " + tok } : {}, signal: turnController?.signal }); key = (await r.json()).api_key; } catch {}
    }
    const payload = { model: config.model, messages, stream: true, stream_options: { include_usage: true } };
    if (tools && tools.length) payload.tools = tools;
    if (config.reasoningEffort) payload.reasoning_effort = config.reasoningEffort;
    if (config.thinkingBudget) payload.thinking_budget = config.thinkingBudget;
    if (config.thinking && typeof config.thinking === "object") payload.thinking = config.thinking;
    if (config.thinkingConfig && typeof config.thinkingConfig === "object") payload.thinking_config = config.thinkingConfig;
    if (config.mcPrefix) payload.mc_prefix = String(config.mcPrefix);
    if (Number.isInteger(config.mcPrefixCovered) && config.mcPrefixCovered > 0) {
      payload.mc_prefix_covered = config.mcPrefixCovered;
    }
    // Relay the L0 server-side-assembly headers exactly like ai.rs::with_ide_headers does
    // for the desktop. The agent turn STRIPS the local system prompt + static tool schemas
    // whenever L0 is on — without these headers nobody re-injects them on the web build,
    // leaving the agent prompt-less and tool-less.
    const _h = { "Content-Type": "application/json", Authorization: "Bearer " + (key || "") };
    if (config.idePowerRoute === true) _h["x-ide-power-route"] = "1";
    if (Number.isFinite(Number(config.ideContextWindow)) && Number(config.ideContextWindow) >= 1000) {
      _h["x-ide-context-window"] = String(Math.round(Number(config.ideContextWindow)));
    }
    if (config.ideMode) _h["x-ide-mode"] = String(config.ideMode);
    if (config.ideTools) _h["x-ide-tools"] = String(config.ideTools);
    if (config.ideSemanticProfile) _h["x-ide-semantic-profile"] = String(config.ideSemanticProfile).slice(0, 1024);
    // 会话开场那句。HTTP 头只能是 ASCII，中文必须编码 —— 用 base64(UTF-8)，网关那边同解。
    if (config.ideSessionGoal) {
      try {
        _h["x-ide-session-goal"] = btoa(String.fromCharCode(...new TextEncoder().encode(String(config.ideSessionGoal).slice(0, 4000)))).slice(0, 8192);
      } catch { /* 编不动就不发，网关自己有兜底 */ }
    }
    if (config.requestId) _h["x-ide-request-id"] = String(config.requestId).slice(0, 128);
    if (/^[-_A-Za-z0-9]{8,128}$/.test(String(config.ideRunId || ""))) _h["x-ide-run-id"] = String(config.ideRunId);
    // 会话级亲和键。校验和 run id 逐字一致 —— 网关那边两级用的是同一道判据，
    // 这边放宽一点点都会让那个值被静默丢弃，而表现只是「缓存又不命中了」。
    if (/^[-_A-Za-z0-9]{8,128}$/.test(String(config.ideSessionId || ""))) {
      _h["x-ide-session-id"] = String(config.ideSessionId);
    }
    if (Number.isInteger(config.ideStepIndex) && config.ideStepIndex >= 0 && config.ideStepIndex <= 10_000) _h["x-ide-step-index"] = String(config.ideStepIndex);
    if (_IDE_TIMELINE_STEP_KINDS.has(String(config.ideStepKind || ""))) _h["x-ide-step-kind"] = String(config.ideStepKind);
    if (config.ideTimezone) _h["x-ide-timezone"] = String(config.ideTimezone).slice(0, 64);
    if (config.ideRegion) _h["x-ide-region"] = String(config.ideRegion).slice(0, 8);
    // michael-compression：网关按会员套餐钳位并回传实际生效档位。
    if (config.michaelCompression) _h["x-michael-compression"] = String(config.michaelCompression);
    if (Number.isInteger(config.ideUtcOffsetMinutes)) _h["x-ide-utc-offset-minutes"] = String(config.ideUtcOffsetMinutes);
    const endpoint = _chatCompletionsUrl(config.baseUrl);
    // 和桌面端同一个头。网页端不经过 Tauri，所以在这儿直接加。
    const _routeId = String(config.ideRouteId || config.gatewayRouteId || "").trim();
    const _post = async (body) => {
      activeAttemptController = typeof AbortController !== "undefined" ? new AbortController() : null;
      const deadlineAt = Date.now() + _AI_RESPONSE_HEADERS_DEADLINE_MS;
      _h["x-ide-response-deadline-ms"] = String(deadlineAt);
      // 同一件事的相对说法，两个一起发。
      //
      // 上面那个是 Date.now() —— **本机墙上时钟**的时间戳，而网关要拿它减自己的时钟才
      // 能算出"还剩多久"。机器时钟慢上一两分钟（NTP 被挡、虚拟机休眠唤醒、装机没对时），
      // 这个差就永远是负的，网关那边算出的预算恒为零：那台机器上每一次请求都在发往上游
      // 之前就被判死，而且永远如此，两边日志里都看不出为什么。
      //
      // 相对预算不牵涉任何时钟比对 —— 它就是本地定时器的那个数（下面 setTimeout 用的
      // 同一个常量），所以时钟准不准都不影响它。网关优先采信这一个，绝对时间戳只用来
      // 收紧（它的价值是把上传耗时也算进去了），且只在两个时钟对得上时才收紧。
      _h["x-ide-response-budget-ms"] = String(_AI_RESPONSE_HEADERS_DEADLINE_MS);
      // 用户点的是哪一组。网关只在**它已经算出来的候选**里认这个 id，
      // 所以它至多让用户在自己本来就能从列表里点到的那几条线路之间选一条。
      if (_routeId) _h["x-ide-route"] = _routeId;
      let timer = null;
      if (activeAttemptController) timer = setTimeout(() => activeAttemptController.abort(), _AI_RESPONSE_HEADERS_DEADLINE_MS);
      try {
        return await fetch(endpoint, {
          method: "POST",
          headers: _h,
          body: JSON.stringify(body),
          signal: activeAttemptController?.signal,
        });
      } catch (error) {
        if (turnController?.signal.aborted) throw new Error("AI request cancelled");
        if (activeAttemptController?.signal.aborted) throw _responseHeadersDeadlineError(_AI_RESPONSE_HEADERS_DEADLINE_MS);
        throw error;
      } finally {
        if (timer) clearTimeout(timer);
      }
    };
    const resp = await _postAiOnce(_post, payload, { signal: turnController?.signal });
    if (!resp.ok) {
      let errorText = "";
      try {
        errorText = await _readAiErrorResponseText(resp, _AI_ERROR_BODY_DEADLINE_MS, () => activeAttemptController?.abort());
      } catch (error) {
        errorText = String(error?.message || error || "");
      }
      // status 必须结构化带上：下游的重试/续传/收尾文案全靠它分类，从文案里反解析
      // 是这套机制上一版最脆的地方（见 _aiFailureKind 上面那段）。
      onEvent({
        kind: "error",
        message: _formatAiHttpError(resp.status, resp.statusText, errorText),
        status: resp.status,
        // 网关一个请求最多换两个上游出口就收手，撞上的那两个已经被记了让位/冷却 ——
        // 所以**重发一次会落到别的出口上**。置位时就别走 15 秒的限流退避了，
        // 那是在白等一个本可以立刻成功的请求。从文案里认这件事不行：措辞一改就失效。
        retryElsewhere: resp.headers?.get?.("x-mide-retry-elsewhere") === "1",
      });
      onEvent({ kind: "done" });
      return;
    }
    streamMetric("responseHeaders");
    if (!resp.ok || !resp.body) {
      let t = "";
      try {
        t = await _readAiErrorResponseText(resp, _AI_ERROR_BODY_DEADLINE_MS, () => activeAttemptController?.abort());
      } catch (error) {
        t = String(error?.message || error || "");
      }
      onEvent({
        kind: "error",
        message: _formatAiHttpError(resp.status, resp.statusText, t),
        status: resp.status,
        // 网关一个请求最多换两个上游出口就收手，撞上的那两个已经被记了让位/冷却 ——
        // 所以**重发一次会落到别的出口上**。置位时就别走 15 秒的限流退避了，
        // 那是在白等一个本可以立刻成功的请求。从文案里认这件事不行：措辞一改就失效。
        retryElsewhere: resp.headers?.get?.("x-mide-retry-elsewhere") === "1",
      });
      onEvent({ kind: "done" });
      return;
    }
    
    // Web build 同样需要解析网关签发的压缩前缀引用（桌面端在 ai.rs 解析；web 在此解析）。
    // 没有这一步，网关每轮签的令牌都进了垃圾桶，客户端只能整份上传历史被 3.5MB 卡死。
    try {
      const prefix = resp.headers.get("x-michael-compression-prefix");
      const coveredStr = resp.headers.get("x-michael-compression-covered");
      const covered = Number(coveredStr || "0") || 0;
      if (prefix && typeof prefix === "string") {
        const trimmedPrefix = prefix.trim();
        // Must match the token the gateway actually issues: "mcp_" + hex. The old bare-hex
        // pattern rejected every real token, so the client never stored a prefix, re-uploaded the
        // entire transcript every turn, and hit the 3.5MB body cap — which made the 2M and 5M
        // tiers physically unreachable from the app no matter what the user paid for. The correct
        // pattern already existed 100 lines below in _mcPrefixLoadAll; this copy was stale.
        if (/^mcp_[a-f0-9]{16,80}$/i.test(trimmedPrefix) && covered > 0) {
          // 覆盖条数缺失或解析失败时按 0 处理：宁可这一轮整份重传，也不能凭一个错的
          // 条数去裁历史 —— 裁错了模型收到的是错位的上下文，而且不会有任何报错。
          onEvent({ kind: "compressionPrefix", token: trimmedPrefix, covered });
        }
      }
    } catch (e) {
      /* Header read is best-effort; lack of prefix only means we skip the optimization this turn */
    }

    const reader = resp.body.getReader();
    const dec = new TextDecoder();
    let buf = "";
    let rawBytes = 0;
    let sentFirstChunkMetric = false;
    let sentFirstProgressMetric = false;
    let lastBytesMetricAt = 0;
    const streamTimeouts = _browserAiStreamTimeouts(config);
    // The whole physical attempt gets one 60-second window to produce a real
    // reasoning/token/tool event. Response headers and empty control frames do
    // not restart that clock.
    const progressStartedAt = streamStarted;
    let firstDataAt = null;
    let lastProgressAt = progressStartedAt;
    let lastByteAt = progressStartedAt;
    let hasProgress = false;
    // Liveness vs. productivity are different questions, and conflating them was killing
    // healthy streams.
    //
    // The gateway sends an SSE heartbeat (`: ping\n\n`) every 15s while the upstream is
    // silent, precisely so the connection survives Chinese carrier NATs. But a heartbeat
    // is an SSE *comment*: no `data:` payload, so it never reaches markFirstProgress().
    // The stall deadline therefore ignored it, and a model that went quiet for 45s while
    // composing a big write_file argument (or just thinking) was aborted by the CLIENT as
    // "网络波动" — even though bytes were arriving the whole time.
    //
    // Worse, 45s is stricter than the gateway's own 180s idle guard, so the client gave up
    // first and the server never got to make the call. Now:
    //   • bytes (incl. heartbeats) prove the connection is alive → LIVENESS_MS
    //   • content stalls fall back to a backstop set ABOVE the gateway's idle guard, so the
    //     server decides when a stream is truly dead and the client stops second-guessing it.
    const LIVENESS_MS = 60_000;          // 4 missed 15s heartbeats ⇒ connection really is gone
    const CONTENT_BACKSTOP_MS = 200_000; // > the gateway's 180s idle guard
    const progressDeadline = () => {
      if (hasProgress) {
        const heartbeatAlive = Date.now() - lastByteAt < LIVENESS_MS;
        const limitMs = heartbeatAlive
          ? Math.max(streamTimeouts.stallMs, CONTENT_BACKSTOP_MS)
          : streamTimeouts.stallMs;
        return { at: lastProgressAt + limitMs, phase: "stall", limitMs };
      }
      if (firstDataAt != null) return { at: progressStartedAt + streamTimeouts.firstProgressMs, phase: "empty", limitMs: streamTimeouts.firstProgressMs };
      return { at: progressStartedAt + streamTimeouts.firstProgressMs, phase: "first", limitMs: streamTimeouts.firstProgressMs };
    };
    const readWithProgressDeadline = async () => {
      const deadline = progressDeadline();
      const remaining = deadline.at - Date.now();
      const timeoutMessage = deadline.phase === "stall"
        ? `模型连续 ${Math.round(deadline.limitMs / 1000)} 秒没有继续生成有效内容，已停止本轮。`
        : (deadline.phase === "empty"
          ? `上游已开始流式传输，但 ${Math.round(deadline.limitMs / 1000)} 秒内没有生成有效内容，已停止本轮。`
          : `模型在 ${Math.round(deadline.limitMs / 1000)} 秒内没有生成有效内容，已停止本轮。`);
      if (remaining <= 0) {
        activeAttemptController?.abort();
        throw new Error(timeoutMessage);
      }
      let timer = null;
      const timeout = new Promise((_, reject) => {
        timer = setTimeout(() => {
          activeAttemptController?.abort();
          reject(new Error(timeoutMessage));
        }, remaining);
      });
      try {
        return await Promise.race([reader.read(), timeout]);
      } finally {
        if (timer) clearTimeout(timer);
      }
    };
    const markFirstProgress = () => {
      lastProgressAt = Date.now();
      hasProgress = true;
      if (!sentFirstProgressMetric) {
        sentFirstProgressMetric = true;
        streamMetric("firstProgress", { bytes: rawBytes });
      }
    };
    for (;;) {
      const { done, value } = await readWithProgressDeadline();
      if (done) break;
      // Any bytes — including the gateway's `: ping` heartbeats — prove the connection is
      // still up, which is what LIVENESS_MS in progressDeadline() keys off.
      if (value && value.byteLength) lastByteAt = Date.now();
      rawBytes += (value && value.byteLength) || 0;
      if (!sentFirstChunkMetric) {
        sentFirstChunkMetric = true;
        lastBytesMetricAt = Date.now();
        streamMetric("firstChunk", { bytes: rawBytes });
      } else if (!sentFirstProgressMetric && Date.now() - lastBytesMetricAt >= 3000) {
        // 首个有效输出前的字节心跳：同 Rust 侧，让停顿提示能区分"连接活着"和"上游断了"。
        lastBytesMetricAt = Date.now();
        streamMetric("streaming", { bytes: rawBytes });
      }
      buf += dec.decode(value, { stream: true });
      let nl;
      while ((nl = buf.indexOf("\n")) >= 0) {
        const line = buf.slice(0, nl).trim();
        buf = buf.slice(nl + 1);
        if (!line.startsWith("data:")) continue;
        const data = line.slice(5).trim();
        if (firstDataAt == null) firstDataAt = Date.now();
        if (data === "[DONE]") { streamMetric("done", { bytes: rawBytes }); onEvent({ kind: "done" }); return; }
        if (!data) continue;
        try {
          const v = JSON.parse(data);
          if (v.usage && typeof v.usage === "object") {
            const u = v.usage;
            // null = 上游没报缓存字段（≠ 真 0）——仪表要显示"未上报"而不是误导排查的"缓存 0"。
            // 覆盖 OpenAI/DeepSeek/Anthropic/Gemini + 顶层平铺 + Responses 风格共 7 种形态。
            const _cc = [
              u.prompt_tokens_details && u.prompt_tokens_details.cached_tokens,
              u.prompt_cache_hit_tokens,
              u.cache_read_input_tokens,
              u.cached_content_token_count,
              u.cachedContentTokenCount,
              u.cached_tokens,
              u.input_tokens_details && u.input_tokens_details.cached_tokens,
            ].find((v) => v != null);
            const cached = _cc != null ? (Number(_cc) || 0) : null;
            // Same shape rule the desktop transport applies (ai.rs) and the gateway bills by.
            // The presence of `cache_read_input_tokens` is the discriminator: Anthropic reports
            // input EXCLUDING everything served from (or written to) cache, so the three have to
            // be added to get the tokens the model actually read. OpenAI/DeepSeek report a
            // prompt total that already CONTAINS the cached part — adding would double it.
            const cacheWrite = Number(u.cache_creation_input_tokens) || 0;
            const promptRaw = Number(u.prompt_tokens ?? u.input_tokens) || 0;
            const prompt = u.cache_read_input_tokens != null
              ? promptRaw + (cached || 0) + cacheWrite
              : promptRaw;
            const completion = Number(u.completion_tokens ?? u.output_tokens) || 0;
            // 思考 token：_recordUsage 一直在读它（上下文环里的「思考 高 · 推理 1.2k」），
            // 但两条传输层都没往上传，于是那半句永远不显示——用户拨了深度，拿不到任何回执。
            // 各家字段名不同，全认一遍。
            const reasoning = Number(
              (u.completion_tokens_details && u.completion_tokens_details.reasoning_tokens)
              ?? (u.output_tokens_details && u.output_tokens_details.reasoning_tokens)
              ?? u.reasoning_tokens,
            ) || 0;
            if (prompt > 0 || completion > 0) {
              onEvent({
                kind: "usage",
                prompt_tokens: prompt,
                completion_tokens: completion,
                cached_tokens: cached,
                cache_creation_tokens: cacheWrite,
                reasoning_tokens: reasoning,
                // 网关在 Anthropic 线路上补的字段：那条路没有 reasoning_tokens 可报。
                thinking_chars: Number(u.thinking_chars) || 0,
              });
            }
          }
          const d = (v.choices && v.choices[0] && v.choices[0].delta) || {};
          const rt = d.reasoning_content || d.reasoning;
          if (rt) { markFirstProgress(); onEvent({ kind: "reasoning", delta: rt }); }
          if (d.content) { markFirstProgress(); onEvent({ kind: "token", delta: d.content }); }
          if (Array.isArray(d.tool_calls)) {
            for (const tc of d.tool_calls) {
              if (!Number.isInteger(tc.index) || tc.index < 0) {
                onEvent({ kind: "error", message: "streamed tool call is missing its numeric index" });
                onEvent({ kind: "done" });
                return;
              }
              onEvent({
                kind: "toolCall",
                index: tc.index,
                id: tc.id || "",
                name: (tc.function && tc.function.name) || "",
                arguments: (tc.function && tc.function.arguments) || "",
              });
              if (tc.id || (tc.function && (tc.function.name || tc.function.arguments))) markFirstProgress();
            }
          }
        } catch { /* keep buffering */ }
      }
    }
    onEvent({ kind: "error", message: _AI_INCOMPLETE_STREAM_ERROR });
    onEvent({ kind: "done" });
  } catch (e) {
    onEvent({ kind: "error", message: String((e && e.message) || e) });
    onEvent({ kind: "done" });
  } finally {
    if (cancelId && _browserAiControllers.get(cancelId) === turnController) _browserAiControllers.delete(cancelId);
  }
}

