/** Map a filename to a bundled Material file-icon URL. */
function fileIconUrl(name) {
  // String(name || "")：一次没传名字的 openFile 不该让 renderTabs 在剩下的
  // 整个会话里全抛——标签栏是全局的，单点故障代价太大。
  const lower = String(name || "").toLowerCase();
  if (lower in NAME_ICON) return iconUrl(NAME_ICON[lower]);
  if (lower.endsWith(".lock")) return iconUrl("lock");
  const ext = lower.includes(".") ? lower.split(".").pop() : "";
  if (ext in EXT_ICON) return iconUrl(EXT_ICON[ext]);
  return iconUrl("file");
}

/** Map a folder name + open state to a bundled Material folder-icon URL. */
function folderIconUrl(name, open) {
  const base = FOLDER_ICON[String(name || "").toLowerCase()] || "folder";
  return (
    iconUrl(open ? base + "-open" : base) ||
    iconUrl(open ? "folder-open" : "folder")
  );
}

let rootContainer = null;
/** path -> { row, kids, loaded } for every directory row currently rendered. */
const dirNodes = new Map();

function setExplorerToolsEnabled(on) {
  for (const id of ["newFileBtn", "newFolderBtn", "refreshTreeBtn"]) {
    const b = $(id);
    if (b) b.disabled = !on;
  }
}

const parentDir = (p) => { const s = String(p == null ? "" : p); return s.slice(0, s.lastIndexOf("/")) || "/"; };

function basename(path) {
  // Guard: a stale/legacy/partially-written stored session can hand us a non-string
  // (null / object / number) path. Splitting that threw "t.split is not a function"
  // and crashed the whole app-open render. Coerce to string first.
  const p = String(path == null ? "" : path);
  return p.split("/").filter(Boolean).pop() || p;
}

// Auto-seed the project's knowledge graph on first open so the agent is smart from message 1 and
// doesn't re-scan / re-install. Records the ENVIRONMENT (venv + its installed packages → the agent
// knows what's already there) and a one-line STACK profile. Idempotent: a `项目环境:`/`项目档案:`
// marker note stops re-seeding on later sessions.
const _profiledRoots = new Set();
async function _seedProjectProfile(root) {
  if (!root || !inTauri || _profiledRoots.has(root)) return;
  _profiledRoots.add(root);
  // 旧写法是"存在即返回"，于是首次打开时抓到的那份依赖清单永不更新：venv 删了、
  // 包换了，它还在每轮说"这些包已装好，别重复安装"。改成 7 天过期，并且重播前先把
  // 旧笔记删掉——不删的话 _kgInsert 的近似去重会把新笔记直接吞掉，等于没刷新。
  const _SEED_TTL = 7 * 86400000;
  try {
    const notes = _kgLoad(root);
    const stale = notes.filter((n) => /^项目环境:|^项目档案:/.test(n.content || ""));
    if (stale.some((n) => Date.now() - (n.created || 0) < _SEED_TTL)) return;
    if (stale.length) {
      const ids = new Set(stale.map((n) => n.id));
      _kgSave(root, notes.filter((n) => !ids.has(n.id)));
      _kgCacheDrop(root);
    }
  } catch {}
  const add = (c) => { try { if (c) _kgAddNote(root, c); } catch {} };
  const read = (rel) => backend.readTextFile(`${root}/${rel}`).catch(() => null);
  try {
    // --- Environment: venv + its installed top-level packages (so nothing gets reinstalled) ---
    for (const v of [".venv", "venv"]) {
      const cfg = await read(`${v}/pyvenv.cfg`);
      if (!cfg) continue;
      const ver = (cfg.match(/version\s*=\s*([\d.]+)/) || [])[1] || "";
      let pkgs = "";
      try {
        const r = await backend.taskRunCapture(root, `"${root}/${v}/bin/python" -m pip list --format=freeze 2>/dev/null | cut -d= -f1 | grep -viE '^(pip|setuptools|wheel)$' | head -25 | paste -sd, -`);
        if (r && r.code === 0) pkgs = String(r.stdout || "").trim();
      } catch {}
      // 写成带日期的观测值而不是祈使句："别重复安装"是命令，模型会照办到清单过期
      // 之后；"某天抓到的、可能已变动"才是这条笔记真正的认识论地位。
      add(`项目环境: Python venv 在 ${v}/${ver ? `（Python ${ver}）` : ""}${pkgs ? `；${new Date().toISOString().slice(0, 10)} 抓到的已装依赖（可能不全或已变动，装包前用 pip show 核实）: ${pkgs}` : ""}。调试/运行/装包用这个 venv。`);
      break;
    }
    // --- Stack / entry ---
    const pkg = await read("package.json");
    if (pkg) {
      try { const j = JSON.parse(pkg); const s = Object.keys(j.scripts || {}); add(`项目档案: Node 项目「${j.name || basename(root)}」${s.length ? `；npm 脚本: ${s.slice(0, 8).join(", ")}` : ""}。`); } catch {}
    } else if ((await read("requirements.txt")) || (await read("pyproject.toml"))) {
      add(`项目档案: Python 项目「${basename(root)}」，依赖见 requirements.txt / pyproject.toml。`);
    } else if (await read("Cargo.toml")) {
      add(`项目档案: Rust 项目「${basename(root)}」（cargo build / run / test）。`);
    } else if (await read("go.mod")) {
      add(`项目档案: Go 项目「${basename(root)}」（go build / run / test）。`);
    }
  } catch { /* best-effort seeding */ }
}

const _kgSyncedRoots = new Set();
function _syncWorkspaceRootLabel() {
  if (!rootNameEl) return;
  if (!rootPath) {
    rootNameEl.setAttribute("data-i18n", "explorer.noFolder");
    rootNameEl.textContent = t("explorer.noFolder");
    rootNameEl.title = "";
    return;
  }
  // This is dynamic state. Keeping the static marker lets the locale observer
  // overwrite the real folder name with "No folder" one frame later.
  rootNameEl.removeAttribute("data-i18n");
  if (workspaceRoots.length > 1) {
    rootNameEl.textContent = t("explorer.folderCount", { count: workspaceRoots.length, name: basename(rootPath) });
    rootNameEl.title = workspaceRoots.join("\n");
  } else {
    rootNameEl.textContent = basename(rootPath);
    rootNameEl.title = rootPath;
  }
}

function setActiveWorkspaceRoot(path) {
  _invalidateProjectFileCache();
  path = _toPosix(path);
  rootPath = path;
  _launchConfigsCache = null;
  _agentContextCache = { root: "", ts: 0, data: "" };
  // Reconcile this workspace's memory with its durable real file (once per root) —
  // restores the knowledge graph if localStorage was cleared / lost.
  if (path && inTauri && !_kgSyncedRoots.has(path)) { _kgSyncedRoots.add(path); _kgSyncFromStore(path); _epSyncFromStore(path); _wfSyncFromStore(path); _idleRun(() => _seedProjectProfile(path)); }
  // Schedule a background symbol-index build for this root (idempotent — exits
  // fast if already built for the same root). Powers the `find_symbol` tool.
  if (path && inTauri && typeof scheduleSymbolIndex === "function") {
    if (_symbolIndexRoot !== path) { _symbolIndexBuilt = false; _symbolIndex.clear(); }
    scheduleSymbolIndex();
  }
  if (path && inTauri) _scheduleWorkspaceAgentWarmup(path);
  _syncWorkspaceRootLabel();
  setExplorerToolsEnabled(Boolean(path));
  const titleFile = activePath ? openFiles.get(activePath)?.name : "";
  const project = path ? basename(path) : "";
  _setWindowTitle(project
    ? (titleFile ? titleFile + " — " : "") + project + " — Mr. Day One"
    : "Mr. Day One");
}

async function renderWorkspaceRoots() {
  _pruneExpandedTreeDirs();
  dirNodes.clear();
  treeEl.innerHTML = "";
  rootContainer = document.createElement("div");
  treeEl.appendChild(rootContainer);

  for (const root of workspaceRoots) {
    const collapsed = collapsedWorkspaceRoots.has(root);
    const section = document.createElement("div");
    section.className = "workspace-root" + (collapsed ? " is-collapsed" : "");

    const row = document.createElement("div");
    row.className = "row workspace-root__row" + (root === rootPath ? " is-active" : "") + (collapsed ? "" : " open");
    row.dataset.path = root;
    row.innerHTML =
      `<button class="workspace-root__toggle" type="button" aria-label="${_escAttr(collapsed ? t("ctx.expandFolder") : t("ctx.collapseFolder"))}" title="${_escAttr(collapsed ? t("ctx.expandFolder") : t("ctx.collapseFolder"))}"><svg class="chev"><use href="#i-chevron" /></svg></button>` +
      `${iconImg(folderIconUrl(basename(root), !collapsed), "folder-ic")}<span class="name"></span><span class="workspace-root__path"></span>` +
      `<button class="workspace-root__close" type="button" aria-label="${_escAttr(t("ctx.removeWorkspaceFolder"))}" title="${_escAttr(t("ctx.removeWorkspaceFolder"))}">×</button>`;
    row.querySelector(".name").textContent = basename(root);
    // 首尾 LRM：路径在 rtl 省略容器里截断出「…尾部」效果时，防止首尾的 / 因 bidi 跳到错误一端
    row.querySelector(".workspace-root__path").textContent = "‎" + root + "‎";
    row.title = root;
    row.querySelector(".workspace-root__toggle").addEventListener("click", async (e) => {
      e.preventDefault();
      e.stopPropagation();
      if (collapsedWorkspaceRoots.has(root)) collapsedWorkspaceRoots.delete(root);
      else collapsedWorkspaceRoots.add(root);
      await renderWorkspaceRoots();
    });
    row.querySelector(".workspace-root__close").addEventListener("click", async (e) => {
      e.preventDefault();
      e.stopPropagation();
      await removeWorkspaceRoot(root);
    });
    row.addEventListener("click", async (e) => {
      if (_treeSelectClick(e, root)) return;
      if (root !== rootPath) {
        setActiveWorkspaceRoot(root);
        await refreshGitStatus();
        preloadProjectModels(root);
        renderTreeActive();
      } else {
        renderTreeActive();
      }
    });
    row.addEventListener("contextmenu", (e) => {
      e.preventDefault();
      e.stopPropagation();
      _suppressNativeSelection();
      openContextMenu(e.clientX, e.clientY, { path: root, name: basename(root), is_dir: true });
    });

    const kids = document.createElement("div");
    kids.className = "children workspace-root__children";
    kids.hidden = collapsed;
    section.append(row, kids);
    rootContainer.appendChild(section);
    if (!collapsed) await renderChildren(root, kids);
  }
  renderTreeActive();
  syncWelcome();
}

// owner: 发起这次打开的会话。两个调用点都是异步且不锁定活动标签——切标签时
// fire-and-forget 跑 _ensureSessionWorkspaceRoot，发送预检也跑它（外面那层 8s
// Promise.race 只是不等，并不取消），所以落地那一刻前台可能已经换人了。写死
// _currentSession() 就会把新目录记到无辜的那个标签头上：它的目录小标签悄悄变成
// 别人的，下一轮还会吃到「工作区已切换，彻底忘掉上面对话里的目录/路径/代码」，
// 模型当场否定自己前面读过的所有文件；项目记忆按 root 做 key，之前记的也全检索不到。
async function openFolder(path, owner = null) {
  path = _toPosix(path);
  if (!(await _closeOpenFilesOutsideRoot(path))) return;
  _workspaceRootEntryCounts.clear();
  /*
   * 换项目要把语言服务器一起换掉。
   *
   * rootUri / workspaceFolders 是 initialize 时一次性钉进去的，之后没有任何一处改过它。
   * 打开 Rust 项目 A → rust-analyzer 按 A 的 Cargo workspace 起来；不重启应用直接切到
   * 项目 B，那个进程还在按 A 工作。打开 B/src/main.rs → 它不属于 A 认识的任何 crate →
   * 补全、跳转、诊断全部失效，而状态栏仍然显示「LSP: rust」一切正常。用户看到的是
   * 「换了个项目，代码智能就没了」，唯一的恢复手段是重启应用。
   *
   * 这里只停不起：下一次 didOpen 会按新根重新 initialize。**要在 workspaceRoots 换掉
   * 之前停**——lspStop 里清 markers 之类还按旧根算。
   */
  try { await lspManager?.resetForNewWorkspace?.(); } catch {}
  workspaceRoots = [path];
  setActiveWorkspaceRoot(path);
  // Opening a different project should immediately retag the active chat tab AND keep the
  // session's own root in sync (it was only updating .project, so session.workspaceRoots could
  // drift stale and later re-override the global root on restore).
  const _sess = owner || _currentSession();
  if (_sess) {
    _sess.workspaceRoots = [path];
    if (_sess.project !== path) { _sess.project = path; _renderChatTabs(); saveChatHistory(); }
  }
  try { await backend.registerWorkspaceRoot(path); }
  catch (e) { if (inTauri) showToast(`⚠️ 打开「${basename(path)}」时注册失败：${String(e?.message || e).slice(0, 80)}。该目录下读写可能被拒绝。`); }
  _ipcBroadcast("workspace_changed", { roots: [path], active: path });
  // 项目记忆读回：本地存储为空时（换机器、清了应用数据、重装）从 .mrdayone/memory.md 恢复。
  // 不 await——它只影响后续轮次的记忆检索，不该让"打开文件夹"多等一次磁盘往返。
  void _importProjectMemoryFile(path);
  await renderWorkspaceRoots();
  preloadProjectModels(path);
  scheduleProjectCacheRefresh(path, "项目已打开");
  await refreshGitStatus();
  await startFileWatcher();
  addRecentProject(path);
  scheduleSaveSession();   // remember this project immediately, not just on close
  _maybeOnboardProject(path); // Codex-style 上手引导 for a freshly-opened project
}

// Show one-time "上手引导" chips when a project is first opened this session: deep-dive,
// what-is-it, how-to-run, add-a-feature. Skipped if the current chat is mid-conversation.
const _onboardedRoots = new Set();
function _maybeOnboardProject(path) {
  try {
    if (!path || _onboardedRoots.has(path)) return;
    _onboardedRoots.add(path);
    const sess = _currentSession();
    if (!sess || !sess.container) return;
    if (sess.memory && sess.memory.recent.length > 1) return; // don't interrupt an ongoing chat
    _renderSuggestionChips(sess, [
      { label: "🔎 " + t("assistant.chip.projectResearch"), send: t("assistant.prompt.projectResearch") },
      { label: t("assistant.chip.whatIsProject"), send: t("assistant.prompt.whatIsProject") },
      { label: t("assistant.chip.howToRun"), send: t("assistant.prompt.howToRunProject") },
      { label: t("assistant.chip.addFeature"), send: t("assistant.prompt.addFeature") },
    ], t("assistant.onboardHeader", { name: basename(path) }));
  } catch {}
}

let _fsWatcherActive = false;
let _fsChangeDebounce = null;
let _fsChangeBatch = [];
const _watchedRoots = new Set(); // roots already registered with the native watcher
let _fsWatcherUnlisten = null;
let _fsWatcherSync = Promise.resolve();
const _pendingReloadDirs = new Set(); // tree reloads deferred while a right-click menu is open
function _desiredFileWatchRoots() {
  return (workspaceRoots.length ? [...workspaceRoots] : rootPath ? [rootPath] : []).filter(Boolean);
}

function _fileWatcherRootPlan(watchedRoots, desiredRoots) {
  const watched = new Set(watchedRoots || []);
  const desired = new Set(desiredRoots || []);
  return {
    unwatch: [...watched].filter((root) => !desired.has(root)),
    watch: [...desired].filter((root) => !watched.has(root)),
  };
}

function _detachFileWatcherListener() {
  try { _fsWatcherUnlisten?.(); } catch {}
  _fsWatcherUnlisten = null;
  _fsWatcherActive = false;
  clearTimeout(_fsChangeDebounce);
  _fsChangeDebounce = null;
  _fsChangeBatch = [];
}

async function _reconcileFileWatcher() {
  const desiredRoots = _desiredFileWatchRoots();
  const { unwatch, watch } = _fileWatcherRootPlan(_watchedRoots, desiredRoots);

  // Native watching is incremental, so root replacement must first remove old paths.
  if (unwatch.length) {
    try { await backend.fsUnwatch(unwatch); }
    catch (e) { console.warn("[watcher] failed to stop:", e); }
    finally { for (const root of unwatch) _watchedRoots.delete(root); }
  }

  if (!desiredRoots.length) {
    _detachFileWatcherListener();
    return;
  }

  if (watch.length) {
    try {
      await backend.fsWatch(watch);
      for (const root of watch) _watchedRoots.add(root);
    } catch (e) {
      console.warn("[watcher] failed to start:", e);
      return;
    }
  }

  if (_fsWatcherActive) return;
  try {
    const { listen } = await import("@tauri-apps/api/event");
    _fsWatcherUnlisten = await listen("fs-change", (event) => {
      // notify may still flush a batch queued immediately before fs_unwatch.
      const roots = _desiredFileWatchRoots();
      const _gone = new Set(event.payload?.missing || []); // 后端判过存在性，见 watcher.rs
      for (const p of event.payload?.paths || []) {
        if (!roots.some((root) => _pathIsAtOrUnder(p, root))) continue;
        _fsChangeBatch.push(p);
        if (_gone.has(p)) _fsChangeMissing.add(p);
      }
      if (!_fsChangeBatch.length) return;
      clearTimeout(_fsChangeDebounce);
      _fsChangeDebounce = setTimeout(() => {
        const batch = _fsChangeBatch;
        const missing = [..._fsChangeMissing];
        _fsChangeBatch = [];
        _fsChangeMissing.clear();
        if (batch.length) handleFsChanges(batch, missing);
      }, 200);
    });
    _fsWatcherActive = true;
  } catch (e) {
    console.warn("[watcher] failed to subscribe:", e);
  }
}

function startFileWatcher() {
  if (!inTauri) return Promise.resolve();
  // Serialize project switches so a stale reconciliation cannot re-add an old root.
  _fsWatcherSync = _fsWatcherSync.catch(() => {}).then(_reconcileFileWatcher);
  return _fsWatcherSync;
}

function stopFileWatcher() {
  _detachFileWatcherListener();
  // Serialize shutdown behind any in-flight reconciliation. The close-request path
  // awaits this promise, so native watches do not survive a normal window close.
  _fsWatcherSync = _fsWatcherSync.catch(() => {}).then(async () => {
    const roots = [..._watchedRoots];
    _watchedRoots.clear();
    if (inTauri && roots.length) {
      try { await backend.fsUnwatch(roots); }
      catch (e) { console.warn("[watcher] failed to stop:", e); }
    }
  });
  return _fsWatcherSync;
}

const _FS_IGNORE_RE = /(^|\/)(node_modules|\.git|target|dist|build|out|\.next|coverage|\.cache|\.venv|__pycache__|vendor|\.gradle)(\/|$)/;
function _isDependencyCachePath(path) {
  const p = _normalizeFsPath(String(path || ""));
  return /(^|\/)(package\.json|package-lock\.json|npm-shrinkwrap\.json|pnpm-lock\.yaml|yarn\.lock|bun\.lockb?|bun\.lock|tsconfig(?:\.[^/]+)?\.json|vite\.config\.[cm]?[jt]s|tailwind\.config\.[cm]?[jt]s|node_modules)(\/|$)/.test(p);
}
function _isGeneratedDependencyDiagnosticPath(path) {
  const p = _normalizeFsPath(String(path || ""));
  return /(^|\/)(package-lock\.json|npm-shrinkwrap\.json|pnpm-lock\.yaml|yarn\.lock|bun\.lockb?|bun\.lock|node_modules|\.mrdayone-ide-types)(\/|$)/.test(p);
}
function _isDependencyResolutionDiagnostic(marker) {
  const msg = String(marker?.message || "");
  return /cannot find module|could not find a declaration file|cannot find type definition|cannot find namespace|找不到模块|找不到.*声明|找不到.*类型定义|module not found|can't resolve/i.test(msg);
}
function _isGeneratedDependencyDiagnostic(marker) {
  return _isGeneratedDependencyDiagnosticPath(markerProblemPath(marker)) && _isDependencyResolutionDiagnostic(marker);
}
function _invalidateSessionEvidenceForPaths(paths) {
  for (const session of _chatSessions || []) {
    const memory = session?.memory;
    const project = _normalizeFsPath(String(session?.project || "")).replace(/\/+$/, "");
    if (!project || typeof memory?.invalidateFileEvidence !== "function") continue;
    for (const path of paths || []) {
      const normalized = _normalizeFsPath(String(path || ""));
      if (normalized === project || normalized.startsWith(project + "/")) {
        memory.invalidateFileEvidence(project, _normRel(normalized, project));
      }
    }
  }
}
// Observed-fact ledger for command mutation accounting. The watcher is the ground truth
// for "did the workspace change?" — strictly better than reading intent out of a command
// string, and it sees what no classifier can (a script, a Makefile target, a generator).
let _fsWatchTick = 0;
let _fsWatchRecent = [];
function _fsWatchSnapshot() { return { tick: _fsWatchTick, len: _fsWatchRecent.length }; }
function _fsWatchDeltaSince(snap) {
  if (!snap) return { changed: false, paths: [] };
  if (_fsWatchTick === snap.tick) return { changed: false, paths: [] };
  return { changed: true, paths: _fsWatchRecent.slice(Math.max(0, snap.len)) };
}

// 这一批里已经不存在的那些。后端在监视线程里判过（一次 exists 系统调用），
// 前端只负责攒到 debounce 结束——LSP 的变更通知必须带对类型才有用，见 notifyWatchedFiles。
let _fsChangeMissing = new Set();
function handleFsChanges(paths, missing = []) {
  const roots = _desiredFileWatchRoots();
  paths = (paths || []).map(_coherentFilePath)
    .filter((path) => roots.some((root) => _pathIsAtOrUnder(path, root)));
  if (!paths.length) return;
  if (paths.length) {
    _fsWatchTick++;
    _fsWatchRecent.push(...paths);
    if (_fsWatchRecent.length > 400) _fsWatchRecent = _fsWatchRecent.slice(-400);
  }
  // 语言服务器只从 didOpen 认得到编辑器打开过的文件。外部创建/删除的（shell 生成、
  // 脚手架产出、装完依赖）它一无所知，而 pyright 的导入解析缓存**只认这条通知**——
  // 少了它，新建模块之后 `Import "x" could not be resolved` 永远不消失，还会进
  // 每轮喂给模型的诊断块，让模型反复重改同一行。
  try { lspManager?.notifyWatchedFiles?.(paths, missing); } catch { /* 通知失败不影响其余刷新 */ }
  const dependencyCacheChanged = paths.some(_isDependencyCachePath);
  _invalidateSessionEvidenceForPaths(paths);
  // A file actually changed (agent write / user edit / external) → the agent context is now stale, so
  // let it rebuild ONCE next time (picking up the new/edited files). When nothing changes, the cache
  // stays valid and the agent reuses it instead of re-scanning + re-reading every turn ("别一直复读").
  _agentContextCache.ts = 0;
  try {
    if (_bm25Index.root && paths.some((p) => p === _bm25Index.root || p.startsWith(_bm25Index.root + "/"))) {
      _bm25Index.built = false;
      // Invalidation without a rebuild was a one-way door: the agent-context builder asks
      // with waitForIndex=false, which returns "" on an unbuilt index — so the FIRST agent
      // write of a session permanently blinded BM25 code retrieval for the rest of it.
      // Debounced so a burst of writes schedules one rebuild; buildBM25Index additionally
      // self-guards (`building`) and yields the main thread in slices.
      clearTimeout(handleFsChanges._bm25RebuildTimer);
      handleFsChanges._bm25RebuildTimer = setTimeout(() => {
        try { void buildBM25Index(_bm25Index.root); } catch {}
      }, 2000);
    }
  } catch {}
  // Clean open models follow disk changes; dirty models keep the user's buffer and
  // become an explicit conflict instead of being overwritten.
  void _syncOpenFilesFromDisk(paths, "磁盘上的文件被外部程序");
  if (!rootPath) return;
  if (_autoSaving) {
    // An autosave write is in flight — don't DROP this batch (it may carry unrelated
    // terminal/external changes that would then never reach the tree); requeue it on
    // the same debounce and retry once the save settles.
    for (const p of paths) _fsChangeBatch.push(p);
    clearTimeout(_fsChangeDebounce);
    _fsChangeDebounce = setTimeout(() => {
      const batch = _fsChangeBatch;
      _fsChangeBatch = [];
      if (batch.length) handleFsChanges(batch);
    }, 200);
    return;
  }

  // Defense in depth (the watcher already filters these at the source): never do
  // work for changes inside high-churn build/dependency dirs. Test the path
  // RELATIVE to its workspace root, so a project that itself lives under a dir
  // named e.g. "build" isn't wholly ignored.
  paths = paths.filter((p) => {
    const r = workspaceRoots.find((wr) => p.startsWith(wr)) || (rootPath && p.startsWith(rootPath) ? rootPath : "");
    return !_FS_IGNORE_RE.test(r ? p.slice(r.length) : p);
  });
  if (dependencyCacheChanged) {
    scheduleProjectCacheRefresh(rootPath, "依赖/项目缓存变化");
  }
  if (!paths.length) return;

  const dirsToReload = new Set();
  for (const p of paths) {
    const dir = parentDir(p);
    if (dir && (workspaceRoots.some((r) => dir.startsWith(r)) || dir.startsWith(rootPath))) {
      dirsToReload.add(dir);
    }
  }
  // Don't rebuild the tree while the user has a right-click context menu open (delete / rename):
  // recreating the rows + restoring scroll would close their menu and move the target out from
  // under them ("AI 回复时右键删除文件被干扰"). Defer the reload until the menu closes.
  if (ctxMenuEl) { for (const d of dirsToReload) _pendingReloadDirs.add(d); return; }
  let reloaded = 0;
  for (const dir of dirsToReload) {
    const target = _treeReloadTargetForDir(dir);
    if (target) {
      reloadDir(target);
      if (++reloaded >= 40) break; // never reload an unbounded number of dirs at once
    }
  }
  refreshGitStatus();
}

// Add one more project folder to the (multi-root) workspace WITHOUT closing the
// others — this is "open multiple projects". Kept separate from openFolder, which
// replaces the workspace.
async function _addWorkspaceRoot(picked) {
  if (!picked) return;
  picked = _normalizeFsPath(picked);
  const existing = workspaceRoots.find((root) => _pathIdentity(root) === _pathIdentity(picked));
  if (existing) { setActiveWorkspaceRoot(existing); await renderWorkspaceRoots(); showToast(`${basename(existing)} 已在工作区`); return; }
  _workspaceRootEntryCounts.delete(_treePath(picked));
  workspaceRoots.push(picked);
  try { await backend.registerWorkspaceRoot(picked); }
  catch (e) {
    // Desktop: failed registration ⇒ the backend sandbox rejects reads/writes
    // under this folder ("access denied") — tell the user now instead of letting
    // a later write fail mysteriously. (Browser preview mocks the cmd; ignore.)
    if (inTauri) showToast(`⚠️ 添加「${basename(picked)}」失败：${String(e?.message || e).slice(0, 80)}。该目录下的读写可能被拒绝。`);
  }
  _ipcBroadcast("workspace_changed", { roots: [...workspaceRoots], active: picked });
  setActiveWorkspaceRoot(picked);
  _syncWorkspaceSessionRoots();
  await renderWorkspaceRoots();
  preloadProjectModels(picked);
  scheduleProjectCacheRefresh(picked, "工作区已添加");
  await refreshGitStatus();
  startFileWatcher();
  addRecentProject(picked);
  showToast(`已添加 ${basename(picked)} 到工作区`);
}

async function addFolderToWorkspace() {
  let picked = null;
  try { picked = await backend.pickFolder(); }
  catch { picked = null; } // native dialog unavailable on this desktop
  if (picked) { await _addWorkspaceRoot(picked); return; }
  // Same robust fallback as opening a folder: when the OS picker is unavailable
  // (Linux without xdg-desktop-portal) or cancelled, show the manual path entry
  // so multi-project actually works instead of the button doing nothing.
  await _promptFolderPath({ title: "添加文件夹到工作区", onPick: _addWorkspaceRoot });
}

function _syncWorkspaceSessionRoots() {
  const sess = _currentSession();
  if (sess) {
    sess.workspaceRoots = [...workspaceRoots];
    if (sess.project !== (rootPath || "")) {
      sess.project = rootPath || "";
      _renderChatTabs();
    }
    try { saveChatHistory(); } catch {}
  }
  scheduleSaveSession();
}

async function removeWorkspaceRoot(path, opts = null) {
  path = _toPosix(path);
  if (!path || !workspaceRoots.includes(path)) return;
  if (!opts || opts.confirm !== false) {
    const ok = await ioConfirm({
      title: t("workspace.remove.title"),
      message: t("workspace.remove.confirm", { name: basename(path), path }),
      okLabel: t("workspace.remove.ok"),
      danger: false,
    });
    if (!ok) return;
  }
  if (!(await _closeOpenFilesUnder(path))) return;
  workspaceRoots = workspaceRoots.filter((root) => root !== path);
  _workspaceRootEntryCounts.delete(_treePath(path));
  collapsedWorkspaceRoots.delete(path);
  _treeDropExpansionDescendants(path, true);
  _treeDropRenderedDescendants(path, true);
  _treeSel.delete(path);
  _applyTreeSel();
  const nextRoot = workspaceRoots.includes(rootPath) ? rootPath : (workspaceRoots[0] || null);
  setActiveWorkspaceRoot(nextRoot);
  _syncWorkspaceSessionRoots();
  _ipcBroadcast("workspace_changed", { roots: [...workspaceRoots], active: rootPath || "" });
  await renderWorkspaceRoots();
  if (rootPath) preloadProjectModels(rootPath);
  await refreshGitStatus();
  await startFileWatcher();
  showToast(t("workspace.removed", { name: basename(path) }));
}

// Eagerly load the workspace's JS/TS/JSON files into the TypeScript language
// service so imports resolve and go-to-definition works across files the user
// hasn't opened yet. Skips heavy/irrelevant directories and caps the count so
// large repos stay responsive; runs in the background (not awaited).
const PRELOAD_CODE_EXT = new Set(["ts", "tsx", "js", "jsx", "mjs", "cjs", "json"]);
const PRELOAD_SKIP_DIRS = new Set([
  "node_modules", ".git", "dist", "build", "out", "target",
  ".next", "coverage", ".cache", ".vscode", "vendor",
]);
const PRELOAD_MAX_FILES = 60; // 预热是锦上添花：150个模型启动期 tokenize+LSP 开销把整机拖卡，减配额
const PRELOAD_MAX_BYTES = 256 * 1024;
let preloadToken = 0;

async function preloadProjectModels(root) {
  // 路径别名（@/components/…）要靠项目自己的 tsconfig/jsconfig 才解析得了。不读它，
  // 现代的 Next.js / Vite-React 模板一打开就是满屏 "Cannot find module" 红波浪线，
  // F12 跳不动、悬停也没有类型。挂在这里而不是七个打开工作区的入口上：这个函数正是
  // "这个项目要用了" 的那一刻。
  _applyProjectTsConfig(root).catch(() => {});
  const token = ++preloadToken;
  // Drop project models from a previously opened folder.
  for (const p of projectModels) {
    if (openFiles.has(p)) continue;
    const m = monaco.editor.getModel(monaco.Uri.file(p));
    // 先清标记再 dispose。标记记在 monaco 的全局表上、按 resource URI 索引，不跟着 model
    // 一起消失；下次打开同一个文件夹时 URI 一样，上一辈子的红线就原样贴回来了。
    // 其余几个 dispose 点都先清了（见 _clearAllMarkersForModel 上面那段说明），只有这个漏了。
    if (m) { _clearAllMarkersForModel(m); m.dispose(); }
  }
  projectModels.clear();

  let count = 0;
  const stack = [root];
  while (stack.length && count < PRELOAD_MAX_FILES) {
    const dir = stack.pop();
    let entries;
    try {
      entries = await backend.readDir(dir);
    } catch {
      continue;
    }
    if (token !== preloadToken) return; // folder changed mid-walk
    for (const entry of entries) {
      if (entry.is_dir) {
        if (!PRELOAD_SKIP_DIRS.has(entry.name)) stack.push(entry.path);
        continue;
      }
      const ext = entry.name.includes(".") ? entry.name.split(".").pop().toLowerCase() : "";
      if (!PRELOAD_CODE_EXT.has(ext) || count >= PRELOAD_MAX_FILES) continue;
      let content;
      try {
        content = await backend.readTextFile(entry.path);
      } catch {
        continue;
      }
      if (token !== preloadToken) return;
      if (content.length > PRELOAD_MAX_BYTES) continue;
      // Never clobber a file the user has open (and may be editing): its model
      // is already alive in the language service.
      if (openFiles.has(entry.path)) {
        projectModels.add(entry.path);
        count++;
        continue;
      }
      getOrCreateModel(entry.path, entry.name, content);
      projectModels.add(entry.path);
      count++;
    }
  }
}

const TS_PACKAGE_TYPE_MAX_LIBS = 80;
const TS_PACKAGE_TYPE_MAX_BYTES = 256 * 1024;
let _tsPackageTypeRefreshToken = 0;
let _tsPackageTypeRefreshTimer = null;
const _tsPackageTypeDisposers = new Map();

function _jsTsImportSpecifiersFromText(text) {
  const specs = new Map(); // specifier -> { named:Set, hasDefault:boolean, hasNamespace:boolean }
  const remember = (spec, details = {}) => {
    if (!spec || spec.startsWith(".") || spec.startsWith("/") || /^[A-Za-z]:[\\/]/.test(spec)) return;
    const entry = specs.get(spec) || { named: new Set(), hasDefault: false, hasNamespace: false };
    if (details.hasDefault) entry.hasDefault = true;
    if (details.hasNamespace) entry.hasNamespace = true;
    for (const name of details.named || []) {
      if (/^[A-Za-z_$][\w$]*$/.test(name)) entry.named.add(name);
    }
    specs.set(spec, entry);
  };
  const src = String(text || "");
  const importRe = /^\s*import\s+(?:type\s+)?([\s\S]*?)\s+from\s+['"]([^'"]+)['"]/gm;
  let m;
  while ((m = importRe.exec(src))) {
    const clause = (m[1] || "").trim();
    const named = [];
    const namedBlock = clause.match(/\{([^}]*)\}/);
    if (namedBlock) {
      for (const part of namedBlock[1].split(",")) {
        const raw = part.trim().split(/\s+as\s+/i)[0]?.trim();
        if (raw) named.push(raw);
      }
    }
    remember(m[2], {
      named,
      hasDefault: !!clause && !clause.startsWith("{") && !clause.startsWith("*"),
      hasNamespace: /\*\s+as\s+[A-Za-z_$][\w$]*/.test(clause),
    });
  }
  const sideEffectRe = /^\s*import\s+['"]([^'"]+)['"]/gm;
  while ((m = sideEffectRe.exec(src))) remember(m[1]);
  const requireRe = /require\s*\(\s*['"]([^'"]+)['"]\s*\)/g;
  while ((m = requireRe.exec(src))) remember(m[1], { hasDefault: true });
  return specs;
}

function _nodePackageNameFromSpecifier(specifier) {
  const s = String(specifier || "").trim();
  if (!s || s.startsWith(".") || s.startsWith("/")) return "";
  if (s.startsWith("@")) return s.split("/").slice(0, 2).join("/");
  return s.split("/")[0];
}

function _nodeAtTypesName(pkgName) {
  const p = String(pkgName || "");
  if (!p) return "";
  return p.startsWith("@") ? `@types/${p.slice(1).replace("/", "__")}` : `@types/${p}`;
}

function _typeEntryCandidatesFromPackageJson(pkgJson) {
  const out = [];
  const push = (value) => {
    if (typeof value !== "string" || !value.trim()) return;
    let v = value.trim().replace(/^\.\//, "");
    if (v.endsWith(".js")) out.push(v.replace(/\.js$/, ".d.ts"), v.replace(/\.js$/, ".d.mts"));
    else if (v.endsWith(".mjs")) out.push(v.replace(/\.mjs$/, ".d.mts"), v.replace(/\.mjs$/, ".d.ts"));
    else out.push(v);
  };
  const scanExport = (value) => {
    if (!value) return;
    if (typeof value === "string") { push(value); return; }
    if (typeof value !== "object") return;
    push(value.types);
    push(value.typings);
    push(value.import);
    push(value.default);
    for (const nested of Object.values(value)) {
      if (nested && typeof nested === "object") scanExport(nested);
    }
  };
  push(pkgJson?.types);
  push(pkgJson?.typings);
  const exp = pkgJson?.exports;
  if (exp) {
    if (typeof exp === "string" || exp.types || exp.typings || exp.import || exp.default) scanExport(exp);
    else if (typeof exp === "object") scanExport(exp["."] || exp);
  }
  out.push("index.d.ts", "index.d.mts", "dist/index.d.ts", "dist/index.d.mts", "dist/node/index.d.ts", "types/index.d.ts");
  return [...new Set(out.map((p) => p.replace(/\\/g, "/")).filter((p) => p && !p.startsWith("../") && !p.includes("/../")))];
}

/*
 * 读一个包的类型入口。**跟随 re-export**，最多再跟 8 个兄弟文件。
 *
 * 只读入口那一个 `.d.ts` 是不够的：现代库的入口几乎全是再导出——
 *     export * from "./types";
 *     export { defineConfig } from "./config";
 * 入口文件里一个具体符号都没有。于是"这个包导出了什么"永远是空的，下面那个垫片就只能
 * 无条件把每个符号都声明成 `any`，TS 的类型检查对第三方 API 彻底失效（诊断必然是绿的，
 * 参数写错、方法不存在都查不出来）。
 *
 * 有界：8 个文件、总字节仍受 TS_PACKAGE_TYPE_MAX_BYTES 管。跟不动就跟不动——
 * 拿到多少算多少，剩下的交给垫片补，不会比以前更差。
 */
const TS_TYPE_REEXPORT_MAX_FILES = 8;

async function _readPackageTypeEntry(root, pkgName) {
  const pkgRoot = `${root.replace(/\/+$/, "")}/node_modules/${pkgName}`;
  let pkgJson = {};
  try { pkgJson = JSON.parse(await backend.readTextFile(`${pkgRoot}/package.json`)); } catch {}
  for (const rel of _typeEntryCandidatesFromPackageJson(pkgJson)) {
    try {
      const path = `${pkgRoot}/${rel}`;
      const content = await backend.readTextFile(path);
      if (!content || content.length > TS_PACKAGE_TYPE_MAX_BYTES) continue;
      const followed = await _followTypeReexports(path, content);
      return { path, content, exports: _extractExportNames(followed) };
    } catch {}
  }
  return null;
}

/** 入口 + 它再导出的兄弟文件，拼成一段用来**抽导出名**的文本（不进 TS 服务，只做判断）。 */
async function _followTypeReexports(entryPath, entryContent) {
  const dir = entryPath.slice(0, entryPath.lastIndexOf("/"));
  const seen = new Set([entryPath]);
  let combined = entryContent;
  const rels = new Set();
  for (const re of [
    /export\s+\*\s+from\s+["']([^"']+)["']/g,
    /export\s*\{[^}]*\}\s*from\s+["']([^"']+)["']/g,
    /\/\/\/\s*<reference\s+path=["']([^"']+)["']/g,
  ]) {
    let m;
    while ((m = re.exec(entryContent))) rels.add(m[1]);
  }
  for (const rel of [...rels].slice(0, TS_TYPE_REEXPORT_MAX_FILES)) {
    if (!rel.startsWith(".")) continue;                 // 只跟相对路径，不追别的包
    const base = `${dir}/${rel}`.replace(/\/\.\//g, "/");
    for (const cand of [base, `${base}.d.ts`, `${base}/index.d.ts`]) {
      if (seen.has(cand)) continue;
      seen.add(cand);
      try {
        const text = await backend.readTextFile(cand);
        if (text && combined.length + text.length <= TS_PACKAGE_TYPE_MAX_BYTES) {
          combined += "\n" + text;
          break;
        }
      } catch {}
    }
  }
  return combined;
}

/*
 * 给一个包补一份 ambient 声明，把 import 里用到、但真类型没覆盖到的名字声明成 any。
 *
 * `knownExports` 是关键：以前这个垫片是**无条件全量**的，而 ambient module declaration
 * 会盖过 node_modules 的正常解析——于是就算真类型读到了，第三方符号的实际类型仍然是
 * `any`，参数写错、方法不存在，`get_diagnostics` 一律绿灯。TS 那条"能把幻觉当场打回"
 * 的防线整个是断的。
 *
 * 现在只补真类型**确实没有**的那些名字。失败方向也选对了：`knownExports` 拿不到（没读到
 * 类型、或者 re-export 跟不动）时它是空集，行为退回从前——宁可多一个 any，也不要凭一份
 * 不完整的解析报「模块里没有这个导出」的假红。
 */
function _makeInstalledPackageShim(specifier, details, knownExports = null) {
  const known = knownExports instanceof Set ? knownExports : new Set(knownExports || []);
  const names = [...(details?.named || [])]
    .filter((name) => /^[A-Za-z_$][\w$]*$/.test(name))
    .filter((name) => !known.has(name));
  const lines = [`declare module ${JSON.stringify(specifier)} {`];
  for (const name of names) lines.push(`  export const ${name}: any;`);
  const needDefault = details?.hasDefault && !known.has("default");
  if (needDefault) {
    lines.push("  const _default: any;");
    lines.push("  export default _default;");
  }
  // 具名和默认都不用补 = 真类型全覆盖了，返回空串让调用方整份跳过。
  if (names.length === 0 && !needDefault) return "";
  lines.push("}");
  return lines.join("\n");
}

function _disposeTsPackageTypesForRoot(root) {
  const keyPrefix = `${root.replace(/\/+$/, "")}:`;
  for (const [key, disposers] of _tsPackageTypeDisposers.entries()) {
    if (!key.startsWith(keyPrefix)) continue;
    for (const d of disposers) { try { d.dispose?.(); } catch {} }
    _tsPackageTypeDisposers.delete(key);
  }
}

function _modelFsPath(model) {
  return _normalizeFsPath(model?.uri?.fsPath || model?.uri?.path || "");
}
function _modelForExactPath(models, path) {
  const want = _pathIdentity(path);
  if (!want) return null;
  return (Array.isArray(models) ? models : []).find((model) =>
    _pathIdentity(_modelFsPath(model)) === want) || null;
}
function _modelBelongsToRoot(model, root) {
  const fp = _modelFsPath(model);
  return !!(fp && root && _pathIsAtOrUnder(fp, root));
}
function _isJsTsJsonModel(model) {
  const lang = model?.getLanguageId?.();
  return lang === "typescript" || lang === "javascript" || lang === "json";
}
function _clearGeneratedDependencyMarkers(root) {
  for (const model of monaco.editor.getModels()) {
    if (root && !_modelBelongsToRoot(model, root)) continue;
    const fp = _modelFsPath(model);
    if (_isGeneratedDependencyDiagnosticPath(fp)) {
      try { monaco.editor.setModelMarkers(model, "typescript", []); } catch {}
      try { monaco.editor.setModelMarkers(model, "javascript", []); } catch {}
      try { monaco.editor.setModelMarkers(model, "json", []); } catch {}
    }
  }
}
function _clearJsTsJsonMarkersForRoot(root) {
  for (const model of monaco.editor.getModels()) {
    if (!_isJsTsJsonModel(model) || (root && !_modelBelongsToRoot(model, root))) continue;
    try { monaco.editor.setModelMarkers(model, "typescript", []); } catch {}
    try { monaco.editor.setModelMarkers(model, "javascript", []); } catch {}
    try { monaco.editor.setModelMarkers(model, "json", []); } catch {}
  }
}
/**
 * 把 tsconfig.json / jsconfig.json 里的 `baseUrl` + `paths` 灌进 Monaco 的 TS 服务。
 *
 * 不灌的后果：`import Button from "@/components/Button"` 这类路径别名解析不了，于是
 * 满屏 "Cannot find module" 红波浪线，F12 跳不动，悬停也没有类型。而现代的 Next.js /
 * Vite-React 模板几乎默认就带 `@/*` 别名——打开一个新项目第一眼就是一片红。
 *
 * tsconfig 是 JSONC：允许 `//` `/* *\/` 注释和尾逗号。JSON.parse 直接吃会抛，所以先剥。
 * 剥的时候必须避开字符串字面量里的 `//`（比如 "https://..."），否则会把值截断。
 */
function _stripJsonc(text) {
  let out = "";
  let inStr = false, esc = false, inLine = false, inBlock = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i], n = text[i + 1];
    if (inLine) { if (c === "\n") { inLine = false; out += c; } continue; }
    if (inBlock) { if (c === "*" && n === "/") { inBlock = false; i++; } continue; }
    if (inStr) {
      out += c;
      if (esc) esc = false;
      else if (c === "\\") esc = true;
      else if (c === '"') inStr = false;
      continue;
    }
    if (c === '"') { inStr = true; out += c; continue; }
    if (c === "/" && n === "/") { inLine = true; i++; continue; }
    if (c === "/" && n === "*") { inBlock = true; i++; continue; }
    out += c;
  }
  // 尾逗号：`,` 后面只跟空白再跟 `}` 或 `]`。
  return out.replace(/,(\s*[}\]])/g, "$1");
}

/**
 * 从 tsconfig 的 compilerOptions 推出要喂给 Monaco 的 baseUrl / paths（都转成绝对路径）。
 *
 * `.` 和 `..` 必须归一。`"baseUrl": "."` 是最常见的写法，不归一会得到 `/ws/.`，
 * 而 paths 目标会变成 `/ws/./src/*` —— TS 的路径匹配是纯字符串前缀比较，多一个 `.`
 * 就永远匹配不上项目里那些 `/ws/src/...` 的 model URI，别名照样解析不了。
 */
function _tsPathsFromConfig(root, configDir, compilerOptions) {
  const co = compilerOptions || {};
  const join = (a, b) => {
    const raw = `${String(a).replace(/\/+$/, "")}/${String(b).replace(/^\/+/, "")}`;
    const abs = raw.startsWith("/");
    const out = [];
    for (const seg of raw.split("/")) {
      if (!seg || seg === ".") continue;
      if (seg === ".." && out.length && out[out.length - 1] !== "..") { out.pop(); continue; }
      out.push(seg);
    }
    // 结尾的 `*` 之类通配要保住，split/join 天然保留。
    return (abs ? "/" : "") + out.join("/");
  };
  const baseUrl = co.baseUrl ? join(configDir, co.baseUrl) : configDir;
  const paths = {};
  for (const [k, v] of Object.entries(co.paths || {})) {
    if (!Array.isArray(v)) continue;
    // paths 的目标是相对 baseUrl 的；Monaco 的 model URI 是绝对路径，所以这里也要绝对化。
    paths[k] = v.map((t) => (String(t).startsWith("/") ? String(t) : join(baseUrl, t)));
  }
  return { baseUrl, paths, hasPaths: Object.keys(paths).length > 0, root };
}

let _tsConfigRoot = "";
/** 打开/切换工作区时调用：读项目的 tsconfig 并重配 TS 服务。 */
async function _applyProjectTsConfig(root) {
  root = String(root || "").replace(/\/+$/, "");
  if (!root || root === _tsConfigRoot) return null;
  for (const name of ["tsconfig.json", "jsconfig.json"]) {
    let text;
    try { text = await backend.readTextFile(`${root}/${name}`); } catch { continue; }
    if (typeof text !== "string" || !text.trim()) continue;
    let parsed;
    try { parsed = JSON.parse(_stripJsonc(text)); } catch { continue; }
    const derived = _tsPathsFromConfig(root, root, parsed.compilerOptions);
    if (!derived.hasPaths) continue;
    try {
      const ts = monaco.languages.typescript;
      for (const d of [ts.typescriptDefaults, ts.javascriptDefaults]) {
        d.setCompilerOptions({ ...d.getCompilerOptions(), baseUrl: derived.baseUrl, paths: derived.paths });
      }
      _tsConfigRoot = root;
      return derived;
    } catch { return null; }
  }
  _tsConfigRoot = root; // 没有 tsconfig 也记下来，别每次切文件都重读
  return null;
}

function _restartJsTsLanguageService() {
  try {
    configureLanguageService();
    const ts = monaco.languages.typescript;
    // Toggle eager sync to force Monaco to spin a fresh TS/JS worker view after
    // node_modules/package metadata changed. Otherwise stale "Cannot find module"
    // diagnostics can survive a successful npm install until the user reloads.
    for (const d of [ts.typescriptDefaults, ts.javascriptDefaults]) {
      d.setEagerModelSync(false);
      d.setEagerModelSync(true);
    }
  } catch {}
}

function _refreshLspDocumentsForRoot(root) {
  /*
   * 这里原来还有一段「refreshWorkspace 不可用时的降级同步」——遍历 openFiles 逐个
   * didChange + didSave。它在**任何输入下都不产生任何效果**：lspManager 非 null 时
   * 上一行就 return 了，循环永不执行；lspManager 为 null 时进得了循环，但循环体全是
   * `lspManager?.` 可选链，一次调用都不会发生。
   *
   * 留着比删了更坏：它看起来像一条独立的兜底路径，会让人以为换工作区时开着的文件
   * 另有保障，从而不去检查 refreshWorkspace 自己的过滤条件覆盖没覆盖到目标文件。
   */
  try { lspManager?.refreshWorkspace?.(root); } catch {}
}

async function refreshProjectCaches(root = rootPath, reason = "项目刷新") {
  const targetRoot = _normalizeFsPath(String(root || rootPath || workspaceRoots[0] || "")).replace(/\/+$/, "");
  if (!targetRoot) return;
  const token = ++_tsPackageTypeRefreshToken;
  _agentContextCache.ts = 0;
  _clearJsTsJsonMarkersForRoot(targetRoot);
  _clearGeneratedDependencyMarkers(targetRoot);
  try {
    if (workspaceRoots.includes(targetRoot)) await reloadDir(targetRoot);
    else await reloadDir(rootPath || workspaceRoots[0] || targetRoot);
  } catch {}
  try { await preloadProjectModels(targetRoot); } catch {}

  const imports = new Map();
  for (const model of monaco.editor.getModels()) {
    const fp = _normalizeFsPath(model.uri?.fsPath || model.uri?.path || "");
    if (!fp || !(_pathIsAtOrUnder(fp, targetRoot)) || fp.includes("/node_modules/")) continue;
    const lang = model.getLanguageId?.();
    if (lang !== "typescript" && lang !== "javascript") continue;
    for (const [spec, details] of _jsTsImportSpecifiersFromText(model.getValue())) {
      const entry = imports.get(spec) || { named: new Set(), hasDefault: false, hasNamespace: false };
      for (const name of details.named || []) entry.named.add(name);
      entry.hasDefault = entry.hasDefault || details.hasDefault;
      entry.hasNamespace = entry.hasNamespace || details.hasNamespace;
      imports.set(spec, entry);
    }
  }

  _disposeTsPackageTypesForRoot(targetRoot);
  let loaded = 0;
  for (const [specifier, details] of imports.entries()) {
    if (token !== _tsPackageTypeRefreshToken || loaded >= TS_PACKAGE_TYPE_MAX_LIBS) break;
    const pkgName = _nodePackageNameFromSpecifier(specifier);
    if (!pkgName) continue;
    const disposers = [];
    const realType = await _readPackageTypeEntry(targetRoot, pkgName)
      || await _readPackageTypeEntry(targetRoot, _nodeAtTypesName(pkgName));
    try {
      if (realType) {
        for (const d of [monaco.languages.typescript.typescriptDefaults, monaco.languages.typescript.javascriptDefaults]) {
          disposers.push(d.addExtraLib(realType.content, monaco.Uri.file(realType.path).toString()));
        }
      }
      const shimPath = `${targetRoot}/node_modules/.mrdayone-ide-types/${specifier.replace(/[^\w.-]+/g, "__")}.d.ts`;
      // 真类型覆盖到的名字不再垫——垫了就会盖住它，类型检查对这个包彻底失效。
      const shim = _makeInstalledPackageShim(specifier, details, realType?.exports || null);
      // 一个名字都不用补时就别加这份 ambient 声明：加了照样会遮蔽真解析。
      if (shim) {
        for (const d of [monaco.languages.typescript.typescriptDefaults, monaco.languages.typescript.javascriptDefaults]) {
          disposers.push(d.addExtraLib(shim, monaco.Uri.file(shimPath).toString()));
        }
      }
      _tsPackageTypeDisposers.set(`${targetRoot}:${specifier}`, disposers);
      loaded++;
    } catch {
      for (const d of disposers) { try { d.dispose?.(); } catch {} }
    }
  }
  _restartJsTsLanguageService();
  _clearGeneratedDependencyMarkers(targetRoot);
  _refreshLspDocumentsForRoot(targetRoot);
  setTimeout(() => _clearGeneratedDependencyMarkers(targetRoot), 1200);
  try { await refreshGitStatus(); } catch {}
  // （不再弹“已刷新文件树和 JS/TS 诊断缓存” toast：刷新是后台自动行为，无需打扰用户）
}

function scheduleProjectCacheRefresh(root = rootPath, reason = "项目刷新") {
  if (_tsPackageTypeRefreshTimer) clearTimeout(_tsPackageTypeRefreshTimer);
  _tsPackageTypeRefreshTimer = setTimeout(() => {
    refreshProjectCaches(root, reason).catch(() => {});
  }, 250);
}

// ---- diagnostics / problems panel ----
const SEV = monaco.MarkerSeverity;
const problemsPanel = $("problemsPanel");
const problemsBody = $("problemsBody");
const problemsPanelCounts = $("problemsPanelCounts");

function pathBase(p) {
  return p.slice(p.lastIndexOf("/") + 1);
}
