  budget.remaining = Math.max(0, Number(budget.remaining) || 0);
  const text = textBudget && typeof textBudget === "object"
    ? textBudget
    : { remaining: Math.max(0, Number(textBudget) || 0), perValue: CHAT_LOCAL_TEXT_PER_VALUE };
