  const localTextBudget = { remaining: CHAT_LOCAL_TEXT_BUDGET, perValue: CHAT_LOCAL_TEXT_PER_VALUE };
  const localOptions = {
    recentLimit: CHAT_LOCAL_RECENT_LIMIT,
    transcriptLimit: CHAT_LOCAL_RECENT_LIMIT,
    textBudget: localTextBudget,
  };
