function _simpleShellWords(segment) {
  const words = [];
  let cur = "", quote = "";
  const s = String(segment || "").trim();
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (quote) {
      if (ch === "\\") { if (i + 1 < s.length) cur += s[++i]; continue; }
      if (ch === quote) { quote = ""; continue; }
      cur += ch;
      continue;
    }
    if (ch === "'" || ch === '"') { quote = ch; continue; }
    if (/\s/.test(ch)) {
      if (cur) { words.push(cur); cur = ""; }
      continue;
    }
    if (ch === "\\") { if (i + 1 < s.length) cur += s[++i]; continue; }
    cur += ch;
  }
  if (quote) return [];
  if (cur) words.push(cur);
  return words;
}

function _isDependencyRestoreOutputPipeSegment(segment) {
  const value = String(segment || "").trim();
  if (!value || /[\r\n;<>`]|\$\(|(?:^|[^&])&([^&]|$)/.test(value)) return false;
  return /^(?:head|tail|wc|sort|uniq|cut|tr|grep|rg|jq|sed\s+-n|cat)(?:\s+[^;&|<>`]*)?$/i.test(value);
}

function _isDependencyRestoreSegment(segment) {
  let words = _simpleShellWords(segment);
  while (words.length && /^[A-Za-z_][A-Za-z0-9_]*=.+$/.test(words[0])) words = words.slice(1);
  if (!words.length) return false;
  const allOptions = (rest) => rest.every((word) => /^-{1,2}[\w.:@/=-]+$/.test(String(word || "")));
  const cmd = String(words[0] || "").toLowerCase();
  const sub = String(words[1] || "").toLowerCase();
  if (cmd === "npm" && /^(?:install|i|ci)$/.test(sub)) return allOptions(words.slice(2));
  if (cmd === "pnpm" && /^(?:install|i)$/.test(sub)) return allOptions(words.slice(2));
  if (cmd === "yarn") {
    if (!sub) return true;
    if (sub === "install") return allOptions(words.slice(2));
    return false;
  }
  if (cmd === "bun" && /^(?:install|i)$/.test(sub)) return allOptions(words.slice(2));
  return false;
}

function _isDependencyRestoreCommand(command) {
  const raw = (typeof _stripHarmlessRedirects === "function" ? _stripHarmlessRedirects(command) : String(command || "")).trim();
  if (!raw || /[\r\n;<>`]|\$\(/.test(raw)) return false;
  if (/(^|[^&])&([^&]|$)/.test(raw)) return false;
  const orParts = raw.split(/\s*\|\|\s*/).map((segment) => segment.trim()).filter(Boolean);
  if (orParts.length === 2) {
    return _looksLikeReadOnlyCommand(orParts[0]) && _isDependencyRestoreCommand(orParts[1]);
  }
  if (orParts.length > 2) return false;
  if (raw.includes("|")) {
    const parts = raw.split(/\s*\|\s*/).map((segment) => segment.trim()).filter(Boolean);
    return parts.length > 1
      && _isDependencyRestoreCommand(parts[0])
      && parts.slice(1).every(_isDependencyRestoreOutputPipeSegment);
  }
  const segments = raw.split(/\s*&&\s*/).map((segment) => segment.trim()).filter(Boolean);
  let sawRestore = false;
  for (const segment of segments) {
    if (_isDependencyRestoreSegment(segment)) { sawRestore = true; continue; }
    if (_looksLikeReadOnlyCommand(segment)) continue;
    return false;
  }
  return sawRestore;
}

function _agentSideEffectIntentIssue(call, run) {
  // Semantic profiles guide prompt construction and the initial tool window; they are
  // not an execution authorization system. An Agent may use any registered tool, and
  // concrete executors remain responsible for factual failures such as invalid args,
  // unavailable transports, workspace mismatch, and file conflicts.
  void call;
  void run;
  return "";
}

function _agentCommandTimeoutSecs(command) {
  const raw = String(command || "").trim();
  if (!raw) return 60;
  const cleaned = (typeof _stripHarmlessRedirects === "function" ? _stripHarmlessRedirects(raw) : raw).trim();
  const depInstall = _isDependencyRestoreCommand(cleaned)
    || /^(?:npm|pnpm|yarn|bun)\s+(?:install|i|ci)\b/i.test(cleaned)
    || /^(?:pip3?|python\d*\s+-m\s+pip)\s+install\b/i.test(cleaned)
    || /^cargo\s+(?:add|install|update)\b/i.test(cleaned)
    || /^go\s+(?:get|mod\s+download)\b/i.test(cleaned);
  if (depInstall) return 600;
  if (
    /^(?:npm|pnpm|yarn|bun)(?:\s+run)?\s+(?:build|test|lint|check|typecheck|compile|verify|package|preview)\b/i.test(cleaned)
    || /^cargo\s+(?:check|build|test|clippy|fmt)\b/i.test(cleaned)
    || /^go\s+(?:build|test)\b/i.test(cleaned)
    || /^(?:pytest|ruff\s+check)\b/i.test(cleaned)
    || /^(?:(?:npx(?:\s+-y|\s+--no-install)?|npm\s+exec)\s+)?tsc\b(?=.*(?:^|\s)--noEmit(?:\s|$))/i.test(cleaned)
    || /^python\d*\s+-m\s+(?:compileall|py_compile)\b/i.test(cleaned)
    || /^(?:mvn|gradle\w*|\.\/gradlew)\s+(?:test|check|build|verify)\b/i.test(cleaned)
    || /^dotnet\s+(?:test|build)\b/i.test(cleaned)
  ) return 300;
  if (_looksLikeVerificationCommand(cleaned)) return 240;
  if (_looksLikeReadOnlyCommand(cleaned)) return 120;
  return 240;
}


// CSS grounding for weaker models: concrete, COPY-ABLE code tokens + component
