    const tok = (typeof localStorage !== "undefined" && localStorage.getItem("michael_token")) || "";
    if (!tok) return;
    const base = (typeof _michaelBase === "function") ? _michaelBase() : (typeof MICHAEL_API !== "undefined" ? MICHAEL_API : "");
    const url = base + "/api/ide-prompts";
    let j = null;
