    const finish = (value) => { if (!settled) { settled = true; resolve(value); } };
    const timer = setTimeout(() => finish({ status: "timeout", latitude: null, longitude: null, accuracyM: null, source: "web_geolocation", message: "定位请求等待超时。" }), 9000);
