  const path = String(callPath || quotedPath?.[1] || "").trim();
  const safePath = path ? path.replace(/\\/g, "\\\\").replace(/"/g, "\\\"") : "";
  const readStep = safePath ? `read_file("${safePath}")` : "read_file 读取目标文件";
  const target = path || "目标文件";
