// 真·多智能体上下文协议：把 run 上的共享上下文（run.ctx = 主循环的运行草稿纸）渲染成一段
// 开局摘要塞给子智能体/worker，让它**站在主智能体已有的进度上**干活——知道总目标、已读过哪些
// 文件、已改了什么、已知的关键发现——不必从零重查、也不会跟主智能体的判断跑偏。空 → "".
function _sharedCtxDigest(ctx) {
  if (!ctx) return "";
  const p = [];
  if (ctx.goal) p.push(`· 总目标：${ctx.goal}`);
  if (ctx.requirements && ctx.requirements.length) p.push(`· 原始需求：${ctx.requirements.map((item, index) => `${index + 1}.${item}`).join(" | ")}`);
  if (ctx.done && ctx.done.length) p.push(`· 主智能体已完成：${ctx.done.slice(-8).join(" → ")}`);
  if (ctx.modified && ctx.modified.size) p.push(`· 已改的文件：${_fmtModified(ctx.modified, "、")}`);
  if (ctx.filesRead && ctx.filesRead.size) p.push(`· 已读过（不必重读，除非你要改它）：${[...ctx.filesRead].slice(-40).join("、")}`);
  // P0.1 关键片段：主 run 已读文件的内容摘要（由 _subAgentFileSnippets 从读取缓存提取，
  // 每文件 ≤1500 字、总量 ≤8K）——只传文件名不传内容正是子智能体重复劳动的主因。
  if (ctx.fileSnippets && ctx.fileSnippets.size) {
    const snippets = [...ctx.fileSnippets].map(([path, snippet]) => `── ${path} ──\n${snippet}`).join("\n");
    p.push(`· 已读文件关键片段（直接引用，不必重读）：\n${snippets}`);
  }
  if (ctx.findings && ctx.findings.length) p.push(`· 已知关键发现：${ctx.findings.slice(-8).join("；")}`);
  if (ctx.errors && ctx.errors.length) p.push(`· 当前未解决的错误：${ctx.errors.slice(-3).join("；")}`);
  return p.length ? `【主智能体已经掌握的上下文——直接接着用，别从零重查】\n${p.join("\n")}` : "";
}
// P0.1 已读文件内容摘要：从主 run 的读取缓存（_agentReadCache）里把 ctx.filesRead 命中的
// 文件内容压成每文件 ≤1500 字的摘要（头尾+错误行优先，复用 _clipPreservingErrors），
// 总量硬上限 8K——token 经济：宁可少带几个文件，不把子智能体请求撑爆。
function _subAgentFileSnippets(ctx, root, perFileMax = 1500, totalMax = 8000) {
  const out = new Map();
  if (!ctx || !ctx.filesRead || !ctx.filesRead.size) return out;
  let total = 0;
  // 最近读的排前面（离当前任务最近、相关性最高）
  for (const rel of [...ctx.filesRead].slice(-12).reverse()) {
    if (total >= totalMax || out.size >= 8) break;
    const abs = root ? _resolveRel(rel, root) : rel;
    const text = _agentReadCache.get(abs) ?? _agentReadCache.get(rel);
    if (typeof text !== "string" || !text.trim()) continue;
    const clip = _clipPreservingErrors(text, Math.min(perFileMax, totalMax - total));
    if (!clip) continue;
    out.set(rel, clip);
    total += clip.length;
  }
  return out;
}
function _sessionFileEvidenceBlock(session, root, limit = 8) {
  const memory = session?.memory;
  if (!root || typeof memory?.fileEvidenceForRoot !== "function") return "";
  const entries = memory.fileEvidenceForRoot(root).sort((a, b) => (b.updatedAt || 0) - (a.updatedAt || 0)).slice(0, limit);
  if (!entries.length) return "";
  const lines = entries.map((entry) => {
    const ranges = (entry.ranges || []).map((range) => `${range[0]}-${range[1]}`).join(",") || "未记录范围";
    const digest = String(entry.digest || "").replace(/\s+/g, " ").slice(0, 180);
    return `· ${entry.path} · 版本 ${entry.signature} · 已读 ${ranges}/${entry.total || "?"}${entry.complete ? "（完整）" : ""}${digest ? ` · 摘要: ${digest}` : ""}`;
  });
  return `〔本会话文件证据账本——复用已知路径与结论，不要重新 search 定位；逐字符修改所需原文若已离开当前上下文，只精读目标文件/范围〕\n${lines.join("\n")}`;
}

// 主↔子实时通道已搬到 src/agent/mainlink.js（见那边的文件头说明）。
// 这里留三个同名薄壳：调用点一个都不用改，而 store 的默认值留在 main.js 这一侧——
// 模块本身不认识那个全局单例，测试可以拿干净的 store 直接驱动它。
const _smRunToken = (run) => _mainlinkRunToken(run);
const _drainSubAgentCollaborationInbox = (store, jobId, cursor = 0, maxItems = 6, maxChars = 1600) =>
  _mainlinkDrain(store || _globalSharedStore, jobId, cursor, maxItems, maxChars);
const _broadcastMainAgentFinding = (run, text, store = _globalSharedStore) =>
  _mainlinkBroadcast(run, text, store);

// A collaboration session owns SharedStore subscriptions. A run can end through
// a normal completion, Stop, a replacement turn, or an exception, so all terminal
// paths must use this one idempotent release instead of relying on await_subagent.
function _endRunCollaborationSession(run, status = "completed") {
  const sessionId = run?._collabSession;
  if (!sessionId) return false;

  const mainJobId = run._collabMainJobId;
  // Clear ownership before calling out: await_subagent and the run finally can
  // meet in the same turn, and only the first one may close the session.
  run._collabSession = null;
  run._collabMainJobId = null;

  const engine = typeof window !== "undefined" ? window.collaborationEngine : null;
  if (!engine || typeof engine.endSession !== "function") return false;
  try {
    if (mainJobId && _globalSharedStore?.updateJobStatus) {
      _globalSharedStore.updateJobStatus(mainJobId, status, status === "completed" ? 100 : undefined);
    }
    return engine.endSession(sessionId) === true;
  } catch {
    return false;
  }
}

function _broadcastSubAgentCollaborationFinding(store, sourceJobId, peerJobIds, call, result, maxChars = 420) {
  if (!store || typeof store.appendFinding !== "function" || sourceJobId == null || sourceJobId === "") return 0;
  const raw = String(result?.content || "").slice(0, Math.max(320, maxChars * 4)).replace(/\s+/g, " ").trim();
  if (!raw || /^\[(?:ERROR|BLOCKED|interrupted)/i.test(raw)) return 0;
  const tool = String(call?._toolName || call?.type || "tool").replace(/\s+/g, " ").slice(0, 64);
  const path = String(call?.path || result?.path || "").replace(/\s+/g, " ").trim().slice(0, 120);
  const content = `[${tool}${path ? ` · ${path}` : ""}] ${raw}`.slice(0, Math.max(80, maxChars));
  let delivered = 0;
  for (const peerId of new Set(Array.isArray(peerJobIds) ? peerJobIds : [])) {
    if (peerId == null || peerId === "" || String(peerId) === String(sourceJobId)) continue;
    try {
      store.appendFinding(`sm_${peerId}`, {
        source: `sm_${sourceJobId}`,
        channel: "collaboration",
        content,
        isExternal: true,
      });
      delivered++;
    } catch {}
  }
  return delivered;
}

