const DISABLED_BINDING = "__none__";

function isMacPlatform(platform = navigator.platform) {
  return /Mac|iPhone|iPad|iPod/i.test(String(platform || ""));
}

/*
 * 组合键的显示。
 *
 * Mac 用符号（⌘⇧⌥⌃⏎⌫），Windows/Linux 用词（Ctrl/Shift/Alt/Enter/Backspace）——
 * 这不是风格偏好：⇧ ⏎ ⌫ 这些字形在 Windows 上既不是系统习惯，很多字体里还缺字，
 * 会渲染成方框。上一版只有 mod/ctrl/alt/meta 做了分支，shift/enter/backspace 三个
 * 无论什么平台都吐 Mac 符号。
 */
function formatCombo(combo) {
  const isMac = isMacPlatform();
  const map = {
    mod: isMac ? "\u2318" : "Ctrl",
    ctrl: isMac ? "\u2303" : "Ctrl",
    shift: isMac ? "\u21e7" : "Shift",
    alt: isMac ? "\u2325" : "Alt",
    meta: isMac ? "\u2318" : "Win",
    enter: isMac ? "\u21a9" : "Enter",
    escape: "Esc",
    esc: "Esc",
    backspace: isMac ? "\u232b" : "Backspace",
    delete: isMac ? "\u2326" : "Delete",
    tab: isMac ? "\u21e5" : "Tab",
    up: isMac ? "\u2191" : "Up",
    down: isMac ? "\u2193" : "Down",
    left: isMac ? "\u2190" : "Left",
    right: isMac ? "\u2192" : "Right",
    " ": "Space",
    space: "Space",
  };
  /*
   * 修饰键的**顺序**也是平台习惯的一部分。
   *
   * 绑定表里写的是 "shift+mod+e"（Mac 顺序：⇧⌘E）。照着原样渲染，Windows 用户看到的是
   * "Shift+Ctrl+E"——而 Windows 的写法一律是 Ctrl 在最前：Ctrl+Shift+E。顺序反了不影响
   * 按键生效，但用户照着念、照着找、跟别的软件对不上，读起来就是"这软件不是给我做的"。
   */
  const WIN_MODIFIER_ORDER = ["Ctrl", "Win", "Alt", "Shift"];
  const rendered = combo.split("+").map((part) => {
    if (map[part]) return map[part];
    return part.length === 1 ? part.toUpperCase() : part.charAt(0).toUpperCase() + part.slice(1);
  });
  if (isMac) return rendered;
  const mods = rendered.filter((k) => WIN_MODIFIER_ORDER.includes(k));
  const rest = rendered.filter((k) => !WIN_MODIFIER_ORDER.includes(k));
  mods.sort((a, b) => WIN_MODIFIER_ORDER.indexOf(a) - WIN_MODIFIER_ORDER.indexOf(b));
  return [...mods, ...rest];
}

/*
 * 文本形式的组合键（菜单项右侧、提示语里用）。
 *
 * Mac 上符号连写就是系统习惯（⌘⇧P）；Windows 上词与词之间必须有加号，否则
 * "CtrlShiftP" 根本读不断句。
 */
function shortcutLabel(combo) {
  return formatCombo(combo).join(isMacPlatform() ? "" : "+");
}

function renderKbdCombo(container, combo) {
  if (!container) return;
  const label = container.querySelector("span");
  container.innerHTML = "";
  for (const key of formatCombo(combo)) {
    const kbd = document.createElement("kbd");
    kbd.textContent = key;
    container.appendChild(kbd);
  }
  if (label) {
    container.appendChild(document.createTextNode(" "));
    container.appendChild(label);
  }
}

/*
 * 给一个按钮写「名字 (组合键)」的 title。
 *
 * `labelKey` 传的是 i18n 的 key，不是写死的中文——这两个按钮的 `data-i18n-title` 标记已经
 * 摘掉了（那个标记会让 i18n 的属性观察器在下一帧把 title 改回词条原文，组合键当场丢失），
 * 所以本地化得在这里自己做。摘标记 + 在这儿取词条 = 只有一个写者，不会来回打架。
 */
function setShortcutTitle(id, labelKey, combo, fallback) {
  const el = $(id);
  if (!el) return;
  let label = fallback || labelKey;
  try { const v = t(labelKey); if (v && v !== labelKey) label = v; } catch {}
  el.title = `${label} (${shortcutLabel(combo)})`;
  if (el.hasAttribute("aria-label")) el.setAttribute("aria-label", el.title);
}

/*
 * 界面上所有快捷键的显示，唯一的出处。
 *
 * 规矩：**任何地方都不许把组合键写进静态文案或 i18n 词条**。写进去就有两个后果——
 * 一是 ⌘⌥⌃⇧↩⌫ 这些字形在 Windows 的 Segoe UI 里缺字，会掉到回落字体变成异体字符
 * （读屏还会念出来）；二是它和这里互相打架：i18n 的属性观察器盯着 title，会把这里刚
 * 写好的「切换终端 (Ctrl+`)」换回词条里那份带 ⌃ 的。所以词条只给名字，组合键在这儿拼。
 *
 * 语言切换之后要重跑一次（见 onLocaleChange 那处）——否则新语言的词条一铺上去，
 * 这里的平台化结果就没了。
 */
function applyPlatformShortcutLabels() {
  setShortcutTitle("runBtn", "toolbar.run", "mod+r", "运行当前文件");
  setShortcutTitle("tabExplorer", "explorer.title", "shift+mod+e", "文件");
  setShortcutTitle("tabGit", "git.title", "ctrl+shift+g", "Git");
  setShortcutTitle("paletteBtn", "menu.commandPalette", "shift+mod+p", "命令面板");
  setShortcutTitle("termNewBtn", "terminal.new", "ctrl+shift+`", "新建终端");
  setShortcutTitle("terminalClose", "terminal.close", "ctrl+`", "关闭面板");
  // 标题栏那个终端开关以前从没被平台化过：它的 title 只有 Shell.jsx 的静态串和 i18n 词条
  // 两个来源，两份都写死 ⌃`。
  setShortcutTitle("terminalBtn", "terminal.toggle", "ctrl+`", "切换终端");

  const composerHint = document.querySelector(".composer__hint");
  if (composerHint) composerHint.textContent = shortcutLabel("mod+enter");
  const sendBtn = $("sendBtn");
  if (sendBtn) sendBtn.title = `发送 (${shortcutLabel("mod+enter")})`;

  const tips = document.querySelectorAll("#welcome .kbd-tip");
  renderKbdCombo(tips[0], "mod+o");
  renderKbdCombo(tips[1], "shift+mod+p");
  // 第三条以前是写死的 <kbd>↩</kbd>，没人管它。
  for (const tip of tips) {
    const combo = tip?.getAttribute?.("data-kbd-combo");
    if (combo) renderKbdCombo(tip, combo);
  }
}

async function rebindAction(action, newCombo) {
  const bindings = getKeybindings();
  for (const [combo, act] of Object.entries(bindings)) {
    if (act === action && combo !== newCombo) {
      if (DEFAULT_KEYBINDINGS[combo] === action) userKeybindings[combo] = DISABLED_BINDING;
      else delete userKeybindings[combo];
    }
  }
  userKeybindings[newCombo] = action;
  const store = await getStore();
  await store.set("keybindings", userKeybindings);
  await store.save();
}

async function resetKeybindings() {
  userKeybindings = {};
  const store = await getStore();
  let cleared = false;
  if (typeof store.delete === "function") {
    try {
      await store.delete("keybindings");
      cleared = true;
    } catch {}
  }
  if (!cleared) await store.set("keybindings", {});
  await store.save();
  applyPlatformShortcutLabels();
}

function recordKeybinding(action, btn, onDone) {
  if (btn.classList.contains("is-recording")) return;
  const original = btn.textContent;
  btn.textContent = "\u8bf7\u6309\u4e0b\u6309\u952e\u2026";
  btn.classList.add("is-recording");
  const cleanup = () => {
    window.removeEventListener("keydown", handler, true);
    btn.textContent = original;
    btn.classList.remove("is-recording");
  };
  const handler = async (e) => {
    e.preventDefault();
    e.stopPropagation();
    if (["Control", "Shift", "Alt", "Meta"].includes(e.key)) return;
    if (e.key === "Escape") { cleanup(); return; }
    const combo = keyCombo(e);
    cleanup();
    await rebindAction(action, combo);
    onDone();
  };
  window.addEventListener("keydown", handler, true);
}

function renderShortcutsTool(body) {
  createToolHeader(body, "键盘快捷键", "查看并自定义快捷键。点击「修改」后按下新的组合键（按 Esc 取消）。");
  const bindings = getKeybindings();
  const actionToCombo = {};
  for (const [combo, act] of Object.entries(bindings)) {
    if (!actionToCombo[act]) actionToCombo[act] = combo;
  }

  const list = document.createElement("div");
  list.className = "shortcuts-list";
  for (const action of Object.keys(ACTION_LABELS)) {
    const combo = actionToCombo[action];
    const isCustom = combo && userKeybindings[combo] === action;
    const row = document.createElement("div");
    row.className = "shortcut-row";

    const left = document.createElement("div");
    left.className = "shortcut-row__label";
    left.textContent = ACTION_LABELS[action];
    if (isCustom) {
      const badge = document.createElement("span");
      badge.className = "shortcut-row__badge";
      badge.textContent = "自定义";
      left.appendChild(badge);
    }
    row.appendChild(left);

    const keys = document.createElement("div");
    keys.className = "shortcut-row__keys";
    if (combo) {
      for (const k of formatCombo(combo)) {
        const kbd = document.createElement("kbd");
        kbd.textContent = k;
        keys.appendChild(kbd);
      }
    } else {
      const none = document.createElement("span");
      none.className = "shortcut-row__unbound";
      none.textContent = "未绑定";
      keys.appendChild(none);
    }
    row.appendChild(keys);

    const change = document.createElement("button");
    change.className = "btn btn--sm shortcut-row__change";
    change.type = "button";
    change.textContent = "修改";
    change.addEventListener("click", () => recordKeybinding(action, change, () => renderFeaturePanel()));
    row.appendChild(change);

    list.appendChild(row);
  }
  body.appendChild(list);

  const foot = document.createElement("div");
  foot.className = "tool-actions settings-actions";
  const reset = document.createElement("button");
  reset.className = "btn";
  reset.type = "button";
  reset.textContent = "全部恢复默认";
  reset.addEventListener("click", async () => {
    reset.disabled = true;
    try {
      await resetKeybindings();
      showToast("已恢复默认快捷键");
      renderFeaturePanel();
    } catch (err) {
      console.warn("Failed to reset keybindings", err);
      showToast("恢复默认快捷键失败");
    } finally {
      reset.disabled = false;
    }
  });
  foot.appendChild(reset);
  body.appendChild(foot);
}

function renderWorkspaceTool(body) {
  createToolHeader(body, "多根工作区", "把多个文件夹加入同一个工作区，再切换由哪个根目录驱动 Git、搜索、终端和语言索引。");
  const actions = document.createElement("div");
  actions.className = "tool-actions";
  const add = document.createElement("button");
  add.className = "btn btn--primary";
  add.type = "button";
  add.textContent = "添加文件夹";
  add.addEventListener("click", async () => {
    await addFolderToWorkspace();
    renderFeaturePanel();
  });
  actions.appendChild(add);
  body.appendChild(actions);

  const list = document.createElement("div");
  list.className = "tool-list";
  if (!workspaceRoots.length) {
    list.appendChild(createEmptyState("先打开一个文件夹来创建工作区。"));
  }
  for (const root of workspaceRoots) {
    const card = document.createElement("div");
    card.className = "tool-card" + (root === rootPath ? " is-active" : "");
    card.innerHTML = `<div class="tool-card__main"><strong></strong><span></span></div><div class="tool-card__actions"><button class="btn js-set-root" type="button"></button><button class="btn js-remove-root" type="button"></button></div>`;
    card.querySelector("strong").textContent = basename(root);
    card.querySelector("span").textContent = root;
    const btn = card.querySelector(".js-set-root");
    btn.textContent = root === rootPath ? "当前根目录" : "设为根目录";
    btn.disabled = root === rootPath;
    btn.addEventListener("click", async () => {
      setActiveWorkspaceRoot(root);
      await renderWorkspaceRoots();
      preloadProjectModels(root);
      await refreshGitStatus();
      renderFeaturePanel();
    });
    const removeBtn = card.querySelector(".js-remove-root");
    removeBtn.textContent = "移除";
    removeBtn.addEventListener("click", async () => {
      await removeWorkspaceRoot(root);
      renderFeaturePanel();
    });
    list.appendChild(card);
  }
  body.appendChild(list);
}

function writeToActiveTerminal(data, tries = 30) {
  const tab = typeof termTabs !== "undefined" && activeTermTab >= 0 ? termTabs[activeTermTab] : null;
  if (tab?.backendId != null) {
    backend.termWrite(tab.backendId, data);
    return;
  }
  if (tries > 0) setTimeout(() => writeToActiveTerminal(data, tries - 1), 150);
}

function shellQuote(value) {
  if (_isWin) return `"${String(value).replace(/"/g, '""')}"`;
  return `'${String(value).replace(/'/g, "'\\''")}'`;
}
const _isWin = typeof navigator !== "undefined" && navigator.platform && navigator.platform.startsWith("Win");
// 清屏命令按**真实的 shell**取，不按操作系统：`cls` 是 cmd 内建，而 Windows 上优先
// 跑的是 Git Bash——那里每次注入的第一行会变成 `bash: cls: command not found`，
// 屏幕也没清。六个注入点共用这一个值。
const _clearCmd = () => (_shellKind() === "cmd" ? "cls" : "clear");
// 和后端 augmented_path 里那份必须是同一个目录，否则 npm 装到 A、找的时候查 B。
const _michaelNpmPrefix = _isWin ? "%USERPROFILE%\\.mrdayone\\npm-global" : "$HOME/.mrdayone/npm-global";
const _nodeDebugAdapterBin = "js-debug-adapter-stdio";

function dirname(path) {
  const clean = path.replace(/\/+$/, "");
  const idx = clean.lastIndexOf("/");
  return idx > 0 ? clean.slice(0, idx) : "/";
}

function _safeRunStem(name) {
  return String(name || "current").replace(/\.[^.]+$/, "").replace(/[^A-Za-z0-9_.-]/g, "_") || "current";
}

function _tmpRunOutputPath(name, suffix = "") {
  const stem = _safeRunStem(name);
  /*
   * 判据是**真实的 shell**，不是操作系统（同 _shellKind 附近那段原则）。
   *
   * `%TEMP%` 是 cmd 的展开语法，而 Windows 上 shell_env 优先挑 Git Bash。bash 不认它，
   * 加上反斜杠在 Windows 上是目录分隔符，于是 `-o "%TEMP%\michael-ide-a"` 变成一个
   * **相对路径** `<cwd>/%TEMP%\michael-ide-a`——那个父目录不存在，rustc/fpc 也不会
   * 自己建，编译当场失败、`&&` 短路，后半段根本不执行。所以症状不是「跑出个怪东西」，
   * 是「按运行没反应，只有一句编译错」。
   *
   * Git Bash 有 /tmp（MSYS 映射），所以 posix 那一支两个平台都成立。
   */
  if (_shellKind() === "cmd") return `%TEMP%\\michael-ide-${stem}${suffix}`;
  return `/tmp/michael-ide-${stem}${suffix}`;
}

function runCommandForFile(path) {
  const name = basename(path);
  const ext = name.includes(".") ? name.split(".").pop().toLowerCase() : "";
  const q = shellQuote(path);
  const dir = shellQuote(dirname(path));
  switch (ext) {
    case "js":
    case "mjs":
    case "cjs":
      return `node ${q}`;
    case "ts":
    case "tsx":
    case "mts":
    case "cts":
    case "jsx":
      return `npx --yes tsx ${q}`;
    case "py":
    case "pyw":
      return `${_isWin ? "py -3" : "python3"} ${q}`;
    case "sh":
    case "bash":
      // Windows 上没有 bash，除非装了 Git for Windows。装了的话它在 PATH 上，这条照样成立；
      // 没装就让 shell 自己报"不是内部或外部命令"——那句话用户看得懂，比我们瞎猜一个
      // 解释器（比如硬塞 PowerShell 去跑 .sh）强。
      return `bash ${q}`;
    case "zsh":
      return `zsh ${q}`;
    case "fish":
      return `fish ${q}`;
    case "ps1":
      return `pwsh -NoProfile -ExecutionPolicy Bypass -File ${q}`;
    case "rb":
      return `ruby ${q}`;
    case "php":
      return `php ${q}`;
    case "go":
      return `go run ${q}`;
    case "rs": {
      const out = _tmpRunOutputPath(name);
      return `rustc ${q} -o ${shellQuote(out)} && ${shellQuote(out)}`;
    }
    case "java": {
      const className = name.replace(/\.java$/i, "");
      if (!/^[A-Za-z_$][A-Za-z0-9_$]*$/.test(className)) return null;
      return `cd ${dir} && javac ${shellQuote(name)} && java ${className}`;
    }
    case "kt":
    case "kts":
      return `kotlinc-jvm ${q} -include-runtime -d ${shellQuote(_tmpRunOutputPath(name, ".jar"))} && java -jar ${shellQuote(_tmpRunOutputPath(name, ".jar"))}`;
    case "swift":
      return `swift ${q}`;
    case "c": {
      const out = _tmpRunOutputPath(name);
      return `cc ${q} -o ${shellQuote(out)} && ${shellQuote(out)}`;
    }
    case "cpp":
    case "cc":
    case "c++":
    case "cxx": {
      const out = _tmpRunOutputPath(name);
      return `c++ -std=c++17 ${q} -o ${shellQuote(out)} && ${shellQuote(out)}`;
    }
    case "cs":
      return `dotnet script ${q}`;
    case "fsx":
      return `dotnet fsi ${q}`;
    case "lua":
      return `lua ${q}`;
    case "pl":
    case "pm":
      return `perl ${q}`;
    case "dart":
      return `dart ${q}`;
    case "r":
      return `Rscript ${q}`;
    case "jl":
      return `julia ${q}`;
    case "ex":
    case "exs":
      return `elixir ${q}`;
    case "erl":
      return `escript ${q}`;
    case "clj":
    case "cljs":
    case "cljc":
      return `clojure ${q}`;
    case "scala":
    case "sc":
      return `scala ${q}`;
    case "groovy":
      return `groovy ${q}`;
    case "hs":
    case "lhs":
      return `runghc ${q}`;
    case "nim":
      return `nim c -r ${q}`;
    case "zig":
      return `zig run ${q}`;
    case "v":
      return `v run ${q}`;
    case "pas":
    case "pp": {
      const out = _tmpRunOutputPath(name);
      return `fpc ${q} -o${shellQuote(out)} && ${shellQuote(out)}`;
    }
    case "m":
      return `octave ${q}`;
    case "do":
      return `stata -b do ${q}`;
    case "html":
    case "htm":
      return `__SERVE_HTML__`;
    case "vue":
    case "svelte":
    case "astro":
      return `__SERVE_FRONTEND__`;
    case "css":
    case "scss":
    case "less":
      return `__SERVE_HTML__`;
    case "json":
      return `${_isWin ? "py -3" : "python3"} -m json.tool ${q}`;
    case "yaml":
    case "yml":
      // Windows 上两处都不成立：没有 `python3` 这个命令（python.org 的包只产出
      // python.exe，同名的 python3.exe 是微软商店的应用执行别名，跑它会弹商店），
      // 而 `<<'PY'` 这种 heredoc 在 cmd.exe 里也不是语法。同一行 JSON 那条早就
      // 按平台分过了（`py -3`），yaml 这条漏了。
      if (_isWin) {
        // 用 -c 单行，绕开 heredoc；路径里的反斜杠和单引号都先转义好再塞进 Python 字面量。
        const _pyPath = String(path).replace(/\\/g, "\\\\").replace(/'/g, "\\'");
        return `py -3 -c "import pathlib,yaml;print(yaml.safe_load(pathlib.Path('${_pyPath}').read_text()))"`;
      }
      return `python3 - <<'PY'\nimport pathlib, sys, yaml\nprint(yaml.safe_load(pathlib.Path(${JSON.stringify(path)}).read_text()))\nPY`;
    case "sql":
      return `sqlite3 < ${q}`;
    case "dockerfile":
      return `docker build -f ${q} ${dir}`;
    case "makefile":
      return `cd ${dir} && make -f ${shellQuote(name)}`;
    default:
      if (name === "Dockerfile") return `docker build -f ${q} ${dir}`;
      if (/^Makefile(?:\..*)?$/.test(name)) return `cd ${dir} && make -f ${shellQuote(name)}`;
      return null;
  }
}

async function _waitTermReady(maxWait = 3000) {
  const start = Date.now();
  while (Date.now() - start < maxWait) {
    const tab = activeTermTab >= 0 ? termTabs[activeTermTab] : null;
    if (tab?.backendId != null && !tab.opening) return true;
    await new Promise((r) => setTimeout(r, 200));
  }
  return false;
}

let _devServerPort = null;
let _devServerRunning = false;

async function _findFreePort(start = 3000) {
  for (let p = start; p < start + 100; p++) {
    try {
      const resp = await fetch(`http://127.0.0.1:${p}`, { signal: AbortSignal.timeout(200) });
      continue;
    } catch {
      return p;
    }
  }
  return start;
}

async function _startDevServer(dir, port, fileName = "") {
  const wasOpen = termIsOpen();
  await openTerminal();
  if (!wasOpen) {
    await _waitTermReady(3000);
    await new Promise((r) => setTimeout(r, 1800));
  }

  const scriptContent = [
    "import http.server, socketserver, os, socket, threading, time",
    `os.chdir(r'${dir}')`,
    `PORT = ${port}`,
    "file_hashes = {}",
    "def scan():",
    "    h = {}",
    "    for root, _, files in os.walk('.'):",
    "        for f in files:",
    "            if f.endswith(('.html', '.css', '.js', '.json')):",
    "                p = os.path.join(root, f)",
    "                try: h[p] = os.path.getmtime(p)",
    "                except: pass",
    "    return h",
    "file_hashes.update(scan())",
    "last_change = [time.time()]",
    "def watcher():",
    "    while True:",
    "        time.sleep(0.8)",
    "        cur = scan()",
    "        if cur != file_hashes:",
    "            file_hashes.clear()",
    "            file_hashes.update(cur)",
    "            last_change[0] = time.time()",
    "threading.Thread(target=watcher, daemon=True).start()",
    // 只管热重载。**调试桥不在这里了**——它由 src-tauri 的 preview-bridge 插件
    // 注入到应用的每一个帧（WKUserScript forMainFrameOnly:false），所以任何本地
    // dev server 起的页面都自带，不再只有这一个服务的预览才有。
    `RELOAD_JS = b'<script>(function(){var t=0;setInterval(function(){fetch("/__reload__").then(function(r){return r.text()}).then(function(s){var n=parseFloat(s);if(t&&n>t)location.reload();t=n})},800)})()</script>'`,
    "class RH(http.server.SimpleHTTPRequestHandler):",
    "    def do_GET(self):",
    "        if self.path == '/__reload__':",
    "            self.send_response(200)",
    "            self.send_header('Content-Type', 'text/plain')",
    "            self.send_header('Access-Control-Allow-Origin', '*')",
    "            self.end_headers()",
    "            self.wfile.write(str(last_change[0]).encode())",
    "            return",
    "        path = self.translate_path(self.path)",
    // 目录要先解析成它的 index.html，再判断要不要注入。
    // translate_path('/') 返回的是**目录**，.endswith('.html') 不成立，于是整个注入
    // 分支被跳过、直接落到父类去发原文——而 `/` 恰恰是 IDE 自己打开的那个地址。
    // 症状是热重载和调试桥对根路径**从来没生效过**，显式敲 /index.html 才有。
    // 这种形状不会有人报 bug，只会觉得「改了代码有时候不刷新」。
    "        if os.path.isdir(path):",
    "            for _idx in ('index.html', 'index.htm'):",
    "                _cand = os.path.join(path, _idx)",
    "                if os.path.isfile(_cand):",
    "                    path = _cand",
    "                    break",
    "        if os.path.isfile(path) and (path.endswith('.html') or path.endswith('.htm')):",
    "            with open(path, 'rb') as f: data = f.read()",
    "            data = data.replace(b'</body>', RELOAD_JS + b'</body>')",
    "            self.send_response(200)",
    "            self.send_header('Content-Type', 'text/html')",
    "            self.send_header('Content-Length', str(len(data)))",
    "            self.end_headers()",
    "            self.wfile.write(data)",
    "            return",
    "        super().do_GET()",
    "    def log_message(self, fmt, *args):",
    "        print(f'  {args[1]} {args[0]}')",
    "try: ip = socket.gethostbyname(socket.gethostname())",
    "except: ip = '127.0.0.1'",
    "s = socketserver.TCPServer(('', PORT), RH)",
    `FILE = '${fileName}'`,
    `path_suffix = '/' + FILE if FILE else ''`,
    `print('\\n  \\033[1;32m✦ Mr. Day One Dev Server\\033[0m\\n')`,
    `print(f'  ➜  Local:   \\033[36mhttp://localhost:{PORT}{path_suffix}\\033[0m')`,
    `print(f'  ➜  Network: \\033[36mhttp://{ip}:{PORT}{path_suffix}\\033[0m')`,
    `print(f'\\n  Serving:  {os.getcwd()}')`,
    `print('  Live Reload: \\033[32m✓ enabled\\033[0m')`,
    `print('  Press \\033[1mCtrl+C\\033[0m to stop\\n')`,
    "s.serve_forever()",
  ].join("\n");

  // `python3` 在 Windows 上不是命令——按 Run 起本地预览会当场报 command not found，
  // 而这是一个按钮，不是模型写的命令，用户没有任何线索。同文件里判 json 的那条
  // 早就写了 `py -3`，起服务这两条漏了。
  //
  // 声明在 try **之外**：catch 分支也要用它，写在 try 里的话回退那条路会直接
  // ReferenceError，而它恰恰是出错时才走的。
  const _py = _isWin ? "py -3" : "python3";
  try {
    const tmpPath = await backend.writeTmpFile("_michael_ide_dev_server.py", scriptContent);
    writeToActiveTerminal(`\n${_clearCmd()}\n${_py} ${shellQuote(tmpPath)}\n`);
  } catch {
    writeToActiveTerminal(`\n${_clearCmd()}\n${_py} -m http.server ${port} --directory ${shellQuote(dir)}\n`);
  }
  _devServerPort = port;
  _devServerRunning = true;
}

async function _startViteServer(dir) {
  const wasOpen = termIsOpen();
  await openTerminal();
  if (!wasOpen) {
    await _waitTermReady(3000);
    await new Promise((r) => setTimeout(r, 1800));
  }

  const q = shellQuote(dir);
  const hasVite = await new Promise((resolve) => {
    try {
      const fs = window.__TAURI_INTERNALS__ ? true : false;
      resolve(true);
    } catch { resolve(false); }
  });

  writeToActiveTerminal(`\n${_clearCmd()}\ncd ${q} && npx --yes vite --open\n`);
  showToast("启动 Vite Dev Server...");
}

async function runCurrentFile() {
  if (!activePath) {
    showToast("请先打开一个文件");
    return;
  }
  const runningPath = activePath;
  const command = runCommandForFile(runningPath);
  if (!command) {
    showToast(`不支持运行 ${basename(runningPath)} 类型的文件`);
    return;
  }
  const file = openFiles.get(runningPath);
  if (file?.dirty) {
    const saved = await saveActive(runningPath);
    if (!saved || openFiles.get(runningPath)?.dirty) {
      showToast("当前内容尚未安全写入磁盘，已取消运行");
      return;
    }
  }

  if (command === "__SERVE_HTML__") {
    const dir = dirname(runningPath);
    const port = await _findFreePort(3000);
    const name = basename(runningPath);
    await _startDevServer(dir, port, name);
    return;
  }

  if (command === "__SERVE_FRONTEND__") {
    const dir = dirname(runningPath);
    await _startViteServer(dir);
    return;
  }

  const wasOpen = termIsOpen();
  await openTerminal();

  if (!wasOpen) {
    await _waitTermReady(3000);
    await new Promise((r) => setTimeout(r, 1800));
  }

  writeToActiveTerminal(`\n${_clearCmd()}\n${command}\n`);
}

async function runTask(task) {
  if (!task?.command) return;
  await openTerminal();
  const cwd = task.cwd || rootPath;
  const prefix = cwd ? `cd ${shellQuote(cwd)} && ` : "";
  writeToActiveTerminal(`\n${prefix}${task.command}\n`);
  showToast(`正在运行任务：${task.label}`);
}

// Owner used for markers produced by task/problem-matcher runs, so they can be
// cleared independently of LSP and extension diagnostics.
const TASK_MARKER_OWNER = "task";
const MAX_PROBLEM_FILES = 80;

function clearTaskProblems() {
  for (const model of monaco.editor.getModels()) {
    monaco.editor.setModelMarkers(model, TASK_MARKER_OWNER, []);
  }
}

function resolveTaskPath(file, cwd) {
  if (!file) return null;
  let f = file.trim().replace(/^\.[\\/]/, "");
  if (f.startsWith("/") || /^[A-Za-z]:[\\/]/.test(f)) return f;
  const base = (cwd || rootPath || "").replace(/[\\/]+$/, "");
  return base ? `${base}/${f}` : f;
}

function taskSeverityToMarker(sev) {
  return sev === "error" ? monaco.MarkerSeverity.Error
    : sev === "warning" ? monaco.MarkerSeverity.Warning
    : sev === "info" ? monaco.MarkerSeverity.Info
    : monaco.MarkerSeverity.Hint;
}

async function ensureModelForPath(absPath) {
  const uri = monaco.Uri.file(absPath);
  const existing = monaco.editor.getModel(uri);
  if (existing) return existing;
  try {
    const content = await backend.readTextFile(absPath);
    return getOrCreateModel(absPath, basename(absPath), content);
  } catch {
    return null;
  }
}

// ── Interleaved verification (P2): worker diagnostics for just-edited JS/TS ──
// Languages whose diagnostics Monaco's BUNDLED worker computes with no external
// LSP. JS/JSX get syntax-only (checkJs:false → rock-solid signal); TS/TSX get
// syntax+semantic.
// 会产出真实诊断的扩展名。
//
// 这张表原来只有 JS/TS 八个，而它同时是**三道卡口**的判据（建 baseline、进检查集、
// _interleavedDiagnostics 内部过滤）。后果：模型改坏 .py / .rs / .go 引入语法或类型
// 错误，`[BLOCKING_NEW_DIAGNOSTICS]` **永不触发**，收尾门直接放行。
//
// 而能力一直是有的——lsp-client.js 管着 23 种语言的真 LSP 诊断。断的只是"拿不拿它
// 当收尾门的依据"。所以这里补上那 23 种语言的常见扩展名；判断某个文件到底有没有
// 语言服务，交给 _lintableLangId() 按 extLang() 的真实结果决定，而不是在这里猜。
const _LINTABLE_EXT = new Set([
  "js", "jsx", "mjs", "cjs", "ts", "tsx", "mts", "cts",
  // 以下靠 lsp-client 的 MANAGED_LANGS 提供诊断（装了对应语言服务器才有）
  "rs", "py", "pyi", "go", "c", "h", "cc", "cpp", "cxx", "hpp", "hh", "m", "mm",
  "java", "rb", "php", "lua", "sh", "bash", "zsh", "yaml", "yml",
  "cs", "kt", "kts", "swift", "dart", "ex", "exs", "clj", "cljs", "scala", "sc",
  "tf", "tfvars", "graphql", "gql", "vue",
]);

/// 这个文件该用哪个 Monaco language id 建 model。
///
/// 原来写死 `isTs ? "typescript" : "javascript"`——于是就算把 .py 放进检查集，
/// 建出来的也是个 JavaScript model，Monaco 的 TS worker 对它报一堆无意义的错，
/// 而真正的 Python 诊断（走 lsp-client）永远不会附到这个 model 上。
function _lintableLangId(rel) {
  const id = extLang(String(rel).split("/").pop());
  return id && id !== "plaintext" ? id : null;
}
const _TS_EXT = new Set(["ts", "tsx", "mts", "cts"]);
/*
 * 项目自己那份 linter，跑在每批改动之后。
 *
 * 隔壁 `_interleavedDiagnostics` 认的是**语法和类型**（Monaco worker + LSP）。而用户真正
 * 吃亏的一类 bug 在语法上全对、类型也全过：漏 await 的 promise、该用 === 用了 ==、
 * React hook 依赖不全、catch 了又吞掉、未使用变量背后藏着拼错的名字。这些只有项目自己
 * 配的 linter 认得 —— 而那份配置就躺在仓库里没人读。纯 JS 项目最极端：没有类型检查，
 * 那条腿只剩语法，等于唯一的写时正确性门几乎是空的。
 *
 * 三条纪律写在 src/agent/project-lint.js 的文件头：只按项目自己的配置认、只报 error、
 * 「没跑成」和「跑了没问题」必须可分。这里只负责**执行**和接进那道已有的阻断门。
 *
 * 有界：`project_lint_run` 在 Rust 侧 8 秒硬超时、程序名走白名单、不经过 shell。
 */
/**
 * 一次写入之后要做的两件事：给模型的质量提醒，以及**按写出来的代码**点亮安全旗标。
 *
 * 收成一个函数是因为它有两个调用点（普通工具执行、有序分段执行），而"手工保持两处
 * 同步"在这个仓库栽过好几次 —— 漏掉一处不会报错，只会让那条路上这道机制不存在。
 *
 * 安全旗标此前只来自**意图裁决**，也就是模型对「用户这句话」的判断：用户说
 * 「做个待办列表」，`securityRisk` 不亮；模型接着写了一段拼 SQL 的查询、一个上传
 * handler —— 网关那份缺陷分类清单一个字都不发。判据得跟着写出来的代码走。
 *
 * 画像是会话粘性的单调并集，所以点亮一次就够，之后每一轮都带着；代价是本轮之后的
 * 第一次请求会作废一次前缀缓存 —— 一次性的，换的是"真写了危险代码时清单在场"。
 */
function _afterWriteAdvice(run, call, root) {
  const advice = String(_debugMutationBlockResult(run, call, root) || "") + _sinkRiskAdvice(call);
  try {
    const kinds = _securitySinkKinds(call);
    if (kinds.length) {
      const sess = run?.session || (typeof _currentSession === "function" ? _currentSession() : null);
      const flags = sess && (Array.isArray(sess._semanticProfileFlags) ? sess._semanticProfileFlags : (sess._semanticProfileFlags = []));
      if (flags && !flags.includes("defects_write")) {
        flags.push("defects_write");
        // 记成执行事实，供本轮的质量事实通道说一句：模型自己往哪个面上写了东西。
        (run._writeFactsPending = run._writeFactsPending || []).push(
          `这一轮写进去的代码碰到了${kinds.join("、")} —— 已经把对应的缺陷分类清单挂上，后面几轮按它自查`);
      }
    }
  } catch {}
  return advice;
}

const _LINT_MAX_FILES = 12;

/** 这个仓库配了哪些 linter。按根缓存 —— 配置文件不会在一个 run 里变。 */
const _lintersByRoot = new Map();
async function _projectLinters(root) {
  const key = String(root || "");
  if (!key || !inTauri) return [];
  if (_lintersByRoot.has(key)) return _lintersByRoot.get(key);
  let found = [];
  try {
    const entries = await backend.readDir(key);
    const names = new Set((entries || []).map((e) => String(e?.name || "")).filter(Boolean));
    let manifest = null;
    if (names.has("package.json")) {
      try { manifest = JSON.parse(await backend.readTextFile(`${key}/package.json`)); } catch {}
    }
    // pyproject 的 [tool.ruff] 不写 TOML 解析器，一行正则够了：这个判据只回答
    // 「这个仓库配没配 ruff」，配错了最坏是白跑一次 8 秒上限的进程。
    if (names.has("pyproject.toml")) {
      try {
        const py = await backend.readTextFile(`${key}/pyproject.toml`);
        if (/^\s*\[tool\.ruff[\].]/m.test(String(py || ""))) {
          manifest = { ...(manifest || {}), pyprojectHasRuff: true };
        }
      } catch {}
    }
    found = _detectLinter(names, manifest);
  } catch {}
  _lintersByRoot.set(key, found);
  return found;
}

/**
 * 跑一遍项目 linter，返回**这次改动新引入的** error。
 *
 * `baseline` 是同一批文件在改动前跑出来的那份（调用方在首次触碰这些文件时抓）。
 * 传 null 表示「这次跑的就是 baseline」。
 *
 * 返回 `{ ran, findings, unavailable }`：`ran:false` 说明这个仓库没配 linter 或者
 * 根本没跑成 —— 那和「跑了、干干净净」是两回事，调用方必须能分开（混为一谈的话，
 * 一个没装 eslint 的项目会得到「零错误」，而那恰恰最该说一句）。
 */
async function _projectLintFindings(editedRelPaths, root, baseline = null) {
  const files = (Array.isArray(editedRelPaths) ? editedRelPaths : []).slice(-_LINT_MAX_FILES);
  if (!files.length || !root || !inTauri) return { ran: false, findings: [], unavailable: [] };
  const linters = await _projectLinters(root);
  if (!linters.length) return { ran: false, findings: [], unavailable: [] };
  const all = [];
  const unavailable = [];
  let ranAny = false;
  for (const linter of linters) {
    const cmd = _lintCommand(linter, files);
    if (!cmd) continue;   // 这一批里没有它管得着的文件
    let out;
    try {
      out = await _invokeCapped("project_lint_run",
        { program: cmd.program, args: cmd.args, cwd: root }, 12_000, `${linter.id} 检查`);
    } catch { out = null; }
    // 没跑成就如实记下来，绝不当成「零问题」。
    //
    // 两层判据缺一不可：Rust 那边的 note 只覆盖「没启动/超时」，而
    // `npx --no-install eslint` 在项目没装 eslint 时会**正常启动、非零退出、stdout 空**
    // —— 进程跑起来了，所以没有 note；解析器拿到空串返回空数组，于是「这个项目没装
    // lint」被读成「零错误、干干净净」。`_lintRan` 就是为这一层存在的。
    if (!out || (out.note && String(out.note).trim())) {
      unavailable.push({ id: linter.id, why: String(out?.note || "调用失败").slice(0, 120) });
      continue;
    }
    if (!_lintRan(linter.id, out)) {
      unavailable.push({
        id: linter.id,
        why: String(out.stderr || out.stdout || `退出码 ${out.code}`).replace(/\s+/g, " ").trim().slice(0, 120),
      });
      continue;
    }
    ranAny = true;
    // 诊断可能在 stdout 也可能在 stderr（go vet 只写 stderr）。
    for (const f of _lintFindings(linter.id, out)) all.push({ ...f, linter: linter.id });
  }
  if (!ranAny) return { ran: false, findings: [], unavailable };
  return { ran: true, findings: baseline ? _newLintFindings(baseline, all) : all, unavailable };
}

const _INTERLEAVED_DIAG_MAX_FILES = 16;
const _INTERLEAVED_DIAG_MAX_WAIT_MS = 4000;
// TS/JS 由 Monaco 自带 worker 出诊断，几百毫秒的事——给它一个短得多的期限，
// 免得整批等待被「反正总闸是 4 秒」拖满。
const _INTERLEAVED_DIAG_TS_WAIT_MS = 1200;
// After the agent changes JS/TS files, ask Monaco's built-in worker whether the
// edits introduced ERRORS — surfaced immediately for self-correction. Side-effect
// free: open models are read-only (never setValue → never falsely marked dirty);
// unopened files use a transient model (no listeners) that is disposed after the
// read. `baselineCounts` is captured before the first mutation of each file, so
// pre-existing project errors do not get blamed on the current Agent run.
/**
 * @param triedLangs run 级的「这门语言这一轮已经试过拉起服务器了」集合。
 *   不传就退化成原来的行为（只用已经在跑的服务器）。
 */
async function _interleavedDiagnostics(editedRelPaths, root = "", baselineCounts = null, triedLangs = null) {
  if (!editedRelPaths.length || typeof monaco === "undefined") return { ran: false, report: "", counts: new Map(), newErrorCount: 0, unchecked: [] };
  const targets = []; // { rel, model, created, isTs }
  // 「查过了，是干净的」和「这门语言根本没有检查器」是两个状态，此前在返回值里同形：
  // 没装语言服务器时 didOpen 是 no-op，等满超时读到 0 个 marker，newErrorCount = 0，
  // 与真干净字节级不可区分——非 JS/TS 项目里这道唯一的写时正确性门结构性哑掉，还每轮
  // 白等 _INTERLEAVED_DIAG_MAX_WAIT_MS。判据是现成的一个布尔查询：lspManager.isRunning。
  // 服务器没在跑的文件不建 model、不进等待循环，改记进 unchecked 让调用方当事实说出去。
  const unchecked = []; // [{ rel, lang }] —— 没有任何检查器看过的目标文件
  // **取最近改的那批，不是最早的。**
  //
  // 调用方传进来的是 run 级**只增不减**的集合（run._diagnosticCheckPaths）。
  // 从头截断的话，第 17 个之后被改的文件在这个 run 里**永远拿不到诊断**，
  // 而最早改的那 16 个每一轮重查一遍（还要为它们白等）。
  // 铺 30 个文件的任务里，后半截写坏什么都不响，收尾门看到 newErrorCount=0 直接放行。
  // 任务越大越静默 —— 这正是「大项目就开始乱」的形状。
  for (const rel of editedRelPaths.slice(-_INTERLEAVED_DIAG_MAX_FILES)) {
    const ext = (rel.split(".").pop() || "").toLowerCase();
    if (!_LINTABLE_EXT.has(ext)) continue;
    let abs = rel;
    try { abs = await _resolveExisting(rel, root); } catch {}
    const isTs = _TS_EXT.has(ext);
    const _jsFamily = isTs || ext === "js" || ext === "jsx" || ext === "mjs" || ext === "cjs";
    const langId = _lintableLangId(rel) || (isTs ? "typescript" : "javascript");
    if (!_jsFamily && !(lspManager?.isRunning?.(langId))) {
      /*
       * **先自己把语言服务器拉起来再说「没检查器」。**
       *
       * 这里原来直接 `continue` —— 而语言服务器只有用户**手动在编辑器里打开**同语言文件
       * 才会起。于是一个 Python / Rust / Go 项目里，只要这次会话用户没手动开过 .py，
       * 智能体改多少个 .py 都只会被记成 unchecked，`[BLOCKING_NEW_DIAGNOSTICS]` 那道门
       * 结构上永不触发 —— 全系统唯一一道「改完自动检查」的门，在非 JS/TS 项目上是关着的。
       * 而且它关着的时候还很诚实地告诉模型「这些文件没有任何检查器看过」。
       *
       * `ensureServer` 的契约正好够用：可 await，缺二进制/启动失败时干净返回 null 并把
       * 自己从 clients 里删掉。所以退化路径就是现在的 unchecked，零风险。
       * 有界：每 run 每语言只试一次（冷启动要花时间，不能每批改动都试一遍）。
       */
      const _canTry = triedLangs && !triedLangs.has(langId) && lspManager?.ensureServer;
      if (_canTry) {
        triedLangs.add(langId);
        try { await lspManager.ensureServer(langId); } catch {}
      }
      if (!(lspManager?.isRunning?.(langId))) {
        unchecked.push({ rel: _normRel(abs, root), lang: langId });
        continue;
      }
    }
    let uri; try { uri = monaco.Uri.file(abs); } catch { continue; }
    let model = monaco.editor.getModel(uri);
    let created = false;
    if (!model) {
      let content = "";
      try { content = await backend.readTextFile(abs); } catch { continue; }
      try { model = monaco.editor.createModel(content, langId, uri); created = true; } catch { continue; }
      // 光建 Monaco model 不够：TS/JS 由 Monaco 自带 worker 分析，**其余语言的诊断来自
      // 语言服务器**，而服务器只会分析它被 didOpen 告知过的文档。模型刚写完、从没被打开
      // 过的 .py/.rs/.go，服务器根本不知道它存在，于是这里等多久都读不到 marker——
      // 扩展名补齐了、语言 id 也对了，门却仍然恒放行。
      try { lspManager?.didOpen(abs, model); } catch {}
    }
    // 带上 _jsFamily 而不是只带 isTs：期限那一行要区分的是「诊断从哪来」——
    // Monaco 自带 worker（TS **和 JS**）还是真 LSP，而不是「是不是 TypeScript」。
    // 只带 isTs 的话 js/jsx/mjs/cjs 会落进 LSP 那条 4 秒的腿，而它们的诊断根本不来自 LSP。
    targets.push({ rel: _normRel(abs, root), model, created, isTs, jsFamily: _jsFamily });
  }
  if (!targets.length) return { ran: false, report: "", counts: new Map(), newErrorCount: 0, unchecked };
  // 诊断是异步来的，而且两条来源的延迟差一个数量级：Monaco 自带的 TS worker 通常几百
  // 毫秒，真 LSP（rust-analyzer / pyright / gopls）冷启动要好几秒。原来固定等 900ms，
  // 对 LSP 语言等于"还没出结果就读，读到空的，判成无新增错误"——门看着在跑，实际恒放行。
  // 改成轮询：任一目标出现 marker 就收，最多等 _INTERLEAVED_DIAG_MAX_WAIT_MS。
  {
    /*
     * 退出条件必须是「**每个**目标各自有结果或各自超时」，不是「任一出结果」。
     *
     * 原来写的是 any：一批里同时改了 src/app.ts 和 src/engine.rs，Monaco 自带的 TS
     * worker 约 300ms 就为 app.ts 推出一条 marker → 循环立刻退出 → 此时 rust-analyzer
     * 一条都还没到（它刚被 didOpen 告知这个文件，冷启动几秒起步）→ engine.rs 的
     * markers 为空 → 新增错误数不含它 → 这道门放行，**engine.rs 里新引入的编译错误
     * 一句提示都没有**，智能体照常收尾报「已完成」。而且它也进不了 unchecked 名单
     * （它满足 isRunning，走的是「查过了、是干净的」那条腿），连「没检查」的诚实
     * 兜底都拿不到。
     *
     * 每个目标有自己的期限：TS/JS 走 Monaco 自带 worker，几百毫秒的事，等久了是白等；
     * 其余语言按 LSP 冷启动给足。整体仍有一个总闸，避免被最慢的那个拖满。
     */
    const started = Date.now();
    const hardDeadline = started + _INTERLEAVED_DIAG_MAX_WAIT_MS;
    /*
     * **JS/TS 走「问它答完没有」，不是「等满就算」。**
     *
     * 下面那个轮询的退出条件是 `有 marker || 到点`。而一个**干净**的 JS/TS 文件
     * 永远不会产生 marker —— 于是它必然等满 _INTERLEAVED_DIAG_TS_WAIT_MS，
     * 每个包含编辑的回合固定白付这一段。改十次文件的任务就是十几秒纯等待。
     *
     * Monaco 自带的 TS worker 有一个真正的完成信号：`getSemanticDiagnostics` 是个
     * Promise，分析完就 resolve，干净文件 resolve 成空数组。拿它当判据，
     * 干净文件几百毫秒就能收工，而不是等满。
     *
     * worker 答完 ≠ marker 已经挂上去（Monaco 还要把结果 publish 成 marker），
     * 所以这里不直接判 settled，而是把这个目标的期限缩短到「再等一小段」——
     * 底下那套读 marker 的逻辑一个字不用改。
     *
     * 拿不到 worker（Monaco 版本差异、被裁剪的构建）就什么都不做，退回原来的等满。
     */
    const _TS_PUBLISH_GRACE_MS = 200;
    for (const t of targets) {
      if (!t.jsFamily) continue;
      (async () => {
        try {
          const _ts = monaco.languages?.typescript;
          const _get = t.isTs ? _ts?.getTypeScriptWorker : _ts?.getJavaScriptWorker;
          if (typeof _get !== "function") return;
          const _client = await _get();
          const _worker = await _client(t.model.uri);
          const _u = t.model.uri.toString();
          await Promise.all([
            Promise.resolve(_worker.getSyntacticDiagnostics?.(_u)).catch(() => null),
            Promise.resolve(_worker.getSemanticDiagnostics?.(_u)).catch(() => null),
          ]);
          t._workerDoneAt = Date.now();
        } catch {}
      })();
    }
    // 判 jsFamily 不判 isTs。上面那句注释（"TS/JS 由 Monaco 自带 worker 出诊断"）
    // 从一开始就把 JS 算在内，只是 targets 里当时没带这个字段，于是每一个干净的
    // .js/.jsx/.mjs/.cjs 都在这里等满 4 秒——而且是**必然**等满：tsconfig 那边
    // checkJs:false，.js 只出语法诊断，语法没错就是 0 个 marker，has 恒为假，
    // 唯一的出路就是 own(t) 到点。一次改动批里每个 .js 文件白等 2.8 秒。
    const own = (t) => started + (t.jsFamily ? _INTERLEAVED_DIAG_TS_WAIT_MS : _INTERLEAVED_DIAG_MAX_WAIT_MS);
    for (;;) {
      await new Promise((r) => setTimeout(r, 150));
      const now = Date.now();
      let settled = true;
      for (const t of targets) {
        if (t._diagSettled) continue;
        let has = false;
        try { has = monaco.editor.getModelMarkers({ resource: t.model.uri }).length > 0; } catch {}
        // worker 答完之后再给一小段让 marker 挂上去，就不必等满整个期限了。
        const _workerReady = t._workerDoneAt != null && now >= t._workerDoneAt + _TS_PUBLISH_GRACE_MS;
        if (has || _workerReady || now >= own(t)) t._diagSettled = true;
        else settled = false;
      }
      if (settled || now >= hardDeadline) break;
    }
  }
  const reports = [];
  const counts = new Map();
  let newErrorCount = 0;
  for (const t of targets) {
    let markers = [];
    try { markers = monaco.editor.getModelMarkers({ resource: t.model.uri }); } catch {}
    const errs = markers.filter((m) => m.severity === 8);
    const fresh = [];
    for (const marker of errs) {
      const code = marker.code == null ? "" : (typeof marker.code === "object" ? marker.code.value : marker.code);
      const identity = `${t.rel}|${code}|${String(marker.message || "").trim()}`;
      const occurrence = (counts.get(identity) || 0) + 1;
      counts.set(identity, occurrence);
      if (!baselineCounts || occurrence > (baselineCounts.get(identity) || 0)) fresh.push(marker);
    }
    if (fresh.length) {
      newErrorCount += fresh.length;
      const formatted = formatDiagnosticsForAgent(fresh, root, { activePath: t.model?.uri?.fsPath || t.model?.uri?.path || "", max: 12 });
      reports.push(`【${t.rel}】(${fresh.length} 个新增错误)\n${formatted}`);
    }
  }
  // Dispose only the models WE created — never touch ones the user has open.
  // 我们建的 model 用完要还回去：先告诉服务器关掉（否则每轮检查都往服务器里塞一份
  // 永不关闭的文档，内存和诊断都会越积越脏），再 dispose。用户自己开着的绝不碰。
  for (const t of targets) {
    if (!t.created) continue;
    try { lspManager?.didClose(t.model?.uri?.fsPath || t.model?.uri?.path || ""); } catch {}
    try { t.model.dispose(); } catch {}
  }
  return { ran: true, report: reports.join("\n\n"), counts, newErrorCount, unchecked };
}

// Run the project's test command (auto-detected) and return a compact failure
// report. Bounded to 60s and called from the finish gate, so a run does not spend
// its time repeating the same command after each small edit batch.
async function _interleavedTest(root, testCmd) {
  if (!root || !testCmd || !inTauri) return { ran: false, ok: false, code: null, timedOut: false, report: "", verification: true };
  try {
    // The timeout is enforced by Rust, which owns and kills the complete process
    // group. A JS Promise.race returned early while cargo/npm kept running for up
    // to five minutes, allowing overlapping verification processes to accumulate.
    const r = await backend.taskRunCapture(root, testCmd, { timeoutSecs: 60 });
    const out = ((r?.stdout || "") + "\n" + (r?.stderr || "")).trim();
    const code = Number.isFinite(Number(r?.code)) ? Number(r.code) : -1;
    const timedOut = !!(r?.timedOut ?? r?.timed_out) || code === -1;
    const failed = timedOut || code !== 0;
    if (!failed) return { ran: true, ok: true, code, timedOut: false, report: "", verification: true };
    // 退出码 126/127 = **验证器本身不存在或不可执行**（command not found / not
    // executable），它对用户代码没有任何断言。把它当"验证失败"是假阴性：报告会说
    // 「验证失败: ruff check . && pytest 退出 127」，看起来像代码有问题，而实际只是
    // 这台机器没装 ruff/pytest。更糟的是收尾门禁据此判定"未验证"，于是本来能继续修的
    // 一轮被直接结束。改为 ran:false —— 与"这个项目识别不出验证命令"同一语义。
    if (code === 127 || code === 126) {
      return {
        ran: false,
        ok: false,
        code,
        timedOut: false,
        unavailable: true,
        verification: true,
        report: `验证器不可用：\`${testCmd}\` 退出 ${code}（命令不存在或不可执行）。这不代表代码有问题；装上工具或改用本项目实际可运行的命令再验。`,
      };
    }
    // 超时 ≠ 失败：健康但慢的套件（cargo test/大型 jest）轻松超 60s，旧版把它当
    // “验证失败”→对好代码发起修复→收尾谎报失败（假阴性蠢逻辑）。与 126/127 同义：
    // ran:false = 没得出断言，不触发修复，建议换后台长命令道。
    if (timedOut) {
      return {
        ran: false,
        ok: false,
        code,
        timedOut: true,
        verification: true,
        report: `验证未完成：\`${testCmd}\` 超过 60s 预算被中止——这不代表失败，只是套件比预算慢。长套件用 run_in_terminal 后台跑完整验证并 read_terminal 看结果，或只跑聚焦子集（如 npm test -- <目标>）。`,
      };
    }
    // Truncate to first ~40 lines so we don't blow context with a 5000-line test log.
    const lines = out.split("\n");
    let detail;
    if (lines.length <= 16) {
      // Short output: show it once, whole — head/tail slices of a short log just
      // repeat the same error lines twice.
      detail = out;
    } else {
      const head = lines.slice(0, 6).join("\n");
      // 多条失败要一起给。只给第一条会让模型改完一处就以为修完了，下一轮再撞第二条——
      // 套件红几条就要几轮。上限 3 段 × 16 行：再多会把 report 的 4000 字预算吃光，
      // 反而看不见 tail（收尾统计行常常在那儿）。
      const FAIL_RE = /FAIL|FAILED|✗|✘|✖|×|Test (suite )?failed|expected/i;
      const blocks = [];
      let cursor = 0;
      while (blocks.length < 3 && cursor < lines.length) {
        const idx = lines.findIndex((l, i) => i >= cursor && FAIL_RE.test(l));
        if (idx < 0) break;
        // 关键词落在 head 切片里时从第 6 行起，诊断正文照样露出来且不和 head 重复。
        const start = Math.max(idx, 6);
        if (start >= lines.length) break;
        const end = Math.min(start + 16, lines.length);
        blocks.push(lines.slice(start, end).join("\n"));
        cursor = Math.max(end, idx + 1);
      }
      const more = blocks.length >= 3 && lines.slice(cursor).some((l) => FAIL_RE.test(l));
      const tail = lines.slice(-10).join("\n");
      detail = `${head}${blocks.length ? "\n…\n" + blocks.join("\n…\n") : ""}`
        + (more ? `\n…\n（还有更多失败没列出——本地重跑 \`${testCmd}\` 看完整输出）` : "")
        + `\n…\n${tail}`;
    }
    const report = `${timedOut ? "验证超时" : "验证失败"}：\`${testCmd}\` 退出 ${code}：\n${detail}`;
    return { ran: true, ok: false, code, timedOut, report: report.slice(0, 4000), verification: true };
  } catch (e) {
    return { ran: true, ok: false, code: null, timedOut: false, report: `验证运行异常: ${e?.message || e}`, verification: true };
  }
}

// Automatic check/test/build commands run directly. They are evidence collection,
// not a separate approval flow.
async function _runApprovedVerification(root, command, run) {
  const call = { type: "cmd", command: String(command || "") };
  const result = await _interleavedTest(root, call.command);
  // stderr, not just report: the red-build fix loop reads e.stderr. Returning the compiler
  // output only under `report` meant every IDE-run failure reached the model as an empty
  // error body — "the build failed, here are the errors:" followed by nothing. The green
  // path is unchanged (report is "" on success, so stderr stays "").
  return { ...result, stderr: result.stderr ?? result.report ?? "", verification: true };
}

// Run a task non-interactively, capture its output, parse it through the
// matching problem matcher, and surface the results in the Problems panel and
// as inline squiggles.
async function runTaskWithProblems(task) {
  if (!task?.command) return;
  const cwd = task.cwd || rootPath;
  if (!cwd) {
    showToast("请先打开一个工作区。");
    return;
  }
  clearTaskProblems();
  showToast(`正在分析：${task.label}…`);
  let result;
  try {
    result = await backend.taskRunCapture(cwd, task.command);
  } catch (e) {
    showToast(`任务启动失败：${String(e && e.message ? e.message : e)}`);
    return;
  }

  const problems = parseProblems(result.combined || `${result.stdout || ""}${result.stderr || ""}`, {
    matcher: task.problemMatcher,
    command: task.command,
  });

  // Group by resolved absolute path.
  const byPath = new Map();
  for (const p of problems) {
    const abs = resolveTaskPath(p.file, cwd);
    if (!abs) continue;
    if (!byPath.has(abs)) byPath.set(abs, []);
    byPath.get(abs).push(p);
  }

  let errs = 0;
  let warns = 0;
  let fileCount = 0;
  for (const [abs, items] of byPath.entries()) {
    if (fileCount >= MAX_PROBLEM_FILES) break;
    const model = await ensureModelForPath(abs);
    if (!model) continue;
    fileCount++;
    const markers = items.map((p) => {
      const line = Math.min(p.line, model.getLineCount());
      const maxCol = model.getLineMaxColumn(line);
      const startCol = Math.min(p.col, maxCol);
      const word = model.getWordAtPosition({ lineNumber: line, column: startCol });
      const endCol = word ? word.endColumn : maxCol;
      if (p.severity === "error") errs++;
      else if (p.severity === "warning") warns++;
      return {
        severity: taskSeverityToMarker(p.severity),
        message: p.code ? `${p.message} (${p.code})` : p.message,
        source: p.source || task.label,
        startLineNumber: line,
        startColumn: startCol,
        endLineNumber: line,
        endColumn: Math.max(endCol, startCol + 1),
      };
    });
    monaco.editor.setModelMarkers(model, TASK_MARKER_OWNER, markers);
  }

  if (problems.length) {
    if (problemsPanel && problemsPanel.hidden) toggleProblems();
    else updateProblems();
    showToast(`${task.label}：${errs} 个错误、${warns} 个警告，分布在 ${fileCount} 个文件中`);
  } else if (result.code === 0) {
    showToast(`${task.label}：完成，未发现问题`);
  } else {
    await openTerminal();
    showToast(`${task.label}：退出码 ${result.code}，无法解析出问题 — 已在终端中运行`);
    runTask(task);
  }
}

function renderTasksTool(body) {
  createToolHeader(body, "任务运行器", "自动发现 npm、Cargo、Makefile、.mrdayone/tasks.json 和 .vscode/tasks.json 里的任务。可在终端运行，或用「问题」面板捕获输出、把编译器/检查器的报错汇总到问题面板。");
  const actions = document.createElement("div");
  actions.className = "tool-actions";
  const refresh = document.createElement("button");
  refresh.className = "btn";
  refresh.type = "button";
  refresh.textContent = "刷新";
  const clearBtn = document.createElement("button");
  clearBtn.className = "btn";
  clearBtn.type = "button";
  clearBtn.textContent = "清除问题";
  clearBtn.addEventListener("click", () => {
    clearTaskProblems();
    updateProblems();
    showToast("已清除任务问题");
  });
  actions.append(refresh, clearBtn);
  const list = document.createElement("div");
  list.className = "tool-list";
  body.append(actions, list);

  const load = async () => {
    list.innerHTML = "";
    if (!rootPath) {
      list.appendChild(createEmptyState("运行任务前请先打开工作区。"));
      return;
    }
    list.appendChild(createEmptyState("正在加载任务…"));
    try {
      const tasks = await backend.tasksList(rootPath);
      list.innerHTML = "";
      if (!tasks.length) {
        list.appendChild(createEmptyState("未发现任务。可添加 package.json scripts、Cargo.toml、Makefile、.mrdayone/tasks.json 或 .vscode/tasks.json。"));
        return;
      }
      for (const task of tasks) {
        const card = document.createElement("div");
        card.className = "tool-card";
        card.innerHTML = `
          <div class="tool-card__main">
            <strong></strong>
            <span></span>
          </div>
          <div class="tool-card__actions">
            <button class="btn" type="button" data-act="problems">问题</button>
            <button class="btn btn--primary" type="button" data-act="run">运行</button>
          </div>`;
        card.querySelector("strong").textContent = task.label;
        card.querySelector("span").textContent = `${task.source} · ${task.group} · ${task.command}`;
        card.querySelector('[data-act="run"]').addEventListener("click", () => runTask(task));
        card.querySelector('[data-act="problems"]').addEventListener("click", () => runTaskWithProblems(task));
        list.appendChild(card);
      }
    } catch (e) {
      list.innerHTML = "";
      list.appendChild(createEmptyState(String(e && e.message ? e.message : e)));
    }
  };

  refresh.addEventListener("click", load);
  load();
}

function renderRemoteTool(body) {
  createToolHeader(body, "远程开发", "创建绑定当前工作区的 SSH 终端会话。需要在编辑器里打开远程文件时，用挂载或同步过来的路径作为文件夹根目录。");
  const form = document.createElement("div");
  form.className = "tool-form";
  form.innerHTML = `
    <label><span>SSH 目标</span><input id="remoteTarget" spellcheck="false" placeholder="user@example.com" /></label>
    <label><span>远程路径</span><input id="remotePath" spellcheck="false" placeholder="/home/user/project" /></label>
    <div class="tool-actions"><button class="btn btn--primary" type="button" id="remoteConnect">打开 SSH 终端</button></div>
    <p class="tool-note">要在编辑器里完整编辑远程文件，先把远程文件夹挂载到本地，再把这个挂载目录加入工作区。</p>`;
  body.appendChild(form);
  form.querySelector("#remoteConnect").addEventListener("click", async () => {
    const target = form.querySelector("#remoteTarget").value.trim();
    const remotePath = form.querySelector("#remotePath").value.trim();
    if (!target) {
      showToast("请先填写 SSH 目标。");
      return;
    }
    if (!/^[A-Za-z0-9_.@%:+-]+$/.test(target)) {
      showToast("SSH 目标包含不支持的字符。");
      return;
    }
    await openTerminal();
    const remoteCommand = remotePath ? ` 'cd ${remotePath.replace(/'/g, "'\\''")} && exec $SHELL -l'` : "";
    writeToActiveTerminal(`ssh -t ${target}${remoteCommand}\n`);
    showToast(`正在打开到 ${target} 的 SSH 会话`);
  });
}

function renderMarketplaceTool(body) {
  body.innerHTML = `<div class="empty"><p>点击「扩展」按钮或按 ${_escHtml(shortcutLabel("shift+mod+x"))} 打开扩展市场。</p></div>`;
}

