// Hoisted so buildMenubar can remove the PRIOR build's document-level listeners before re-adding —
// buildMenubar re-runs on every Auto-Save toggle, and these two would otherwise stack on `document`.
let _menubarDocClick = null, _menubarDocKey = null;
function buildMenubar() {
  const bar = $("menubar");
  if (!bar) return;
  bar.innerHTML = "";
  const buttons = [];
  const panels = [];
  let openIdx = -1;

  const closeMenu = () => {
    if (openIdx < 0) return;
    panels[openIdx].hidden = true;
    buttons[openIdx].classList.remove("is-open");
    buttons[openIdx].setAttribute("aria-expanded", "false");
    openIdx = -1;
  };
  const openMenu = (i) => {
    if (openIdx === i) return;
    closeMenu();
    panels[i].hidden = false;
    buttons[i].classList.add("is-open");
    buttons[i].setAttribute("aria-expanded", "true");
    openIdx = i;
  };

  const MENUS = getMenus();
  MENUS.forEach((menu, i) => {
    const wrap = document.createElement("div");
    wrap.className = "tb-menu";
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "tb-menu__btn";
    btn.textContent = menu.label;
    btn.setAttribute("aria-haspopup", "true");
    btn.setAttribute("aria-expanded", "false");
    const panel = document.createElement("div");
    panel.className = "menu menu--tb";
    panel.setAttribute("role", "menu");
    panel.hidden = true;
    for (const entry of menu.items) {
      if (entry.sep) {
        const sep = document.createElement("div");
        sep.className = "menu__sep";
        panel.appendChild(sep);
        continue;
      }
      const mi = document.createElement("div");
      mi.className = "menu__item";
      mi.setAttribute("role", "menuitem");
      mi.innerHTML =
        (entry.icon ? `<svg class="ic" aria-hidden="true"><use href="#${entry.icon}" /></svg>` : "") +
        `<span class="name"></span>` +
        (entry.hint ? `<span class="meta"></span>` : "");
      mi.querySelector(".name").textContent = entry.label;
      if (entry.hint) mi.querySelector(".meta").textContent = entry.hint;
      mi.addEventListener("click", () => {
        closeMenu();
        try {
          entry.action();
        } catch (e) {
          showToast(String(e));
        }
      });
      panel.appendChild(mi);
    }
    btn.addEventListener("click", (e) => {
      e.stopPropagation();
      if (openIdx === i) closeMenu();
      else openMenu(i);
    });
    btn.addEventListener("mouseenter", () => {
      if (openIdx >= 0) openMenu(i);
    });
    wrap.append(btn, panel);
    bar.appendChild(wrap);
    buttons.push(btn);
    panels.push(panel);
  });

  // Remove the previous build's handlers before re-adding, so repeated buildMenubar() calls
  // (every Auto-Save toggle) never leak stacked document listeners capturing stale menubar state.
  if (_menubarDocClick) document.removeEventListener("click", _menubarDocClick);
  if (_menubarDocKey) document.removeEventListener("keydown", _menubarDocKey);
  _menubarDocClick = (e) => { if (openIdx >= 0 && !bar.contains(e.target)) closeMenu(); };
  _menubarDocKey = (e) => { if (e.key === "Escape") closeMenu(); };
  document.addEventListener("click", _menubarDocClick);
  document.addEventListener("keydown", _menubarDocKey);
}

// ---- wiring ----
async function chooseFolder() {
  let picked = null, errored = false;
  const t0 = Date.now();
  try { picked = await backend.pickFolder(); }
  catch { errored = true; } // native dialog threw (unavailable on this desktop)
  if (picked) { await openFolder(picked); return; }
  // No folder chosen. Show the manual path entry ONLY when the native picker
  // didn't really work — it threw, or resolved suspiciously fast (<400ms) meaning
  // no dialog actually opened (e.g. Linux without xdg-desktop-portal, which made
  // the button look dead). A real user CANCEL takes longer than that, so cancelling
  // the macOS picker no longer pops a second modal.
  if (errored || Date.now() - t0 < 400) await _promptFolderPath();
}

// Manual "open folder" via typed/pasted path + recent list — the reliable
// fallback when the OS file picker is unavailable. `onPick` lets the same modal
// either OPEN a project (default, replaces the workspace) or ADD a folder to the
// current multi-root workspace; `title` labels it accordingly.
async function _promptFolderPath(opts) {
  const onPick = (opts && opts.onPick) || openFolder;
  const title = (opts && opts.title) || "打开文件夹";
  let home = "";
  try { home = (await backend.homeDir()) || ""; } catch {}
  home = home || rootPath || "";
  let recents = [];
  try { const store = await loadStore("session.json"); recents = (await store.get(RECENT_PROJECTS_KEY)) || []; } catch {}

  const overlay = document.createElement("div");
  overlay.style.cssText = "position:fixed;inset:0;background:rgba(0,0,0,.45);display:flex;align-items:center;justify-content:center;z-index:99999";
  const modal = document.createElement("div");
  modal.style.cssText = "width:min(560px,92vw);background:var(--panel,#1e1e22);border:1px solid var(--border,rgba(128,128,128,.35));border-radius:12px;box-shadow:0 20px 60px rgba(0,0,0,.5);overflow:hidden";
  modal.innerHTML =
    `<div style="display:flex;align-items:center;gap:8px;padding:12px 14px;border-bottom:1px solid var(--border,rgba(128,128,128,.25))">` +
      `<svg viewBox="0 0 16 16" width="15" height="15" fill="currentColor"><path d="M1.75 1A1.75 1.75 0 000 2.75v10.5C0 14.216.784 15 1.75 15h12.5A1.75 1.75 0 0016 13.25v-8.5A1.75 1.75 0 0014.25 3H7.5a.25.25 0 01-.2-.1l-.9-1.2C6.07 1.26 5.55 1 5 1H1.75z"/></svg>` +
      `<span style="font-size:14px;font-weight:600">${title}</span>` +
      `<button class="pf-close" type="button" style="margin-left:auto;background:none;border:none;color:inherit;cursor:pointer;font-size:16px;opacity:.6">✕</button>` +
    `</div>` +
    `<div style="padding:12px 14px">` +
      `<div style="font-size:12px;opacity:.65;margin-bottom:6px">输入或粘贴文件夹的完整路径：</div>` +
      `<input class="pf-input" type="text" spellcheck="false" placeholder="${_escAttr(home || "/path/to/project")}" style="width:100%;box-sizing:border-box;padding:9px 10px;font:13px/1.4 ui-monospace,Menlo,monospace;background:var(--bg,#15151a);color:var(--text,#eee);border:1px solid var(--border,rgba(128,128,128,.3));border-radius:8px;outline:none">` +
      `<div class="pf-err" style="color:#f85149;font-size:12px;min-height:16px;margin-top:6px"></div>` +
      (recents.length ? `<div style="font-size:12px;opacity:.6;margin:2px 0 4px">最近打开：</div><div class="pf-recents" style="display:flex;flex-direction:column;gap:1px;max-height:150px;overflow:auto"></div>` : "") +
    `</div>` +
    `<div style="display:flex;gap:8px;padding:0 14px 14px;justify-content:flex-end">` +
      `<button class="pf-cancel" type="button" style="padding:6px 12px;border-radius:7px;border:1px solid var(--border,rgba(128,128,128,.35));background:none;color:inherit;cursor:pointer;font:inherit;font-size:12px">取消</button>` +
      `<button class="pf-open" type="button" style="padding:6px 14px;border-radius:7px;border:none;background:var(--accent,#3b82f6);color:#fff;cursor:pointer;font:inherit;font-size:12px">打开</button>` +
    `</div>`;
  overlay.appendChild(modal);
  document.body.appendChild(overlay);

  const input = modal.querySelector(".pf-input");
  const errEl = modal.querySelector(".pf-err");
  input.value = home;
  setTimeout(() => { input.focus(); input.select(); }, 30);
  const close = () => overlay.remove();
  const tryOpen = async (path) => {
    const p = (path || "").trim().replace(/^['"]|['"]$/g, "");
    if (!p) { errEl.textContent = "请输入路径"; return; }
    try { await backend.readDir(p); }
    catch { errEl.textContent = "找不到这个文件夹（检查路径是否写对）"; return; }
    close();
    await onPick(p);
  };
  modal.querySelector(".pf-close").addEventListener("click", close);
  modal.querySelector(".pf-cancel").addEventListener("click", close);
  overlay.addEventListener("click", (e) => { if (e.target === overlay) close(); });
  modal.querySelector(".pf-open").addEventListener("click", () => tryOpen(input.value));
  input.addEventListener("keydown", (e) => { if (e.key === "Enter") { e.preventDefault(); tryOpen(input.value); } else if (e.key === "Escape") close(); });

  const recentsBox = modal.querySelector(".pf-recents");
  if (recentsBox) {
    for (const rp of recents.slice(0, 8)) {
      const path = typeof rp === "string" ? rp : (rp && rp.path);
      if (!path) continue;
      const b = document.createElement("button");
      b.type = "button";
      b.style.cssText = "text-align:left;padding:6px 8px;border-radius:6px;border:none;background:none;color:inherit;cursor:pointer;font:12px ui-monospace,Menlo,monospace;opacity:.85;white-space:nowrap;overflow:hidden;text-overflow:ellipsis";
      b.textContent = path;
      b.addEventListener("mouseenter", () => { b.style.background = "rgba(128,128,128,.15)"; });
      b.addEventListener("mouseleave", () => { b.style.background = "none"; });
      b.addEventListener("click", () => tryOpen(path));
      recentsBox.appendChild(b);
    }
  }
}
$("openFolderBtn").addEventListener("click", chooseFolder);
$("emptyOpenBtn").addEventListener("click", chooseFolder);
// Welcome-screen "打开文件夹" button — was a DUPLICATE id="emptyOpenBtn", so
// getElementById only wired the first one and this big button did nothing.
$("welcomeOpenBtn")?.addEventListener("click", () => {
  const root = rootPath || workspaceRoots[0] || "";
  if (root) newEntry(root, false);
  else chooseFolder();
});
// settings dropdown
// 齿轮与菜单项全部改在 pointerdown 上响应（同侧边栏页签的修复）：AI 回复期间渲染繁忙，
// WKWebView 的 click（按下+松开配对）常被吞——账单/通用设置/快捷键点了没反应。
// pointerdown 一按即达；同一次按压派生的后续 click 用一次性捕获吞掉，防它落到菜单
// 关闭后暴露的底层元素或 document 关单逻辑上。键盘 Enter/Space（合成 click，detail===0）保留。
const settingsDropdown = $("settingsDropdown");
const _swallowNextClick = () => {
  const eat = (e) => { e.stopPropagation(); e.preventDefault(); };
  document.addEventListener("click", eat, { capture: true, once: true });
  setTimeout(() => document.removeEventListener("click", eat, { capture: true }), 350);
};
$("settingsBtn").addEventListener("pointerdown", (e) => {
  if (e.button !== 0) return;
  e.stopPropagation();
  _swallowNextClick();
  if (settingsDropdown) settingsDropdown.hidden = !settingsDropdown.hidden;
});
$("settingsBtn").addEventListener("click", (e) => {
  e.stopPropagation();
  if (e.detail === 0 && settingsDropdown) settingsDropdown.hidden = !settingsDropdown.hidden; // 键盘可达
});
// 按在菜单外 → 关单（pointerdown 保证回复期间也能可靠关闭）；click 路径保留为兜底。
document.addEventListener("pointerdown", (e) => {
  if (!settingsDropdown || settingsDropdown.hidden) return;
  if (settingsDropdown.contains(e.target) || $("settingsBtn").contains(e.target)) return;
  settingsDropdown.hidden = true;
});
document.addEventListener("click", () => { if (settingsDropdown) settingsDropdown.hidden = true; });
if (settingsDropdown) {
  const _dropdownActivate = (item) => {
    settingsDropdown.hidden = true;
    const action = item.dataset.action;
    if (action === "general-settings") openFeaturePanel("settings");
    else if (action === "shortcuts") openFeaturePanel("shortcuts");
    else if (action === "billing") { _showBillingPanel(); }
    else if (action === "login") {
      const dlg = $("loginDialog");
      if (dlg) { _resetLoginUI(); const em = $("loginEmail"); if (em) em.value = ""; dlg.showModal(); setTimeout(() => em?.focus(), 0); }
    }
    else if (action === "logout") {
      _doLogout();
    }
    else if (action === "profile") {
      showProfile();
    }
  };
  settingsDropdown.addEventListener("pointerdown", (e) => {
    if (e.button !== 0) return;
    e.stopPropagation();
    const item = e.target.closest("[data-action]");
    if (!item) return;
    _swallowNextClick();
    _dropdownActivate(item);
  });
  settingsDropdown.addEventListener("click", (e) => {
    e.stopPropagation();
    if (e.detail !== 0) return; // 鼠标路径已由 pointerdown 处理
    const item = e.target.closest("[data-action]");
    if (item) _dropdownActivate(item);
  });
}
$("saveBtn").addEventListener("click", saveActive);
$("runBtn")?.addEventListener("click", runCurrentFile);
// Debug button (left of Run): opens the debugger panel — pick/launch a debug config (breakpoints,
// stepping, variables). Uses the existing DAP-backed debugger UI.
$("debugBtn")?.addEventListener("click", () => { try { startDebugForActiveFile(); } catch {} });
// Michael Premium：顶部工具栏的数据库工作台入口（连接管理器）。
$("michaelPremiumBtn")?.addEventListener("click", () => { try { openMichaelPremium(); } catch {} });

// login state
let _loggedInEmail = null;

// The web sign-in page asks this app, over loopback, whether anyone is signed in, so a
// user who is already logged in here does not retype a password in the browser. Rust
// owns the listener and the origin allowlist; this only keeps its copy of the session
// in step. Mirrored on every login-state change rather than set once at login, so a
// logout — or an expired token cleared by refreshMichaelUser — revokes it too.
/*
 * Tell the gateway this app is running, so the account page can say so.
 *
 * It used to be the other way round: the web page opened http://127.0.0.1:47821 and
 * asked this app directly. That cannot be made to work. Chrome 150, with the app
 * running, listening, answering the CORS preflight with
 * Access-Control-Allow-Private-Network, and with local-network-access *granted*, still
 * failed the request with a bare "TypeError: Failed to fetch". An HTTPS page reaching a
 * plaintext loopback port is the exact shape browsers have been closing off, and there
 * is nothing left to fix on this side of it.
 *
 * Reporting outward has no such problem — this is the same authenticated call the app
 * already makes for everything else. It also means the status is right even when the
 * console is open on a different machine.
 *
 * Only ever sent while signed in; the token is what tells the gateway whose app this is.
 */
const _HEARTBEAT_MS = 30_000;
let _heartbeatTimer = 0;

async function _sendDesktopHeartbeat() {
  let token = "";
  try { token = localStorage.getItem("michael_token") || ""; } catch (_) {}
  if (!token || !_loggedInEmail) return;
  try {
    await fetch(MICHAEL_API + "/api/desktop/heartbeat", {
      method: "POST",
      headers: { "Content-Type": "application/json", Authorization: "Bearer " + token },
      // Injected from package.json by vite's define; guarded so the browser preview,
      // which is served without that substitution in some paths, cannot throw here.
      body: JSON.stringify({
        version: typeof __APP_VERSION__ === "string" ? __APP_VERSION__ : "",
      }),
      cache: "no-store",
    });
  } catch (_) {
    // Offline, or the gateway is restarting. The presence key simply expires; the next
    // beat revives it. Nothing to report and nothing to retry.
  }
}

function _startDesktopHeartbeat() {
  if (!inTauri || _heartbeatTimer) return;
  void _sendDesktopHeartbeat();
  _heartbeatTimer = setInterval(_sendDesktopHeartbeat, _HEARTBEAT_MS);
}

/**
 * 网页登录页通过 `mrday://signin` 唤起本 App，请求把这里的登录身份交接到浏览器。
 *
 * **深链不携带任何凭据，这是有意的。** 上一版是网页先向网关要一对 nonce+secret，再让这里
 * 拿着 nonce 去认领。那个 start 接口按设计公开（调用它的正是还没登录的人），于是任何一个
 * 网站都能自己要一对、诱导受害者的 App 去认领，然后用自己手里的 secret 换走受害者完整的
 * 会话 —— 一个不需要用户做任何事的账号接管。校验来源补不上：攻击者用 curl 就能完成那两步，
 * 受害者的浏览器根本不参与。
 *
 * 所以现在由这边发起，密钥一步都不经过发起方：
 *
 *   1. 用**本 App 自己的登录令牌**向网关换一个一次性交接码（offer）；
 *   2. **由本 App 亲自打开系统浏览器**到 `/gate?handoff=<code>`；
 *   3. 那个页面把码换成会话（redeem），取走即焚。
 *
 * 攻击者能造成的唯一后果，是受害者自己的浏览器上真的登录了他自己的账号 —— 那正是他点那个
 * 按钮想要的结果。因为码从网关直接经由本 App 进入用户自己的浏览器，第三方没有任何位置可以
 * 插进来，也因此不需要弹确认框。
 *
 * 没登录就什么都不做：没有可交接的身份，静默比弹一个错更合适（用户是在浏览器那边点的，
 * 那边会自己超时并提示）。
 */
async function _handleHandoffSignin() {
  let token = "";
  try { token = localStorage.getItem("michael_token") || ""; } catch (_) {}
  if (!token || !_loggedInEmail) return;
  try {
    const r = await fetch(_michaelBase() + "/api/auth/handoff/offer", {
      method: "POST",
      headers: { "Content-Type": "application/json", Authorization: "Bearer " + token },
      body: JSON.stringify({}),
    });
    const j = await r.json().catch(() => ({}));
    if (!r.ok || !j.url) {
      console.warn("[handoff] offer rejected:", r.status, j.error || "");
      return;
    }
    // 必须由这里打开。整个设计的安全性就建立在「码只走网关 → 本 App → 用户自己的浏览器」
    // 这条路径上；把 url 交给别人去开，就等于把上一版的漏洞原样搬回来。
    await backend.openUrl(j.url);
  } catch (e) {
    console.warn("[handoff] offer failed:", e && e.message);
  }
}

// 深链事件由 Rust 侧发出（lib.rs 的 on_open_url）。App 没运行时系统会先把它启动起来，
// 所以这个监听要尽早挂上。
if (inTauri) {
  (async () => {
    try {
      const { listen } = await import("@tauri-apps/api/event");
      await listen("michael://handoff-signin", () => { void _handleHandoffSignin(); });
    } catch (_) { /* 老版本后端没有这个事件，忽略 */ }
  })();
}

function _syncHandoffSession() {
  // Signing in or out changes what the heartbeat should say, so send one immediately
  // rather than leaving the console up to 30s out of date.
  _startDesktopHeartbeat();
  void _sendDesktopHeartbeat();
  if (!inTauri || !backend?.invoke) return;
  let token = "";
  try { token = localStorage.getItem("michael_token") || ""; } catch (_) {}
  const signedIn = !!(token && _loggedInEmail);
  Promise.resolve()
    .then(() => backend.invoke("handoff_set_session", {
      token: signedIn ? token : null,
      email: signedIn ? _loggedInEmail : null,
    }))
    .catch(() => { /* older backend without the command — handoff just stays off */ });
}

/**
 * The account's display identity, matching the console's Shell.tsx: the name when there is one,
 * the email otherwise. Defined once because it is now needed in three places — the profile card,
 * this dropdown, and the avatar's initial — and three copies is how they drift apart.
 */
/**
 * Swap the dropdown's placeholder glyph for the account's real avatar, or the same initial-on-blue
 * the card and the console draw. The generic person outline said nothing about whose account it
 * was — and showed a different thing from the card for the same account.
 */
function _setDropdownAvatar(u, identity) {
  const host = document.querySelector(".settings-dropdown__header");
  const current = host?.querySelector(".settings-dropdown__avatar");
  if (!host || !current) return;
  const next = u?.avatar ? document.createElement("img") : document.createElement("span");
  next.className = "settings-dropdown__avatar settings-dropdown__avatar--filled";
  if (u?.avatar) {
    next.src = u.avatar;
    next.alt = "";
    next.referrerPolicy = "no-referrer";
    // A dead URL must fall back to the letter, not leave a broken-image frame.
    next.onerror = () => _setDropdownAvatar({ ...u, avatar: "" }, identity);
  } else {
    next.textContent = (identity || "?").slice(0, 1).toUpperCase();
  }
  current.replaceWith(next);
}

function _accountIdentity(u = _michaelUser, fallbackEmail = "") {
  const name = [u?.first_name, u?.last_name]
    .filter((part) => String(part || "").trim())
    .join(" ")
    .trim();
  return name || u?.email || fallbackEmail || "";
}

function _updateLoginUI() {
  _refreshUserLabels(); // relabel already-sent user messages to the current account (or back to 你 on logout)
  const dropName = document.querySelector(".settings-dropdown__name");
  const dropHint = document.querySelector(".settings-dropdown__hint");
  const profileBtn = $("profileBtn");
  const logoutBtn = $("logoutBtn");
  const billingBtn = $("billingBtn");
  const accountActionsDivider = $("accountActionsDivider");
  const logoutDivider = $("logoutDivider");
  const loginHeader = document.querySelector(".settings-dropdown__header");
  let _tok = ""; try { _tok = localStorage.getItem("michael_token") || ""; } catch (_) {}
  if (_loggedInEmail && _tok) {
    // Name when the account has one, email otherwise — the same rule as the card and the console.
    // The email stays on hover, since it is what identifies the account.
    const _identity = _accountIdentity(_michaelUser, _loggedInEmail);
    if (dropName) { dropName.removeAttribute("data-i18n"); dropName.textContent = _identity; dropName.title = _loggedInEmail; }
    _setDropdownAvatar(_michaelUser, _identity);
    const _pn = { trial: "Trial", basic: "Basic", pro: "Pro", power: "Power", ultra: "Ultra" };
    const _u = _michaelUser;
    const _active = _u && _u.plan && _u.plan !== "none" && (!_u.plan_expires_at || new Date(_u.plan_expires_at) > new Date());
    const _hint = _active ? "★ " + (_pn[_u.plan] || _u.plan) + " " + t("account.memberSuffix") : (_u ? t("account.signedInNoPlan") : t("account.signedIn"));
    if (dropHint) { dropHint.removeAttribute("data-i18n"); dropHint.textContent = _hint; dropHint.title = _hint; }
    if (profileBtn) profileBtn.hidden = false;
    if (logoutBtn) logoutBtn.hidden = false;
    if (billingBtn) billingBtn.hidden = false;
    if (accountActionsDivider) accountActionsDivider.hidden = false;
    if (logoutDivider) logoutDivider.hidden = false;
    if (loginHeader) loginHeader.dataset.action = "profile";
  } else {
    if (dropName) { dropName.setAttribute("data-i18n", "account.notSignedIn"); dropName.textContent = t("account.notSignedIn"); dropName.removeAttribute("title"); }
    if (dropHint) { dropHint.setAttribute("data-i18n", "account.signInHint"); dropHint.textContent = t("account.signInHint"); dropHint.removeAttribute("title"); }
    if (profileBtn) profileBtn.hidden = true;
    if (logoutBtn) logoutBtn.hidden = true;
    if (billingBtn) billingBtn.hidden = true;
    if (accountActionsDivider) accountActionsDivider.hidden = true;
    if (logoutDivider) logoutDivider.hidden = true;
    if (loginHeader) loginHeader.dataset.action = "login";
  }
  _syncHandoffSession();
}
// Force the correct initial state NOW (logged-out → profile/logout hidden). Without this the UI
// relied purely on the HTML `hidden` attribute until restoreMichaelSession() resolved — and a dev
// HMR update (module state resets to _loggedInEmail=null while the DOM keeps a prior hidden=false)
// or any stale DOM would leave "退出登录" showing for a user who isn't logged in.
_updateLoginUI();

// login flow
const loginLogoEl = $("loginLogo");
if (loginLogoEl) loginLogoEl.innerHTML = `<img class="assistant-logo" data-app-icon="true" src="${appIconSrc()}" alt="Mr. Day One" style="width:52px;height:52px;border-radius:13px" />`;
// Login / signup flow:
//   step 1 — enter email → validate format → check DB for an existing account
//   existing account → enter password → 登录                 (auth_login)
//   new account      → set password → email code → 完成注册   (auth_send_code + auth_register)
//   existing account may also opt into passwordless code login (auth_verify_code)
let _loginEmail = "";
let _loginMode = "login";   // "login" | "signup" | "code-login"
let _codeSent = false;

function _emailValid(s) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(s || "");
}
function _showCodeField(show) {
  const f = $("loginCodeField"), c = $("loginCode"), otp = $("loginOtp");
  if (f) f.hidden = !show;
  if (c) c.value = "";
  if (otp && otp._reset) otp._reset();
  if (show && otp && otp._focus) setTimeout(() => otp._focus(), 0);
}
// 6-box verification code (Google style): digits only, auto-advance, backspace-to-prev, paste-fill,
// and auto-submit when all 6 are in. Assembles into the hidden #loginCode the existing flow reads.
(function _wireLoginOtp() {
  const otp = document.getElementById("loginOtp");
  const hidden = document.getElementById("loginCode");
  if (!otp || !hidden) return;
  const boxes = [...otp.querySelectorAll(".login-otp__box")];
  const sync = () => {
    hidden.value = boxes.map((b) => (b.value.match(/\d/) || [""])[0]).join("").slice(0, 6);
    boxes.forEach((b) => b.classList.toggle("is-filled", !!b.value));
  };
  const maybeSubmit = () => { if (hidden.value.length === 6) { try { document.getElementById("loginSubmitBtn")?.click(); } catch {} } };
  boxes.forEach((box, i) => {
    box.addEventListener("input", () => {
      box.value = ((box.value.match(/\d/g) || []).pop()) || ""; // keep the last typed digit
      sync();
      if (box.value && i < boxes.length - 1) boxes[i + 1].focus();
      maybeSubmit();
    });
    box.addEventListener("keydown", (e) => {
      if (e.key === "Backspace" && !box.value && i > 0) { e.preventDefault(); boxes[i - 1].value = ""; boxes[i - 1].focus(); sync(); }
      else if (e.key === "ArrowLeft" && i > 0) { e.preventDefault(); boxes[i - 1].focus(); }
      else if (e.key === "ArrowRight" && i < boxes.length - 1) { e.preventDefault(); boxes[i + 1].focus(); }
    });
    box.addEventListener("paste", (e) => {
      e.preventDefault();
      const ds = ((e.clipboardData && e.clipboardData.getData("text")) || "").replace(/\D/g, "").slice(0, 6);
      if (!ds) return;
      ds.split("").forEach((d, k) => { if (boxes[k]) boxes[k].value = d; });
      sync();
      boxes[Math.min(ds.length, boxes.length - 1)].focus();
      maybeSubmit();
    });
  });
  otp._reset = () => { boxes.forEach((b) => { b.value = ""; b.classList.remove("is-filled"); }); hidden.value = ""; };
  otp._focus = () => { if (boxes[0]) boxes[0].focus(); };
})();
document.getElementById("loginResendBtn")?.addEventListener("click", async () => {
  const email = _loginEmail || $("loginEmail")?.value?.trim();
  if (!_emailValid(email)) return;
  const btn = document.getElementById("loginResendBtn");
  await _withBtn(btn, t("login.sending"), async () => {
    try { const msg = await backend.authSendCode(email); showToast(typeof msg === "string" ? msg : t("login.resendSuccess")); }
    catch (e) { alert(t("login.sendFailed", { message: e?.message || e })); }
  });
});
function _resetLoginUI() {
  $("loginStep1").hidden = false;
  $("loginStep2").hidden = true;
  _showCodeField(false);
  const pw = $("loginPassword");
  if (pw) { pw.hidden = false; pw.disabled = false; pw.type = "password"; pw.value = ""; }
  _codeSent = false; _loginMode = "login";
}
function _refreshLoginRuntimeLabels() {
  const pw = $("loginPassword");
  if (pw) pw.placeholder = _loginMode === "signup" ? t("login.signupPasswordPlaceholder") : t("login.passwordPlaceholder");
  const useCode = $("loginUseCodeBtn");
  if (useCode) useCode.textContent = t("login.useCode");
  const submit = $("loginSubmitBtn");
  if (submit) {
    submit.textContent = _loginMode === "code-login"
      ? t("login.verify")
      : _loginMode === "signup"
        ? (_codeSent ? t("login.completeSignup") : t("login.signupNext"))
        : t("login.submit");
  }
  const hint = $("loginStep2Hint");
  const email = _loginEmail || $("loginEmail")?.value?.trim();
  if (hint && email && !$("loginStep2")?.hidden) {
    hint.textContent = _loginMode === "signup"
      ? t("login.newAccountHint", { email })
      : t("login.welcomeBack", { email });
  }
}
function _finishLogin(result) {
  if (result && result.success) {
    $("loginDialog")?.close();
    _loggedInEmail = _loginEmail;
    // Auth responses contain the base user row; /api/me adds the authoritative
    // compression capability. Keep the profile now, then fetch that capability.
    if (result.user) _setMichaelUserProfile(result.user, false);
    // Use the login token as the Michael gateway credential.
    if (result.token) { const c = _cfgCache || _DEFAULT_AI_CONFIG; saveConfig({ ...c, gatewayApiKey: result.token }); }
    _updateLoginUI();
    _resetLoginUI();
    _fetchIdePrompts().catch(() => {});
    refreshMichaelUser(true).catch(() => {});
  } else {
    alert((result && result.message) || t("login.failed"));
  }
}
// Branded confirm modal (Google-light) → resolves true/false. Used for destructive actions like
// logout so they're deliberate AND give visible feedback (the "退出登录没有提示" fix).
// 对话框正文的排版。
//
// 之前是整段 esc() 之后直接塞进 div：换行被 HTML 折成空格、`**强调**` 原样吐出一堆星号，
// 一段本来分了小节的说明糊成一坨、还带着 markdown 残渣。这里认三样东西就够了——
// 段落（空行）、换行、以及 **强调**；先转义再做替换，注入面不变。
function _dialogBodyHtml(body) {
  const esc = (v) => String(v == null ? "" : v).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
  const inline = (line) => esc(line)
    .replace(/\*\*([^*]+)\*\*/g, '<strong style="color:#202124;font-weight:600">$1</strong>')
    .replace(/「([^」]+)」/g, '<strong style="color:#202124;font-weight:600">「$1」</strong>');
  return String(body || "")
    .split(/\n{2,}/)                                  // 空行分段
    .map((para) => para.split("\n").map(inline).join("<br>"))
    .filter((para) => para.trim())
    .map((para) => `<p style="margin:0 0 10px">${para}</p>`)
    .join("");
}

function _confirmDialog(title, body, confirmLabel, danger) {
  return new Promise((resolve) => {
    const esc = (s) => String(s == null ? "" : s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
    const ov = document.createElement("div");
    ov.style.cssText = "position:fixed;inset:0;background:rgba(32,33,36,.45);backdrop-filter:blur(2px);display:grid;place-items:center;z-index:100000;font-family:var(--font)";
    const card = document.createElement("div");
    // 短确认框保持 360；说明性长文案给到 460，否则每行只剩十几个字，读起来像一堵墙。
    const _wide = String(body || "").length > 160;
    card.style.cssText = `background:#fff;color:#202124;border-radius:16px;width:${_wide ? 460 : 360}px;max-width:90vw;box-shadow:0 24px 70px rgba(60,64,67,.28),0 4px 12px rgba(60,64,67,.14);overflow:hidden`;
    card.innerHTML =
      `<div style="padding:22px 24px 6px;font-size:17px;font-weight:600">${esc(title)}</div>` +
      (body ? `<div style="padding:2px 24px 16px;font-size:13.5px;color:#5f6368;line-height:1.65;max-height:52vh;overflow-y:auto">${_dialogBodyHtml(body)}</div>` : `<div style="height:12px"></div>`) +
      `<div style="display:flex;justify-content:flex-end;gap:10px;padding:8px 20px 18px">` +
        `<button class="_cd-cancel" style="padding:8px 18px;border-radius:8px;border:1px solid #dadce0;background:#fff;color:#3c4043;cursor:pointer;font-size:13.5px;font-weight:600">取消</button>` +
        `<button class="_cd-ok" style="padding:8px 18px;border-radius:8px;border:0;background:${danger ? "#d93025" : "#1a73e8"};color:#fff;cursor:pointer;font-size:13.5px;font-weight:600">${esc(confirmLabel || "确定")}</button>` +
      `</div>`;
    ov.appendChild(card);
    document.body.appendChild(ov);
    const done = (val) => { try { ov.remove(); } catch {} document.removeEventListener("keydown", onKey, true); resolve(val); };
    const onKey = (e) => { if (e.key === "Escape") { e.preventDefault(); done(false); } else if (e.key === "Enter") { e.preventDefault(); done(true); } };
    document.addEventListener("keydown", onKey, true);
    ov.addEventListener("click", (e) => { if (e.target === ov) done(false); });
    card.querySelector("._cd-cancel").addEventListener("click", () => done(false));
    card.querySelector("._cd-ok").addEventListener("click", () => done(true));
    setTimeout(() => { try { card.querySelector("._cd-ok").focus(); } catch {} }, 0);
  });
}

// ============================================================================
// 旧版残留清理器
// ============================================================================
//
// 用户反复反馈「装了新版还像旧版」。把每一层摸过一遍之后，成因分三类，
// 这一段只管第三类，前两类在别处修，也修不了：
//
//   1. 有东西在运行时把新版盖掉 —— 例如第三方语言包整份压过内置词典。清缓存没用，
//      覆盖发生在每次启动。（已修：扩展的 registerLocale 改成只补空缺。）
//   2. 新版根本没送到用户手上 —— 同一个版本号切了两次内容不同的包，更新器按
//      semver 严格大于判断，永远不下发。这是发版纪律，不是残留。
//   3. 真残留 —— 换包留下的旧 .app 副本、失效的站点数据、网络缓存，以及被更高版本
//      取代之后再没人读的本地存储键。只有这一类清得掉。

/**
 * 启动时静默清掉「已经被更高版本取代」的本地存储键。
 *
 * **判据不是「看起来像缓存」，也不是键名白名单，而是「同一个基名存在更高版本」。**
 * 这一点很关键：按名字猜的话，`michael_token`（登录凭据）、`michael-ide.chat-sessions`
 * （聊天镜像）这种都会被误伤；而「有更高版本的同名键」是**结构性证据**——写新版本的
 * 那段代码已经在用新的了，旧的那个再没人读。
 *
 * 这段是从 i18n 那个先例推广来的：initLocale 里手写了一串「删掉 v1..v5」的名单，
 * 每次涨版本都要有人记得去补一条，漏一条旧键就活下来。这里不需要任何人记得。
 */
function _sweepSupersededStorage() {
  const removed = [];
  try {
    // base -> 出现过的版本号
    const versions = new Map();
    const parse = (key) => {
      const m = /^(.*?)[._-]v(\d+)$/.exec(key);
      return m ? { base: m[1] + "|" + key.slice(m[1].length, key.length - m[2].length), n: Number(m[2]) } : null;
    };
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i);
      const p = key && parse(key);
      if (!p) continue;
      const seen = versions.get(p.base) || [];
      seen.push({ key, n: p.n });
      versions.set(p.base, seen);
    }
    for (const list of versions.values()) {
      if (list.length < 2) continue;                 // 只有一个版本 = 它就是现役的
      const top = Math.max(...list.map((x) => x.n));
      for (const { key, n } of list) {
        if (n >= top) continue;
        removed.push(key);
      }
    }
    for (const key of removed) {
      try { localStorage.removeItem(key); } catch { /* 单条失败不影响其余 */ }
    }
    // 记一条水位线：它是这套机制唯一自己写、且自己永远不清的键。
    try { localStorage.setItem("michael-ide.cleaner.last-run-version", String(appPackage?.version || "")); } catch {}
  } catch { /* 存储被禁用/配额满：清扫是锦上添花，绝不能因此挡住启动 */ }
  if (removed.length) console.info("[cleaner] 清掉已被取代的存储键:", removed);
  return removed;
}

/** 把字节数说成人话。 */
function _cleanupBytes(n) {
  const b = Number(n) || 0;
  if (b >= 1024 * 1024 * 1024) return (b / 1024 / 1024 / 1024).toFixed(1) + " GB";
  if (b >= 1024 * 1024) return (b / 1024 / 1024).toFixed(1) + " MB";
  if (b >= 1024) return (b / 1024).toFixed(0) + " KB";
  return b + " B";
}

/**
 * 清理器的界面入口。
 *
 * 分两次问：`auto` 那档（别处有权威副本，最坏后果是重取一次）一次确认就清；
 * `manual` 那档（旧版副本＝回滚点，清了就没了）单独再问一次，措辞里说清代价。
 * 不做成一个「全部清理」按钮 —— 这两档的后果完全不是一个量级。
 */
async function openCleanupDialog() {
  if (!inTauri) { showToast("清理器只在桌面版可用"); return; }
  let items = [];
  try { items = await backend.invoke("cleanup_scan"); } catch (e) {
    showToast("扫描失败：" + String(e?.message || e)); return;
  }
  if (!Array.isArray(items) || !items.length) {
    await _confirmDialog("清理旧版残留", "没有找到可清理的残留。\n\n"
      + "聊天记录、项目记忆、登录凭据和项目信任决定不在清理范围内——它们不可重建，"
      + "清理器连扫都不扫。", "知道了", false);
    return;
  }
  const auto = items.filter((i) => i.tier === "auto");
  const manual = items.filter((i) => i.tier !== "auto");
  const fmt = (list) => list.map((i) =>
    `- **${i.label}** · ${_cleanupBytes(i.bytes)}（${i.entries} 项）\n  ${i.detail}`).join("\n");

  if (auto.length) {
    const total = auto.reduce((s, i) => s + (Number(i.bytes) || 0), 0);
    const body = `可以安全清理 **${_cleanupBytes(total)}**：\n\n${fmt(auto)}\n\n`
      + `清掉的东西会先进${/Mac/i.test(navigator.platform || navigator.userAgent) ? "废纸篓" : "隔离区（七天后自动清空）"}，不是直接删除，随时能拿回来。`;
    if (await _confirmDialog("清理旧版残留", body, "清理", false)) {
      await _runCleanup(auto.map((i) => i.id));
    }
  }
  if (manual.length) {
    const total = manual.reduce((s, i) => s + (Number(i.bytes) || 0), 0);
    const body = `还有 **${_cleanupBytes(total)}** 需要你确认：\n\n${fmt(manual)}\n\n`
      + `这一档和上面不一样——清掉之后就回不到那些旧版本了。`;
    if (await _confirmDialog("清理旧版副本", body, "确认清理", true)) {
      await _runCleanup(manual.map((i) => i.id));
    }
  }
}

async function _runCleanup(ids) {
  let rep = null;
  try { rep = await backend.invoke("cleanup_apply", { ids }); } catch (e) {
    showToast("清理失败：" + String(e?.message || e)); return;
  }
  const freed = _cleanupBytes(rep?.freed_bytes);
  const failed = Array.isArray(rep?.failed) ? rep.failed : [];
  if (failed.length) {
    // 失败要说得出是哪条、为什么。静默跳过等于让用户以为清干净了。
    await _confirmDialog("清理完成，但有几项没动",
      `已腾出 **${freed}**，可以在${rep?.recovered_from || "废纸篓"}里找回。\n\n`
      + `没能清理的：\n` + failed.map(([p, why]) => `- \`${p}\`\n  ${why}`).join("\n"),
      "知道了", false);
  } else {
    showToast(`已清理 ${freed} —— 都在${rep?.recovered_from || "废纸篓"}里，需要可以拿回来`);
  }
}

// Log out: confirm → clear ALL client session state → refresh UI immediately → toast. Every step is
// guarded and the UI update runs FIRST, so a slow/failed config write can never leave the "退出登录"
// button stuck visible (the old handler ran an unguarded saveConfig BEFORE _updateLoginUI).
async function _doLogout() {
  const ok = await _confirmDialog(t("account.logoutConfirmTitle"), t("account.logoutConfirmBody"), t("account.logout"), true);
  if (!ok) return;
  _loggedInEmail = null; _setMichaelUserProfile(null); _lastUserRefresh = 0;
  try { _updateLoginUI(); } catch (_) {}       // hide profile/logout NOW, before any async work
  try { refreshModelBadge(); } catch (_) {}
  try { localStorage.removeItem("michael_token"); } catch (_) {}
  try { const c = _cfgCache || _DEFAULT_AI_CONFIG; saveConfig({ ...c, providerMode: AI_PROVIDER_GATEWAY, gatewayApiKey: "", apiKey: "" }); } catch (_) {} // async; fire-and-forget
  try { showToast(t("account.logoutSuccess")); } catch (_) {}
}
// run an async action with the button showing a transient label, always restored
async function _withBtn(btn, label, fn) {
  const orig = btn.textContent;
  btn.textContent = label; btn.disabled = true;
  try { return await fn(); }
  finally { btn.disabled = false; btn.textContent = orig; }
}

$("loginCloseBtn")?.addEventListener("click", () => { $("loginDialog")?.close(); _resetLoginUI(); });

$("loginNextBtn")?.addEventListener("click", async () => {
  const email = $("loginEmail")?.value?.trim();
  if (!_emailValid(email)) { alert(t("login.invalidEmail")); $("loginEmail")?.focus(); return; }
  await _withBtn($("loginNextBtn"), t("login.checking"), async () => {
    let exists;
    try { exists = await backend.authCheckEmail(email); }
    catch (e) { alert(t("login.checkEmailFailed", { message: e?.message || e })); return; }
    _loginEmail = email;
    _loginMode = exists ? "login" : "signup";
    _codeSent = false;
    const pw = $("loginPassword");
    pw.hidden = false; pw.disabled = false; pw.type = "password"; pw.value = "";
    pw.placeholder = exists ? t("login.passwordPlaceholder") : t("login.signupPasswordPlaceholder");
    _showCodeField(false);
    $("loginStep2Hint").textContent = exists
      ? t("login.welcomeBack", { email })
      : t("login.newAccountHint", { email });
    $("loginSubmitBtn").textContent = exists ? t("login.submit") : t("login.signupNext");
    $("loginUseCodeBtn").hidden = !exists;          // passwordless code login: existing accounts only
    $("loginUseCodeBtn").textContent = t("login.useCode");
    $("loginStep1").hidden = true;
    $("loginStep2").hidden = false;
    setTimeout(() => pw.focus(), 0);
  });
});

$("loginBackBtn")?.addEventListener("click", () => { _resetLoginUI(); $("loginEmail")?.focus(); });

$("loginSubmitBtn")?.addEventListener("click", async () => {
  const email = _loginEmail || $("loginEmail")?.value?.trim();
  const password = $("loginPassword")?.value || "";
  const code = $("loginCode")?.value?.trim() || "";
  const btn = $("loginSubmitBtn");
  try {
    if (_loginMode === "login") {
      if (!password) { $("loginPassword")?.focus(); return; }
      _finishLogin(await _withBtn(btn, t("login.loggingIn"), () => backend.authLogin(email, password)));
    } else if (_loginMode === "code-login") {
      if (code.length !== 6) { $("loginCode")?.focus(); return; }
      _finishLogin(await _withBtn(btn, t("login.verifying"), () => backend.authVerifyCode(email, code)));
    } else { // signup
      if (!_codeSent) {
        if (password.length < 6) { alert(t("login.passwordMin")); $("loginPassword")?.focus(); return; }
        const msg = await _withBtn(btn, t("login.sendingCode"), () => backend.authSendCode(email));
        _codeSent = true;
        const pw = $("loginPassword"); if (pw) pw.disabled = true;   // lock the chosen password
        _showCodeField(true);
        $("loginSubmitBtn").textContent = t("login.completeSignup");
        alert(msg);
      } else {
        if (code.length !== 6) { $("loginCode")?.focus(); return; }
        _finishLogin(await _withBtn(btn, t("login.signingUp"), () => backend.authRegister(email, password, code)));
      }
    }
  } catch (e) {
    alert(t("login.failed") + "：" + (e?.message || e));
  }
});

$("loginUseCodeBtn")?.addEventListener("click", async () => {
  // passwordless code login for an existing account
  const email = _loginEmail || $("loginEmail")?.value?.trim();
  if (!_emailValid(email)) return;
  _loginMode = "code-login";
  const pw = $("loginPassword"); if (pw) pw.hidden = true;
  _showCodeField(true);
  $("loginSubmitBtn").textContent = t("login.verify");
  $("loginUseCodeBtn").hidden = true;
  try { alert(await backend.authSendCode(email)); }
  catch (e) { alert(t("login.sendFailed", { message: e?.message || e })); }
});

// ---- explorer tabs / tools / search ----
// 页签切换改在 pointerdown 上触发（VS Code 同款）：click 要求 mousedown/mouseup 落在同一
// 元素，WKWebView 里手抖几像素或碰到拖拽判定就丢事件——用户体感"要点好几下才切换"。
// pointerdown 一按即切；整条 seg 容器全域命中，按到 2px 缝隙/内边距也吸附到最近页签。
const _sideTabWhich = (btn) =>
  btn.id === "tabExplorer" ? "explorer"
  : btn.id === "tabGit" ? "git"
  : "debug";
const _sideTabsEl = $("sideTabs");
_sideTabsEl.addEventListener("pointerdown", (e) => {
  if (e.button !== 0) return;
  let btn = e.target && e.target.closest ? e.target.closest(".seg__btn") : null;
  if (!btn) { // 点在缝隙上 → 命中横向最近的页签
    let best = null, bestDist = Infinity;
    for (const b of _sideTabsEl.querySelectorAll(".seg__btn")) {
      const r = b.getBoundingClientRect();
      const d = e.clientX < r.left ? r.left - e.clientX : e.clientX > r.right ? e.clientX - r.right : 0;
      if (d < bestDist) { bestDist = d; best = b; }
    }
    btn = best;
  }
  if (!btn) return;
  showSide(_sideTabWhich(btn));
});
// 键盘可达性：Enter/Space 触发的合成 click（detail===0）仍然切换；鼠标 click 已由
// pointerdown 处理过，跳过避免同一次按压双重刷新。
_sideTabsEl.addEventListener("click", (e) => {
  const btn = e.target && e.target.closest ? e.target.closest(".seg__btn") : null;
  if (!btn || e.detail !== 0) return;
  showSide(_sideTabWhich(btn));
});
