async function replaceInFiles(replaceAll) {
  const query = $("searchInput").value;
  const replacement = replaceInputEl.value;
  if (!query || !rootPath) return;

  // 每一条失败都要能说出来。这个函数原来只有成功路径会 ++，失败全部落进空 catch：
  // 搜索失败 → 直接 return（点了按钮什么都没发生）；读文件失败 → continue；文件有未保存
  // 改动 → continue；CAS 冲突时那句精心写好的「编辑期间内容变化，替换已撤销」被
  // `catch { /* skip */ }` 原地吃掉。最后 `if (totalCount > 0)` 还没有 else——**全部失败时
  // 连一个 toast 都不弹**。
  //
  // 于是用户看到「已替换 40 处 / 8 个文件」，实际有几个文件根本没写进去，带着半改的代码
  // 去提交；或者按钮点下去毫无反应，看起来像坏了。跨文件替换是不可逆的批量操作，
  // 谎报成功比失败本身严重。
  let totalCount = 0, fileCount = 0;
  const skippedDirty = [];   // 有未保存改动，故意不动
  const failed = [];         // { rel, why }
  let files;
  try {
    files = await backend.searchInProject(rootPath, query, searchCaseSensitive);
  } catch (e) {
    showToast(`替换没能开始：搜索失败（${String(e?.message || e).slice(0, 80)}）`);
    return;
  }

  for (const f of files) {
    if (!replaceAll && totalCount > 0) break;
    const filePath = _coherentFilePath(f.path);
    let content;
    try { content = await backend.readTextFile(filePath); }
    catch (e) { failed.push({ rel: f.rel || filePath, why: `读不出来（${String(e?.message || e).slice(0, 60)}）` }); continue; }
    const regex = searchCaseSensitive
      ? new RegExp(query.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"), "g")
      : new RegExp(query.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"), "gi");
    // 替换文本必须按**字面量**插入。传字符串给 replace 时，$& $' $` $$ $1 $<name>
    // 全是替换模式：把 SEP 换成 IFS=$'\n' 时，$' 会展开成「匹配点之后的全部内容」，
    // 于是每个命中点插进一整份文件尾部——文件成倍膨胀、语法全毁，写盘还成功，
    // toast 照报「已替换 N 处」。SQL 的 $$、Makefile 的 $$VAR 同理。
    // 传函数则返回值原样插入，不做任何模式解释。
    const newContent = content.replace(regex, () => replacement);
    if (newContent !== content) {
      try {
        const open = openFiles.get(filePath);
        // 跳过有未保存改动的文件是对的（不该覆盖用户正在编辑的内容），但必须说出来，
        // 否则用户以为整个项目都替换过了。
        if (open?.dirty) { skippedDirty.push(f.rel || filePath); continue; }
        await backend.writeTextFileIfUnchanged(filePath, content, newContent);
        if (open) {
          const sync = _applyDiskContentToOpenFile(filePath, newContent);
          if (sync.state === "conflict") {
            let rolledBack = false;
            try { await backend.writeTextFileIfUnchanged(filePath, newContent, content); rolledBack = true; } catch {}
            if (rolledBack) open.externalConflict = false;
            throw new Error(rolledBack ? "编辑期间内容变化，替换已撤销" : "编辑期间内容变化，已保留编辑器内容");
          }
        }
        const count = (content.match(regex) || []).length;
        totalCount += count;
        fileCount++;
      } catch (e) {
        // 这里原来是 `catch { /* skip */ }`，把上面那句写得很清楚的冲突原因也一起吃掉了。
        failed.push({ rel: f.rel || filePath, why: String(e?.message || e).slice(0, 60) });
      }
    }
    if (!replaceAll) break;
  }

  // 无论成败都出一条 toast——全部失败时静默是最坏的结果，用户会以为按钮坏了或者以为做完了。
  const parts = [];
  if (totalCount > 0) {
    parts.push(replaceAll
      ? t("search.replaced", { count: totalCount, s: totalCount === 1 ? "" : "s", files: fileCount, s2: fileCount === 1 ? "" : "s" })
      : t("search.replacedInFile", { count: totalCount, s: totalCount === 1 ? "" : "s" }));
  }
  if (skippedDirty.length) parts.push(`跳过 ${skippedDirty.length} 个有未保存改动的文件（${skippedDirty.slice(0, 3).join("、")}${skippedDirty.length > 3 ? " 等" : ""}）`);
  if (failed.length) parts.push(`${failed.length} 个失败：${failed.slice(0, 2).map((x) => `${x.rel}（${x.why}）`).join("；")}${failed.length > 2 ? " 等" : ""}`);
  if (!parts.length) parts.push(`没有替换任何内容——${files.length ? "命中的文件都没能写入" : "没有匹配的文件"}`);
  showToast(parts.join(" · "));
  if (totalCount > 0) runSearch();
}

replaceSingleBtn.addEventListener("click", () => replaceInFiles(false));
replaceAllBtn.addEventListener("click", () => replaceInFiles(true));

/*
 * 默认键位。**按平台分两套**——几处不是审美问题，是会被系统/输入法吃掉：
 *   · Markdown 预览：Windows 微软拼音里 Ctrl+. 是中英文标点切换，按下去进不来，
 *     所以非 Mac 走 VS Code 同款的 mod+shift+v。
 *   · 删除文件：Mac 惯例是 ⌘⌫；Windows 惯例是裸 Delete，而 Ctrl+Backspace 在系统里
 *     是"删除前一个词"。
 *   · view.git / view.output 保持 ctrl+ 开头：Mac 上 keyCombo 把 ⌘ 记成 mod、⌃ 记成
 *     ctrl，所以这两条在 Mac 上要按 Control——和 VS Code Mac 版一致，是肌肉记忆。
 */
function _defaultKeybindings() {
  const mac = isMacPlatform();
  return {
    "ctrl+`": "terminal.toggle",
    "mod+o": "file.openFolder",
    "mod+p": "file.quickOpen",
    "mod+s": "file.save",
    "mod+w": "file.close",
    "mod+shift+n": "window.new",
    "mod+shift+e": "view.explorer",
    "mod+shift+f": "view.search",
    "ctrl+shift+g": "view.git",
    "ctrl+shift+u": "view.output",
    "mod+shift+m": "view.problems",
    "mod+shift+p": "commandPalette",
    "mod+\\": "view.splitEditor",
    "mod+r": "code.runCurrentFile",
    // 跳转历史，键位按平台分——和 VS Code 一致，而且**必须**这么分：
    // macOS 上 Option+←/→ 是 Monaco 的「按词移动光标」，是每天都在用的键，抢掉就是
    // 弄坏一个正在工作的功能（这一轮已经因为同样的理由放弃过 ⇧⌘B，那个键归书签）。
    // 所以 mac 走 VS Code 的 ⌃- / ⌃⇧-（cmd+- 是界面缩放，ctrl+- 是空的），
    // Windows/Linux 才用 Alt+←/→。
    // 键名用 arrowleft/arrowright：keyCombo 取的是 e.key.toLowerCase()，方向键是
    // "ArrowLeft" 而不是 "Left"，写成 "alt+left" 永远匹配不上。
    ...(mac
      ? { "ctrl+-": "nav.back", "ctrl+shift+-": "nav.forward" }
      : { "alt+arrowleft": "nav.back", "alt+arrowright": "nav.forward" }),
    "mod+shift+i": "memory.manage",
    "mod+shift+b": "view.bookmarks",
    "mod+shift+x": "view.extensions",
    [mac ? "mod+." : "mod+shift+v"]: "view.markdownPreview",
    "mod+=": "view.zoomIn",
    "mod+-": "view.zoomOut",
    "mod+0": "view.zoomReset",
    // mac 上全屏由系统给（ctrl+cmd+f），不占键位；Windows/Linux 用 F11，和 VS Code 一致。
    ...(mac ? {} : { f11: "view.toggleFullScreen" }),
    [mac ? "mod+backspace" : "delete"]: "file.deleteSelected",
  };
}
const DEFAULT_KEYBINDINGS = _defaultKeybindings();

let userKeybindings = {};

async function loadKeybindings() {
  const store = await getStore();
  userKeybindings = (await store.get("keybindings")) || {};
}

function getKeybindings() {
  const merged = { ...DEFAULT_KEYBINDINGS, ...userKeybindings };
  for (const k of Object.keys(merged)) {
    if (merged[k] === DISABLED_BINDING) delete merged[k];
  }
  return merged;
}

const KB_ACTIONS = {
  "file.openFolder": () => chooseFolder(),
  "window.new": () => _openNewWindow(),
  "terminal.toggle": () => toggleTerminal(),
  "file.quickOpen": () => qoOpen(),
  "file.save": () => saveActive(),
  "file.close": () => activePath && closeFile(activePath),
  "view.explorer": () => showSide("explorer"),
  "view.search": () => showSide("search"),
  "view.git": () => showSide("git"),
  "view.output": () => toggleOutputPanel(),
  "view.bookmarks": () => toggleBookmarksPanel(),
  "view.problems": () => toggleProblems(),
  "memory.manage": () => openMemoryPanel(),
  "commandPalette": () => palette.open(),
  "view.splitEditor": () => toggleSplitEditor(),
  "code.runCurrentFile": () => runCurrentFile(),
  "nav.back": () => navigateBack(),
  "nav.forward": () => navigateForward(),
  "view.markdownPreview": () => _toggleMarkdownPreviewAction(),
  // 全屏以前**整个产品都没有**：全仓唯一的 fullscreen 代码是只读同步。mac 靠系统绿灯，
  // 而 Windows 的原生标题栏被 decorations:false 关掉了——那边根本没有任何全屏入口。
  "view.toggleFullScreen": () => _toggleFullScreen(),
  "view.zoomIn": () => _applyUiZoom(_uiZoom + 0.1),
  "view.zoomOut": () => _applyUiZoom(_uiZoom - 0.1),
  "view.zoomReset": () => _applyUiZoom(1),
  "file.deleteSelected": () => _deleteSelectedTreeItem(),
  // 和命令面板里同 id 的那条对齐（79585 走的是 extPanel.open()）。原来这里指向
  // openMarketplaceModal —— 同一个 id 两处指两个东西，而市场那个列表是**刻意清空**的
  // （见 _mktAllEntries 那处注释：不再展示任何内置/远程扩展），点进去永远「暂无内容」。
  "view.extensions": () => extPanel.open(),
};

function keyCombo(e) {
  const isMac = isMacPlatform();
  const parts = [];
  if ((isMac && e.metaKey) || (!isMac && e.ctrlKey)) parts.push("mod");
  if (e.ctrlKey && (isMac || e.metaKey)) parts.push("ctrl");
  if (e.metaKey && !isMac) parts.push("meta");
  if (e.shiftKey) parts.push("shift");
  if (e.altKey) parts.push("alt");
  const key = e.key.toLowerCase();
  if (!["control", "shift", "alt", "meta"].includes(key)) parts.push(key);
  return parts.join("+");
}

function keyComboAliases(e) {
  const combo = keyCombo(e);
  const aliases = [combo];
  // Back-compat: older Windows/Linux builds recorded/defaulted Ctrl shortcuts as
  // `ctrl+...`. The canonical cross-platform form is now `mod+...`, but trying
  // the legacy alias keeps existing saved bindings working.
  if (!isMacPlatform() && e.ctrlKey && !e.metaKey && combo.startsWith("mod+")) {
    aliases.push("ctrl+" + combo.slice(4));
  }
  return [...new Set(aliases.filter(Boolean))];
}

loadKeybindings().catch(console.error);

/*
 * 焦点在能打字的地方吗？（输入框 / 文本域 / contenteditable / 编辑器 / 终端）
 *
 * **不带修饰键的绑定必须先问这一句。** Windows 上删除文件的默认键位是裸 `delete`
 * （macOS 是 mod+backspace，天然不冲突），而下面那个派发器以前是无条件先
 * `preventDefault()` 再执行动作。于是在编辑器里、在聊天输入框里、在终端里按 Delete：
 * 默认行为被吃掉（字符删不掉），删文件那个动作又被它自己内部的焦点守卫挡住——
 * 净效果是 **Delete 键在整个应用里失效**。
 *
 * 守卫放在派发器这一层而不是各个动作里：它是一条通则——没有修饰键的键位在打字的时候
 * 本来就该让给输入。以后再加裸键绑定，不必每个都记得自己写一遍。
 */
function _focusIsTextEntry() {
  const ae = document.activeElement;
  if (!ae) return false;
  if (ae.tagName === "INPUT" || ae.tagName === "TEXTAREA" || ae.isContentEditable) return true;
  return !!(ae.closest && (ae.closest(".monaco-editor") || ae.closest(".xterm")));
}

window.addEventListener("keydown", (e) => {
  // 输入法正在组字时不抢键。Windows 上中文输入是常态（微软拼音），组字过程中浏览器会发
  // 一串 keydown（isComposing / keyCode 229），这时候把键抢走就是把用户正在拼的字打断。
  // 本仓库别处的输入处理已经这么判了（编辑器和输入框那两处），全局派发器漏了。
  if (e.isComposing || e.keyCode === 229) return;
  const bindings = getKeybindings();
  const combos = keyComboAliases(e);
  const action = combos.map((combo) => bindings[combo]).find(Boolean);
  if (!action || !KB_ACTIONS[action]) return;
  // 裸键（不含 mod/ctrl/alt/shift）在打字时让路：不拦默认行为，也不触发动作。
  // 功能键（F1~F12）**不算裸键**——它们从来不是「正在打字」，让路给编辑器/终端
  // 等于这类键位在 IDE 里永远收不到（编辑器有焦点是常态）。上面那条让路规则是为
  // 裸 delete 之类立的，别把它套到功能键上。
  const bare = !e.metaKey && !e.ctrlKey && !e.altKey && !/^F\d{1,2}$/.test(e.key || "");
  if (bare && _focusIsTextEntry()) return;
  e.preventDefault();
  e.stopPropagation();
  KB_ACTIONS[action]();
});

// ---- integrated terminal (multi-tab) ----
const termPanel = $("terminalPanel");
const termBody = $("terminalBody");
const termTabBar = $("termTabBar");
const editorwrapEl = document.querySelector(".editorwrap");


let termHistory = [];
function pushTermHistory(cmd) {
  termHistory = termHistory.filter((c) => c !== cmd);
  termHistory.unshift(cmd);
  if (termHistory.length > 300) termHistory.length = 300;
}

// Cache of workspace-relative paths (files + dirs) for argument completion.
let termPathCache = [];
async function refreshTermPathCache() {
  if (!rootPath) { termPathCache = []; return; }
  const out = [];
  const skip = new Set(["node_modules", ".git", "dist", "build", "target", ".next", "coverage", ".cache", "vendor"]);
  const base = rootPath.endsWith("/") ? rootPath : rootPath + "/";
  const stack = [rootPath];
  let count = 0;
  while (stack.length && count < 4000) {
    const dir = stack.pop();
    let entries;
    try { entries = await backend.readDir(dir); } catch { continue; }
    for (const e of entries) {
      const rel = e.path.startsWith(base) ? e.path.slice(base.length) : e.name;
      out.push(e.is_dir ? rel + "/" : rel);
      count++;
      if (e.is_dir && !skip.has(e.name)) stack.push(e.path);
    }
  }
  termPathCache = out;
}

// System commands ($PATH) + the user's shell history, loaded once from the
// backend so suggestions cover every installed tool and real past command.
let termPathCommands = [];
let _termDataLoaded = false;
async function loadTermData() {
  if (_termDataLoaded) return;
  _termDataLoaded = true;
  try {
    const hist = await backend.termHistory?.();
    if (Array.isArray(hist) && hist.length) {
      const existing = new Set(termHistory);
      for (const c of hist) if (!existing.has(c)) termHistory.push(c);
    }
  } catch { /* ignore */ }
  try {
    const cmds = await backend.termListCommands?.();
    if (Array.isArray(cmds)) termPathCommands = cmds;
  } catch { /* ignore */ }
}

function getTermSuggestions(prefix) {
  if (!prefix || prefix.length < 1) return [];
  const seen = new Set();
  const out = [];
  const add = (cmd) => {
    if (cmd.length <= prefix.length || !cmd.startsWith(prefix) || seen.has(cmd)) return;
    seen.add(cmd);
    out.push(cmd);
  };
  for (const c of termHistory) add(c);
  for (const c of TERM_COMMON_CMDS) add(c);
  // Every installed command on $PATH — only when completing the first word.
  if (!prefix.includes(" ")) {
    for (const c of termPathCommands) {
      add(c);
      if (out.length >= 6) break;
    }
  }
  // Argument path completion: complete the last token against workspace paths.
  if (out.length === 0 && prefix.includes(" ")) {
    const cut = prefix.lastIndexOf(" ");
    const head = prefix.slice(0, cut + 1);
    const token = prefix.slice(cut + 1);
    if (token && !token.startsWith("-")) {
      for (const rel of termPathCache) {
        if (rel.length > token.length && rel.startsWith(token)) {
          const full = head + rel;
          if (!seen.has(full)) { seen.add(full); out.push(full); }
          if (out.length >= 6) break;
        }
      }
    }
  }
  return out.slice(0, 6);
}

let _ghostTimer = null;
let _ghostDeco = null;
let _ghostMarker = null;

// Remove the ghost overlay. This ONLY disposes the decoration — it never writes
// to the PTY buffer or moves the cursor, so the shell's line editing (backspace,
// arrows, history) is never disturbed.
function clearTermGhost(entry) {
  if (_ghostDeco) { try { _ghostDeco.dispose(); } catch { /* ignore */ } _ghostDeco = null; }
  if (_ghostMarker) { try { _ghostMarker.dispose(); } catch { /* ignore */ } _ghostMarker = null; }
  if (entry) entry.ghost = "";
}

// Render the suggestion as a non-intrusive overlay decoration positioned at the
// cursor. Because nothing is written into the terminal buffer, editing keys keep
// working exactly as the shell expects.
function renderTermGhost(entry) {
  clearTermGhost(entry);
  if (!entry || entry !== termTabs[activeTermTab] || entry.backendId == null) return;
  const prefix = entry.inputLine;
  const sug = getTermSuggestions(prefix)[0] || "";
  entry.suggestion = sug;
  const ghost = sug ? sug.slice(prefix.length) : "";
  if (!ghost) return;
  const term = entry.term;
  let marker = null;
  let deco = null;
  try {
    marker = term.registerMarker(0);
    if (!marker) return;
    deco = term.registerDecoration({
      marker,
      x: term.buffer.active.cursorX,
      width: Math.min(ghost.length, term.cols),
      layer: "top",
    });
  } catch { return; }
  if (!deco) { try { marker.dispose(); } catch { /* ignore */ } return; }
  _ghostMarker = marker;
  _ghostDeco = deco;
  entry.ghost = ghost;
  deco.onRender((el) => {
    el.textContent = ghost;
    el.classList.add("term-ghost");
  });
}

function scheduleTermGhost(entry) {
  clearTimeout(_ghostTimer);
  _ghostTimer = setTimeout(() => renderTermGhost(entry), 30);
}

// Accept the current ghost: send the remaining characters to the shell.
function acceptTermGhost(entry) {
  if (!entry || !entry.ghost || !entry.suggestion) return false;
  const rest = entry.suggestion.slice(entry.inputLine.length);
  clearTermGhost(entry);
  if (entry.backendId != null && rest) backend.termWrite(entry.backendId, rest);
  entry.inputLine = entry.suggestion;
  return true;
}

function trackTermInput(entry, d) {
  for (const ch of d) {
    const code = ch.charCodeAt(0);
    if (ch === "\r" || ch === "\n") {
      const line = entry.inputLine.trim();
      if (line) {
        pushTermHistory(line);
        entry.lastCommand = line;
      }
      entry.lastActivityAt = Date.now();
      entry.inputLine = "";
      clearTermGhost(entry);
      return;
    } else if (code === 127 || code === 8) {
      entry.inputLine = entry.inputLine.slice(0, -1);
    } else if (code === 27 || code === 3 || code === 21 || code === 23 || code === 9) {
      // ESC sequences (arrow keys), Ctrl-C/U/W, or Tab: stop tracking this line
      entry.inputLine = "";
      clearTermGhost(entry);
      return;
    } else if (code >= 32) {
      entry.inputLine += ch;
      entry.lastActivityAt = Date.now();
    }
  }
  scheduleTermGhost(entry);
}

function termTheme() {
  const dark = document.documentElement.getAttribute("data-theme") === "dark";
  if (dark) {
    return {
      background: "#101011",
      foreground: "#d6d6d6",
      cursor: "#4daafc",
      cursorAccent: "#101011",
      selectionBackground: "rgba(77, 170, 252, 0.24)",
      selectionForeground: "#ffffff",
      black: "#101011", red: "#f87171", green: "#4ade80", yellow: "#fbbf24",
      blue: "#4daafc", magenta: "#c084fc", cyan: "#22d3ee", white: "#d6d6d6",
      brightBlack: "#5f5f63", brightRed: "#fca5a5", brightGreen: "#86efac",
      brightYellow: "#fde68a", brightBlue: "#93c5fd", brightMagenta: "#d8b4fe",
      brightCyan: "#67e8f9", brightWhite: "#ffffff",
    };
  }
  // Light terminal (GitHub Light palette) — dark text on white.
  return {
    background: "#ffffff",
    foreground: "#1f2328",
    cursor: "#0a84ff",
    cursorAccent: "#ffffff",
    selectionBackground: "rgba(10, 132, 255, 0.18)",
    selectionForeground: "#1f2328",
    black: "#24292f", red: "#cf222e", green: "#116329", yellow: "#7d4e00",
    blue: "#0969da", magenta: "#8250df", cyan: "#1b7c83", white: "#6e7781",
    brightBlack: "#57606a", brightRed: "#a40e26", brightGreen: "#1a7f37",
    brightYellow: "#633c01", brightBlue: "#218bff", brightMagenta: "#a475f9",
    brightCyan: "#3192aa", brightWhite: "#8c959f",
  };
}

const termIsOpen = () => termPanel && !termPanel.hidden;

const termResizeObserver = new ResizeObserver(() => {
  if (termIsOpen() && activeTermTab >= 0 && termTabs[activeTermTab]?.fit) {
    try { termTabs[activeTermTab].fit.fit(); } catch {}
  }
});

let termTabs = [];
let activeTermTab = -1;
let termSeq = 0;
let _termSplitActive = false;

/**
 * 哪些终端里真的有命令在跑。
 *
 * 标签上的 `▶` 是**出身**不是**状态**：它只说明这个终端是智能体为某个任务开的，任务
 * 跑完了它还在，所以一排终端里根本看不出谁还在动。真状态问 PTY 的前台进程组
 * （term_running_ids），用户自己敲的 npm run dev 一样算得上。
 *
 * 只在终端面板可见时轮询；面板收起来就停，不给后台白烧。
 */
const _TERM_RUNNING_POLL_MS = 900;
let _termRunningIds = new Set();
let _termRunningTimer = 0;

function _applyTermRunningState() {
  if (!termTabBar) return;
  const buttons = termTabBar.querySelectorAll(".term-tab:not(.term-tab--debug)");
  termTabs.forEach((tab, i) => {
    const btn = buttons[i];
    if (btn) btn.classList.toggle("is-running", tab.backendId != null && _termRunningIds.has(tab.backendId));
  });
}

async function _pollTermRunning() {
  try {
    const ids = await backend.termRunningIds?.();
    const next = new Set(Array.isArray(ids) ? ids : []);
    // 只有集合真的变了才动 DOM——每秒无谓地改 class 会让 CSS 动画不停重启。
    let changed = next.size !== _termRunningIds.size;
    if (!changed) for (const id of next) if (!_termRunningIds.has(id)) { changed = true; break; }
    _termRunningIds = next;
    if (changed) _applyTermRunningState();
  } catch {}
}

function _startTermRunningPoll() {
  if (_termRunningTimer) return;
  _pollTermRunning();
  _termRunningTimer = setInterval(_pollTermRunning, _TERM_RUNNING_POLL_MS);
}

function _stopTermRunningPoll() {
  if (!_termRunningTimer) return;
  clearInterval(_termRunningTimer);
  _termRunningTimer = 0;
  if (_termRunningIds.size) { _termRunningIds = new Set(); _applyTermRunningState(); }
}

function renderTermTabs() {
  if (!termTabBar) return;
  termTabBar.innerHTML = "";
  termTabs.forEach((tab, i) => {
    const btn = document.createElement("button");
    btn.className = "term-tab" + (i === activeTermTab ? " is-active" : "");
    btn.type = "button";
    btn.title = tab.cwd ? `${tab.label} — ${tab.cwd}` : tab.label;
    btn.innerHTML =
      `<svg class="term-tab__icon" viewBox="0 0 24 24" aria-hidden="true"><use href="#i-terminal" /></svg>` +
      `<span class="term-tab__live" aria-hidden="true"></span>` +
      `<span class="term-tab__label"></span>` +
      `<span class="term-tab__x" title="Close" aria-label="Close terminal">` +
      `<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round"><path d="M4.5 4.5l7 7M11.5 4.5l-7 7"/></svg>` +
      `</span>`;
    btn.querySelector(".term-tab__label").textContent = tab.label;
    btn.addEventListener("click", (e) => {
      if (e.target.closest(".term-tab__x")) closeTermTab(i);
      else switchTermTab(i);
    });
    termTabBar.appendChild(btn);
  });
  _applyTermRunningState();   // 重建标签后立刻把运行态贴回去，避免闪一下没有指示
  // 轮询的开关挂在这里而不是各个"打开面板"的调用点：面板有三条打开路径，其中智能体
  // 派任务那条（_runTaskInNewTerminal）刻意绕开 openTerminal，正好是最需要看运行态的
  // 那条。挂在渲染出口上，哪条路进来都覆盖得到。
  if (termIsOpen() && termTabs.length) _startTermRunningPoll();
  else _stopTermRunningPoll();
  // The debug console lives here too, as a peer tab of the terminals (present while its container exists).
  if (_dbgConsoleEl) {
    const btn = document.createElement("button");
    btn.className = "term-tab term-tab--debug" + (_dbgConsoleActive ? " is-active" : "");
    btn.type = "button";
    btn.title = "调试控制台";
    btn.innerHTML =
      `<svg class="term-tab__icon" viewBox="0 0 24 24" aria-hidden="true"><use href="#i-bug" /></svg>` +
      `<span class="term-tab__label">调试控制台</span>` +
      `<span class="term-tab__x" title="关闭" aria-label="关闭调试控制台"><svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round"><path d="M4.5 4.5l7 7M11.5 4.5l-7 7"/></svg></span>`;
    btn.addEventListener("click", (e) => {
      if (e.target.closest(".term-tab__x")) hideDebugDock();
      else showDebugDock();
    });
    termTabBar.appendChild(btn);
  }
}

function switchTermTab(idx) {
  if (idx < 0 || idx >= termTabs.length) return;
  // If the debug console tab is showing, leaving it for a terminal hides the console.
  const wasDebug = _dbgConsoleActive;
  if (wasDebug) { if (_dbgConsoleEl) _dbgConsoleEl.hidden = true; _dbgConsoleActive = false; }
  if (!wasDebug && idx === activeTermTab) return;
  clearTermGhost(termTabs[activeTermTab]);
  // In split view both panes stay visible; only single view hides the old one.
  if (!_termSplitActive && activeTermTab >= 0 && termTabs[activeTermTab]) {
    termTabs[activeTermTab].container.hidden = true;
  }
  activeTermTab = idx;
  const tab = termTabs[idx];
  tab.container.hidden = false;
  if (_termSplitActive) _applyTermSplit();
  renderTermTabs();
  requestAnimationFrame(() => {
    try { tab.fit.fit(); } catch {}
    tab.term.focus();
  });
}

async function createTermTab(customLabel, cwdOverride = "") {
  // Opening a terminal takes the panel over from the debug console tab.
  if (_dbgConsoleActive) { if (_dbgConsoleEl) _dbgConsoleEl.hidden = true; _dbgConsoleActive = false; }
  const idx = termTabs.length;
  const label = customLabel || `Terminal ${++termSeq}`;
  const cwd = cwdOverride || rootPath || "";
  const container = document.createElement("div");
  container.className = "terminal-panel__instance";
  container.hidden = activeTermTab >= 0;
  termBody.appendChild(container);

  const { Terminal, FitAddon, WebglAddon, WebLinksAddon } = await _loadXterm();
  const term = new Terminal({
    fontSize: 13,
    fontFamily: MONO_STACK,
    fontWeight: "normal",
    fontWeightBold: "bold",
    lineHeight: 1.4,
    letterSpacing: 0.2,
    theme: termTheme(),
    cursorBlink: true,
    cursorStyle: "bar",
    cursorWidth: 2,
    scrollback: 3500, // bounded so a flooding command can't balloon terminal memory/CPU
    allowProposedApi: true,
    drawBoldTextInBrightColors: false,
    minimumContrastRatio: 4.5,
  });
  const fit = new FitAddon();
  term.loadAddon(fit);
  term.open(container);
  // WebGL renderer is much faster, but a lost GPU context (sleep/wake, driver
  // reset, too many contexts) silently stops it rendering — the classic "typing
  // shows nothing / terminal frozen" bug. Dispose the addon on context loss so
  // xterm falls back to the canvas renderer instead of freezing.
  let webglAddon = null;
  try {
    webglAddon = new WebglAddon();
    webglAddon.onContextLoss(() => { try { webglAddon.dispose(); } catch {} webglAddon = null; });
    term.loadAddon(webglAddon);
  } catch { webglAddon = null; /* WebGL unavailable → canvas renderer */ }
  term.loadAddon(new WebLinksAddon());
  termResizeObserver.observe(container);

  let initDone = false;
  let initBuffer = "";
  const now = Date.now();
  /**
   * 把启动失败**显示出来**，而不是把标签页关掉。
   *
   * 原来两条错误路径都调 `closeTermTab(...)`。而 closeTermTab 发现一个标签页都不剩时会
   * 顺手把整个终端面板收起来（见 closeTerminal 的调用点），所以用户点了终端按钮之后看到的
   * 是"什么都没发生"——也就是他报的"打不开终端"。与此同时真正的原因 `entry.startError`
   * 全文件只有写入点、没有任何一处把它渲染出来，启动期输出也被 initBuffer 吞了。
   *
   * 失败必须留在屏幕上：这是 Windows 那台机器上唯一可能拿到的线索。
   */
  const _showTermStartError = (e, buffered) => {
    if (!e || e.closed) return;
    try {
      if (buffered) e.term.write("\r\n\x1b[2m--- shell 启动期输出 ---\x1b[0m\r\n" + buffered);
      e.term.write("\r\n\x1b[31m" + (e.startError || "终端启动失败") + "\x1b[0m\r\n");
      e.term.write("\x1b[2m终端没能起来。上面这段就是原因，请截图或复制发回。\x1b[0m\r\n");
      e.term.write("\x1b[2m（Windows 若有崩溃日志，在 %USERPROFILE%\\.mrdayone\\crash.log）\x1b[0m\r\n");
    } catch { /* xterm 已经被销毁就算了 */ }
  };
  const entry = { term, fit, container, label, cwd, backendId: null, opening: false, closed: false, startError: "", inputLine: "", ghost: "", suggestion: "", webgl: webglAddon, createdAt: now, lastActivityAt: now, lastCommand: "", initTimer: 0 };
  termTabs.push(entry);

  term.onData((d) => {
    if (entry.closed) return;
    // Drop the ghost overlay immediately; it is rebuilt after the echo settles.
    clearTermGhost(entry);
    if (entry.backendId != null) backend.termWrite(entry.backendId, d);
    trackTermInput(entry, d);
  });
  term.onResize(({ cols, rows }) => { if (!entry.closed && entry.backendId != null) backend.termResize(entry.backendId, cols, rows); });
  // Tab accepts the inline ghost suggestion when one is shown; otherwise it
  // falls through to the shell's own completion.
  term.attachCustomKeyEventHandler((e) => {
    if (e.type === "keydown" && e.key === "Tab" && entry.ghost) {
      e.preventDefault();
      acceptTermGhost(entry);
      scheduleTermGhost(entry);
      return false;
    }
    return true;
  });

  switchTermTab(idx);

  entry.opening = true;
  let openedPty = null;
  try {
    openedPty = await backend.termOpen(
      { cwd: cwd || undefined, cols: term.cols, rows: term.rows },
      (ev) => {
        if (entry.closed) return;
        if (ev.kind === "data") {
          entry.lastActivityAt = Date.now();
          if (!initDone) {
            initBuffer += ev.data;
            return;
          }
          // xterm.js parses ANSI escape codes (colors/formatting/cursor moves) NATIVELY — write the
          // raw PTY bytes straight through. (The old code did `require('ansi-to-html')` here, which
          // both crashed with "Can't find variable: require" under ESM/Vite AND was wrong: piping HTML
          // into term.write would render literal <span> tags, not colors. That broke the terminal.)
          term.write(ev.data);
          _detectTerminalChanges(ev.data);
          // Keep a bounded tail of recent output so agent task tools can read back
          // what a launched persistent task printed (e.g. a dev server URL). Trim
          // only when it grows past 2x the cap (not every chunk) — re-slicing an
          // 8KB string on every PTY chunk was needless churn during output floods.
          entry.recentOut = (entry.recentOut || "") + ev.data;
          if (entry.recentOut.length > 16000) entry.recentOut = entry.recentOut.slice(-8000);
        } else if (ev.kind === "exit") {
          entry.lastActivityAt = Date.now();
          term.write("\r\n\x1b[2m[process exited]\x1b[0m\r\n");
          entry.exitCode = Number.isFinite(Number(ev.code)) ? Number(ev.code) : null;
          entry.backendId = null;
          entry.exited = true;
          _scheduleTermRefresh();
        }
      },
    );
    // The tab may be closed, or its shell may exit, while term_open is still
    // resolving. In either case this late backend handle has no live UI owner.
    // Detach the channel before stopping the PTY so queued native events can only
    // reach the inert sink installed by _releaseTauriChannel.
    if (entry.closed || entry.exited) {
      _releaseTauriChannel(openedPty.channel);
      try { await backend.termClose(openedPty.id); } catch {}
      return entry;
    }
    entry.backendId = openedPty.id;
    entry.channel = openedPty.channel; // nulled in closeTermTab so the captured xterm/entry can be GC'd
    // PTY 是用 term.cols/rows 建的，而那两个值在上面 await 之前就求值了——那时 xterm 还是
    // 默认的 80×24。面板真正的 fit 发生在 backendId 赋值**之前**，onResize 因为 backendId
    // 还是 null 被丢弃（见 :60439），于是 PTY 永远停在 80×24：换行位置错、提示符被盖掉、
    // 退格吃错字符，直到用户手动拖一次面板才自愈。SSH 面板早就补了这一行，这里照做。
    try { backend.termResize(entry.backendId, term.cols, term.rows); } catch {}
    const finishInit = () => {
      if (initDone || entry.closed) return;
      initDone = true;
      term.write("\x1b[0m\x1b[?25h");
      // 回放启动期攒下来的输出。
      //
      // 这里原来是 `term.reset()` + 往 PTY 里注入一条 `clear`，为的是开局给用户一块干净屏幕。
      // 代价是：shell 启动头 1.5 秒说的每一句话——banner、profile 里的报错、Windows 上
      // chcp 的失败——先被攒进 initBuffer，然后 reset 连同滚回缓冲一起抹掉，而 initBuffer
      // 从来没有第二个读取点。于是"终端打不开"在界面上永远只剩一片空白，没有任何线索。
      //
      // 注入的那条 `clear` 还有独立的害处：它是**追加在用户这 1.5 秒里已经敲进去的内容后面
      // 再回车**的，敲了一半的 `npm ru` 会变成 `npm ru clear` 被真的执行；而 macOS 的 clear
      // 发的是 ESC[3J，清掉的正是滚回缓冲。
      if (initBuffer) {
        term.write(initBuffer);
        initBuffer = "";
      }
      entry.ready = true; // 启动窗口结束 → 可以安全地往里注入命令了
    };
    // A tab can be closed while its PTY is still in the startup window. Keep the
    // timer on the entry so closeTermTab can cancel it before xterm is disposed.
    entry.initTimer = setTimeout(() => {
      entry.initTimer = 0;
      try { finishInit(); }
      catch (err) {
        entry.startError = "终端初始化失败: " + String(err?.message || err);
        _showTermStartError(entry, initBuffer);
      }
    }, 1500);
  } catch (err) {
    entry.startError = "终端启动失败: " + String(err?.message || err);
    // 后端资源该收还得收，但**标签页要留着**——见 _showTermStartError 的说明。
    if (openedPty) {
      try { _releaseTauriChannel(openedPty.channel); } catch {}
      try { await backend.termClose(openedPty.id); } catch {}
    }
    entry.backendId = null;
    entry.channel = null;
    _showTermStartError(entry, initBuffer);
    initBuffer = "";
  } finally {
    entry.opening = false;
  }
  return entry;
}

// Find an agent task terminal (one started by run_in_terminal — its label is
// prefixed with "▶ "). With a name, match the label (case-insensitive substring);
// without one, return the most-recently-active task terminal. Only powers
// stop_terminal; read_terminal/list_terminals intentionally see every IDE terminal.
function _findTaskTerm(name) {
  return _findAgentTerminal(name, { taskOnly: true });
}

function _sameWorkspace(a, b) {
  const norm = (v) => String(v || "").replace(/\\/g, "/").replace(/\/+$/, "");
  return !!norm(a) && norm(a) === norm(b);
}

function _runOwnedDevServerUrl(run) {
  const server = run?._devServer;
  if (!server || server.requestId !== (run._reqId || "") || !_sameWorkspace(server.root, run.root)) return "";
  if (server.entry && (server.entry.exited || server.entry.backendId == null)) return "";
  return server.url || "";
}

function _isRunOwnedDevUrl(run, url) {
  const owned = _runOwnedDevServerUrl(run);
  if (!owned || !url) return false;
  try { return new URL(url).origin === new URL(owned).origin; } catch { return false; }
}

// Launch a persistent / long-running command in a NEW real IDE terminal tab —
// the task stays attached to the IDE (visible, user-stoppable) instead of dying
// with the agent's one-shot capture subprocess. Returns once the command has been
// written; the caller can read `entry.recentOut` after a short wait.
/// 最多保留多少个「agent 建的、命令已退出」的终端页签。
///
/// 已退出的终端只剩查看价值，而 read_terminal 仍能读到它们的输出，所以保留最近几个就够。
const _AGENT_DEAD_TERM_CAP = 3;

/// 回收 agent 建的、已经跑完的终端页签。
///
/// `run_in_terminal` 每次调用都新建一个页签，而命令退出后没有任何人关掉它 —— 一个
/// agent run 起十几个服务/脚本，就留下十几个常驻的 xterm 实例、WebGL 上下文和 PTY。
/// `closeTermTab` 本身已经把 WebGL / xterm / PTY / ResizeObserver 全部释放干净了，
/// 缺的只是没人调用它。
///
/// 只回收「agent 建的」且「已退出」的；用户自己开的终端、仍在运行的服务（dev server）
/// 一概不碰。最近的几个也留着，方便用户回看这轮到底跑了什么。
function _reapExitedAgentTerminals() {
  try {
    const dead = [];
    for (let i = 0; i < termTabs.length; i++) {
      const t = termTabs[i];
      if (!t || !t.agentCreated) continue;    // 用户自己开的，不碰
      if (!t.exited) continue;                 // 还在跑的服务，不碰
      dead.push(i);
    }
    // 超出上限的部分从最旧的开始关；倒序 splice 以免下标错位。
    const excess = dead.length - _AGENT_DEAD_TERM_CAP;
    if (excess <= 0) return;
    for (const idx of dead.slice(0, excess).reverse()) closeTermTab(idx);
  } catch { /* 回收失败不能影响正在跑的任务 */ }
}

// An agent task terminal that already ran THIS command in THIS cwd. Reusing it instead of
// stacking a new tab is the fix for "the AI opens a new terminal for the same task every time":
// re-running `go run ./cmd/foo` three times used to leave three tabs. Prefer an exited tab (safe
// to re-run in place); fall back to one still running the same command (refocus, don't duplicate
// and don't stack a second process into its PTY).
function _findReusableTaskTerminal(command, cwd) {
  const norm = (s) => String(s || "").trim();
  const cmd = norm(command), dir = norm(cwd);
  if (!cmd) return null;
  let running = null;
  for (const t of termTabs) {
    if (!t || t.closed || !t.agentCreated || t.backendId == null) continue;
    if (norm(t.taskCommand) !== cmd || norm(t.cwd) !== dir) continue;
    if (t.exited) return { entry: t, alreadyRunning: false }; // re-run in place
    running = running || { entry: t, alreadyRunning: true };  // same command already up
  }
  return running;
}

async function _runTaskInNewTerminal(command, label, cwd = "") {
  // Show the panel WITHOUT openTerminal's auto-create (which would add a stray
  // empty default tab); we create exactly one dedicated tab for this task.
  if (termPanel && !termIsOpen()) {
    termPanel.hidden = false;
    editorwrapEl?.classList.add("has-terminal");
    try { monacoEditor.layout(); } catch {}
  }
  // Reuse before creating: the same task should re-run in its own tab, not spawn a new one.
  const _reuse = _findReusableTaskTerminal(command, cwd);
  if (_reuse) {
    const entry = _reuse.entry;
    const idx = termTabs.indexOf(entry);
    if (idx >= 0) { try { switchTermTab(idx); } catch {} }   // bring the existing tab to front
    entry.lastActivityAt = Date.now();
    if (_reuse.alreadyRunning) {
      // Same command already running here — don't duplicate, don't stack a second process.
      return { ok: true, entry, reused: true, alreadyRunning: true };
    }
    // Exited → re-run in place: clear the old output, then send the command again.
    entry.recentOut = "";
    entry.exited = false;
    entry.lastCommand = command;
    try { backend.termWrite(entry.backendId, " " + _clearCmd() + "\n"); } catch {}
    backend.termWrite(entry.backendId, command + "\n");
    return { ok: true, entry, reused: true };
  }
  const entry = await createTermTab(label, cwd);
  entry.agentCreated = true;   // mark now so reuse works even before the caller stamps it
  entry.taskCommand = command; // the reuse key for the next run of the same task
  // Wait for the PTY to be up AND past finishInit's `clear`, so the command isn't
  // wiped. finishInit fires ~1.5s after open; cap the wait at 6s.
  const start = Date.now();
  while (Date.now() - start < 6000) {
    if (entry.backendId != null && entry.ready) break;
    if (entry.closed || entry.startError) break;
    await new Promise((r) => setTimeout(r, 120));
  }
  if (entry.backendId == null || !entry.ready) {
    if (!entry.startError) entry.startError = "终端初始化超时（6 秒内未就绪）";
    // 这里同样不关标签页。智能体拿到 ok:false 就够它换路子了，但用户需要留在屏幕上的证据——
    // 关掉之后终端面板会整个收起来，看上去就是"点了没反应"。createTermTab 的失败路径已经把
    // 原因写进终端本体了；这条超时路径补一行，免得屏幕上只有一个空标签页。
    try { entry.term.write("\r\n\x1b[31m" + entry.startError + "\x1b[0m\r\n"); } catch {}
    return { ok: false, entry, error: entry.startError };
  }
  entry.recentOut = "";
  entry.lastCommand = command;
  entry.lastActivityAt = Date.now();
  backend.termWrite(entry.backendId, command + "\n");
  return { ok: true, entry };
}

function closeTermTab(idx) {
  if (idx < 0 || idx >= termTabs.length) return;
  const tab = termTabs[idx];
  tab.closed = true;
  if (tab.initTimer) { clearTimeout(tab.initTimer); tab.initTimer = 0; }
  // Detach the captured terminal state before asking the backend to stop the PTY.
  // The sink keeps Tauri's late-output dispatcher callable during shutdown.
  if (tab.channel) _releaseTauriChannel(tab.channel);
  tab.channel = null;
  if (tab.backendId != null) backend.termClose(tab.backendId);
  clearTimeout(_ghostTimer); // drop any pending ghost render that captured this tab
  clearTermGhost(tab);
  try { tab.webgl?.dispose(); } catch {} // release the GPU context (avoid leaking WebGL contexts)
  tab.term.dispose();
  termResizeObserver.unobserve(tab.container);
  tab.container.remove();
  termTabs.splice(idx, 1);
  if (termTabs.length === 0) {
    activeTermTab = -1;
    closeTerminal();
    return;
  }
  // Keep activeTermTab pointing at the SAME tab after the splice: closing a tab
  // LEFT of the active one shifts it down by one (decrement); closing the active
  // tab shows its neighbour (clamped); closing one to the right is a no-op.
  if (idx < activeTermTab) activeTermTab--;
  else if (idx === activeTermTab) activeTermTab = Math.min(idx, termTabs.length - 1);
  termTabs[activeTermTab].container.hidden = false;
  if (_termSplitActive) {
    if (termTabs.length >= 2) _applyTermSplit();
    else { _termSplitActive = false; $("terminalBody")?.classList.remove("term-split"); }
  }
  renderTermTabs();
  requestAnimationFrame(() => {
    try { termTabs[activeTermTab].fit.fit(); } catch {}
    termTabs[activeTermTab].term.focus();
  });
}

async function openTerminal() {
  if (!termPanel) return;
  if (termIsOpen()) {
    if (activeTermTab >= 0) termTabs[activeTermTab]?.term.focus();
    return;
  }
  termPanel.hidden = false;
  buildMenubar();
  editorwrapEl?.classList.add("has-terminal");
  monacoEditor.layout();
  _startTermRunningPoll();
  loadTermData();
  refreshTermPathCache().catch(() => {});

  if (termTabs.length === 0) {
    await createTermTab();
  } else {
    switchTermTab(activeTermTab);
  }
}

function closeTerminal() {
  if (!termIsOpen()) return;
  clearTermGhost(termTabs[activeTermTab]);
  termPanel.hidden = true;
  _stopTermRunningPoll();
  buildMenubar();
  editorwrapEl?.classList.remove("has-terminal");
  monacoEditor.layout();
  monacoEditor.focus();
}

function toggleTerminal() {
  if (termIsOpen()) closeTerminal();
  else openTerminal();
}

$("terminalClose")?.addEventListener("click", closeTerminal);
$("termNewBtn")?.addEventListener("click", () => createTermTab());
$("terminalBtn")?.addEventListener("click", toggleTerminal);

// ---- 助手面板开关（标题栏，调试图标左边）----
//
// 走的是既有的 togglePane("assistant")，不是另起一套：视图菜单里本来就有这个开关，
// CSS 的 .layout.hide-assistant 也早就同时收掉了面板和它右边的分隔条。各做一套的
// 结果是两个入口互相不认账——从菜单关掉，标题栏按钮还亮着"已展开"。
function _syncAssistantToggleBtn() {
  const btn = $("toggleAssistantBtn");
  if (!btn) return;
  const open = paneIsOpen("assistant");
  btn.classList.toggle("is-off", !open);
  btn.setAttribute("aria-pressed", open ? "true" : "false");
  btn.title = t(open ? "menu.closeAssistant" : "menu.openAssistant");
  // 换的是**图标本身**，不是给同一个图标改个颜色：同一副几何、只差右段填不填
  // （实心＝面板在，空框＝已收起）。只换颜色的话，光看图标判断不出当前是开是关，
  // 得先记住"亮的是开还是关"——那不叫状态指示。
  const icon = $("toggleAssistantIcon");
  if (icon) icon.setAttribute("href", open ? "#i-sidebar-right-on" : "#i-sidebar-right");
}
_restorePaneState();
_syncAssistantToggleBtn();
$("toggleAssistantBtn")?.addEventListener("click", () => {
  togglePane("assistant");
  _syncAssistantToggleBtn();
  // 编辑器按容器宽度布局，容器一变必须重算，否则代码区会停在旧宽度上。
  try { window.dispatchEvent(new Event("resize")); } catch {}
});

// terminal panel resize
{
  const resizeHandle = $("terminalResize");
  if (resizeHandle) {
    let startY = 0, startH = 0, dragging = false, layoutRaf = 0;
    const scheduleLayout = () => {
      if (layoutRaf) return;
      layoutRaf = requestAnimationFrame(() => {
        layoutRaf = 0;
        monacoEditor.layout();
        if (activeTermTab >= 0 && termTabs[activeTermTab]?.fit)
          try { termTabs[activeTermTab].fit.fit(); } catch {}
      });
    };
    const onMove = (e) => {
      if (!dragging) return;
      const h = Math.max(140, Math.min(viewportH() * 0.7, startH + (startY - e.clientY)));
      termPanel.style.flex = `0 0 ${h}px`;
      scheduleLayout();
    };
    const onUp = () => {
      dragging = false;
      if (layoutRaf) { cancelAnimationFrame(layoutRaf); layoutRaf = 0; }
      document.body.style.cursor = "";
      document.body.style.userSelect = "";
      document.removeEventListener("mousemove", onMove);
      document.removeEventListener("mouseup", onUp);
    };
    resizeHandle.addEventListener("mousedown", (e) => {
      e.preventDefault();
      dragging = true;
      startY = e.clientY;
      startH = termPanel.getBoundingClientRect().height;
      document.body.style.cursor = "ns-resize";
      document.body.style.userSelect = "none";
      document.addEventListener("mousemove", onMove);
      document.addEventListener("mouseup", onUp);
    });
  }
}

// terminal maximize/restore
{
  const maxBtn = $("termMaxBtn");
  if (maxBtn) {
    let maximized = false, savedFlex = "";
    maxBtn.addEventListener("click", () => {
      if (maximized) {
        termPanel.style.flex = savedFlex;
        maxBtn.title = "Maximize Panel";
        maximized = false;
      } else {
        savedFlex = termPanel.style.flex;
        termPanel.style.flex = "1 1 0";
        maxBtn.title = "Restore Panel";
        maximized = true;
      }
      requestAnimationFrame(() => {
        monacoEditor.layout();
        if (activeTermTab >= 0 && termTabs[activeTermTab]?.fit)
          try { termTabs[activeTermTab].fit.fit(); } catch {}
      });
    });
  }
}

