  e.preventDefault();
  const payload = { position: { x: e.clientX, y: e.clientY } };
  const target = _dragTargetAt(payload);
  _hideDrop();
  const files = [...(e.dataTransfer?.files || [])].map((f) => f.path).filter(Boolean);
  await _handleDrop(files, target, payload);
