// 全量草稿同步写掉再走常规镜像。WKWebView 下 beforeunload 不总是触发（Tauri destroy
// 直接拆 webview），pagehide 更可靠；visibilitychange(hidden) 则在"隐藏后被强杀"前多留
// 一个落盘点。三者幂等，重复触发无害；平时的 5s 防抖保存节奏不变。
function _flushExitStateSync() {
  const draft = _streamDraftFlushSync();
  _flushChatHistorySync(); _flushDirtyBuffersSync(); _flushSessionSync();
  // 存在流式会话时再补一手异步兜底：进程若还活着（隐藏/被 CloseRequested 拦下的路径），
  // 草稿镜像进磁盘 store + 唤醒 immediate 保存；真正的卸载里它们跑不完也无妨，
  // 上面的同步 localStorage 写已经落了。
  if (Array.isArray(_chatSessions) && _chatSessions.some((s) => s?.streaming)) {
    void _streamDraftPersistDurable(draft);
    void saveChatHistory({ immediate: true });
  }
}
window.addEventListener("beforeunload", () => { _flushExitStateSync(); saveSession(); });
window.addEventListener("pagehide", () => _flushExitStateSync());
document.addEventListener("visibilitychange", () => {
  // 隐藏 = 之后随时可能被强杀。只在存在流式会话时才 flush，不打扰平时的保存节奏。
  if (document.visibilityState !== "hidden") return;
  if (Array.isArray(_chatSessions) && _chatSessions.some((s) => s?.streaming)) _flushExitStateSync();
});
if (inTauri) {
  import("@tauri-apps/api/window").then(({ getCurrentWindow }) => {
    const currentWindow = getCurrentWindow();
    /*
     * Windows 上关掉了原生标题栏（否则它会压在应用自己那条上面，两条叠着），所以最小化 /
     * 最大化 / 关闭这三个键得自己接。macOS 上这三个按钮不显示（CSS 按 body.is-win 控制），
     * 红绿灯照旧由系统画。
     *
     * 关闭走 `currentWindow.close()` 而不是 destroy()：close 会触发下面那个
     * onCloseRequested，未保存的会话、草稿、文件缓冲才有机会落盘。直接 destroy 等于
     * 点一下叉就丢数据。
     */
    const bindWinCtl = (id, run) => {
      const el = document.getElementById(id);
      if (el) el.addEventListener("click", () => { void run(); });
    };
    bindWinCtl("winMinimize", () => currentWindow.minimize());
    bindWinCtl("winMaximize", () => currentWindow.toggleMaximize());
    bindWinCtl("winClose", () => currentWindow.close());
    // 最大化状态要反映到图标上，否则用户分不清当前是不是最大化。
    const syncMaxState = async () => {
      try { document.body.classList.toggle("is-maximized", await currentWindow.isMaximized()); } catch {}
    };
    void syncMaxState();
    try { void currentWindow.onResized(() => { void syncMaxState(); }); } catch {}

    currentWindow.onCloseRequested(async (event) => {
      event.preventDefault();
      const _exitDraft = _streamDraftFlushSync();
      _flushChatHistorySync(); _flushDirtyBuffersSync(); _flushSessionSync();
      // Wake any debounced chat save and wait for the current in-flight write plus
      // its trailing snapshot before destroying the WebView.流式草稿也赶在 destroy 前
      // 镜像进磁盘 store：localStorage 在窗口销毁/进程退出时未必来得及落盘。
      await Promise.all([saveChatHistory({ immediate: true }), saveSession(), _streamDraftPersistDurable(_exitDraft)]);
      await stopFileWatcher();
      await currentWindow.destroy();
    });
  }).catch(() => {});
}
restoreSession().then(() => _loadBreakpoints()).catch(() => _loadBreakpoints());
// Restore the Michael login session (keeps the user logged in across restarts).
restoreMichaelSession();
// Keep the plan/credits live: re-fetch when the window regains focus (e.g. you just
// changed the plan in the backend admin and switched back) + a slow background poll.
// This is why an admin plan/credit change now shows up without restarting the IDE.
window.addEventListener("focus", () => refreshMichaelUser());
document.addEventListener("visibilitychange", () => { if (!document.hidden) refreshMichaelUser(); });

/**
 * 回到窗口时重新读一遍环境。
 *
 * 一个进程的环境块是 exec 那一刻的快照——用户在别的终端 `export`、改 `.zshrc`、用系统属性面板
 * 加一个变量，都不会改写已经在跑的这个 app。以前 macOS 上那次登录 shell 探测是 `OnceLock`，
 * **整个进程只跑一次**，所以"刚装的工具找不到"要重启 App 才好；Windows 上更彻底，压根没有
 * 任何重读通道。
 *
 * 用户从别处装完东西切回来，正是环境最可能变过的时刻，所以挂在 focus 上；后端有 5 秒下限防抖，
 * alt-tab 连点不会刷出一串 shell。
 */
const _refreshShellEnv = async () => {
  try {
    const r = await backend.envRefresh();
    if (r?.shell?.kind) _shellPlanCache = r.shell;
    if (!r?.changed) return;
    _osDetailCache = null; // 这个缓存以前永不失效，会把开机那一刻的 shell/版本冻到关机
    // 给模型一句话：它此前得出的"没装 / 找不到命令"结论可能已经不成立了。
    _envChangedNote = "\n环境已更新：PATH 在上一轮之后发生了变化，此前得出的「找不到命令 / 未安装」结论可能已失效，需要时请重新探测。";
    try { showToast("🔄 检测到环境变量变化，已刷新", { duration: 3000 }); } catch {}
  } catch {}
};
window.addEventListener("focus", _refreshShellEnv);
document.addEventListener("visibilitychange", () => { if (!document.hidden) _refreshShellEnv(); });
// Idempotent: clear any prior timer so a Vite HMR re-run can't stack duplicate
// pollers (stacked pollers = duplicate account-info refreshes / toast spam).
if (typeof window !== "undefined" && window.__michaelUserTimer) clearInterval(window.__michaelUserTimer);
{
  const _mut = setInterval(() => { if (!document.hidden) refreshMichaelUser(); }, 60000);
  if (typeof window !== "undefined") window.__michaelUserTimer = _mut;
}

let _cachedHomeDir = "";
if (inTauri) {
  backend.homeDir().then(home => {
    if (home) {
      _cachedHomeDir = home;
      backend.registerWorkspaceRoot(home).catch(() => {});
    }
  }).catch(() => {});

  // macOS fullscreen hides the traffic lights; mirror that state onto <body> so
  // the titlebar can drop the 84px reserved for them (logo + menus slide left).
  import("@tauri-apps/api/window").then(({ getCurrentWindow }) => {
    const currentWindow = getCurrentWindow();
    const _syncFullscreen = () => currentWindow.isFullscreen()
      .then(fs => document.body.classList.toggle("is-fullscreen", !!fs))
      .catch(() => {});
    _syncFullscreen();
    currentWindow.onResized(() => _syncFullscreen()).catch(() => {});
  }).catch(() => {});
}

