// ---- Terminal Split ----
$("termSplitBtn")?.addEventListener("click", async () => {
  _termSplitActive = !_termSplitActive;
  const body = $("terminalBody");
  body.classList.toggle("term-split", _termSplitActive);
  if (_termSplitActive) {
    if (termTabs.length < 2) await createTermTab(); // need a second pane to split into
    _applyTermSplit();
  } else {
    // back to single view: show only the active terminal
    termTabs.forEach((t, i) => { t.container.hidden = i !== activeTermTab; });
  }
  requestAnimationFrame(() => termTabs.forEach((t) => {
    if (!t.container.hidden) { try { t.fit.fit(); } catch {} }
  }));
});

// Show two terminals side by side: the active one + the newest other one.
function _applyTermSplit() {
  const a = activeTermTab >= 0 ? activeTermTab : termTabs.length - 1;
  let b = termTabs.length - 1;
  if (b === a) b = termTabs.length - 2;
  const show = new Set([a, b].filter((i) => i >= 0 && i < termTabs.length));
  termTabs.forEach((t, i) => { t.container.hidden = !show.has(i); });
}

// ---- Bookmarks ----
const _bookmarks = new Map();
let _bookmarkDecorations = [];

function toggleBookmark(path, line) {
  if (!path) return;
  const key = `${path}:${line}`;
  if (_bookmarks.has(key)) {
    _bookmarks.delete(key);
  } else {
    _bookmarks.set(key, { path, line, label: "" });
  }
  renderBookmarkDecorations();
}

function renderBookmarkDecorations() {
  if (!activePath) return;
  const decos = [];
  for (const [, bm] of _bookmarks) {
    if (bm.path !== activePath) continue;
    decos.push({
      range: new monaco.Range(bm.line, 1, bm.line, 1),
      options: {
        isWholeLine: true,
        glyphMarginClassName: "bookmark-glyph",
        overviewRuler: { color: "#007aff", position: monaco.editor.OverviewRulerLane.Center },
      },
    });
  }
  _bookmarkDecorations = monacoEditor.deltaDecorations(_bookmarkDecorations, decos);
}

function nextBookmark() {
  const line = monacoEditor.getPosition()?.lineNumber || 0;
  const sorted = [..._bookmarks.values()].filter(b => b.path === activePath).sort((a, b) => a.line - b.line);
  const next = sorted.find(b => b.line > line) || sorted[0];
  if (next) {
    monacoEditor.revealLineInCenter(next.line);
    monacoEditor.setPosition({ lineNumber: next.line, column: 1 });
  }
}

function prevBookmark() {
  const line = monacoEditor.getPosition()?.lineNumber || 0;
  const sorted = [..._bookmarks.values()].filter(b => b.path === activePath).sort((a, b) => b.line - a.line);
  const prev = sorted.find(b => b.line < line) || sorted[0];
  if (prev) {
    monacoEditor.revealLineInCenter(prev.line);
    monacoEditor.setPosition({ lineNumber: prev.line, column: 1 });
  }
}

function toggleBookmarksPanel() {
  showToast(`${_bookmarks.size} bookmark(s)`);
}

monacoEditor.addAction({
  id: "editor.toggleBookmark",
  label: "Toggle Bookmark",
  keybindings: [monaco.KeyMod.CtrlCmd | monaco.KeyMod.Alt | monaco.KeyCode.KeyK],
  run: () => {
    const line = monacoEditor.getPosition()?.lineNumber;
    if (line && activePath) toggleBookmark(activePath, line);
  },
});
monacoEditor.addAction({
  id: "editor.nextBookmark",
  label: "Next Bookmark",
  keybindings: [monaco.KeyMod.CtrlCmd | monaco.KeyMod.Alt | monaco.KeyCode.KeyN],
  run: () => nextBookmark(),
});
monacoEditor.addAction({
  id: "editor.prevBookmark",
  label: "Previous Bookmark",
  keybindings: [monaco.KeyMod.CtrlCmd | monaco.KeyMod.Alt | monaco.KeyCode.KeyP],
  run: () => prevBookmark(),
});

// ---- 定时任务 ----
//
// 「设置个时间，让它自己去干」这件事以前完全没有：全仓没有任何 cron / schedule。
//
// 唤醒器就放在 JS 里，不放 Rust。Rust 的 tokio loop 和 webview 是同一个进程——
// 应用活着两边都活着，应用没了两边一起没。而没有 webview 就没有智能体，所以
// Rust 那一侧买不到任何多出来的时间窗口，只多一层跨进程通信。
// 「关掉应用也要跑」需要 launchd / 计划任务，那是往用户系统里装常驻项，
// 这个项目一贯不做，也不该背着用户做。所以边界说清楚：**应用开着才跑**。
//
// 判据用墙钟比较（nextAt <= now）而不是靠 interval 的精度，所以窗口被系统节流、
// 或者电脑睡了一觉，醒来那一次就是一个 overdue，照样会被认出来执行。
const _SCHED_KEY = "schedules";
const _SCHED_TICK_MS = 30_000;
let _schedules = null;
let _schedTimer = null;
let _schedFiring = false;

async function _schedLoad() {
  if (_schedules) return _schedules;
  try {
    const st = await getStore();
    const raw = await st.get(_SCHED_KEY);
    _schedules = Array.isArray(raw) ? raw : [];
  } catch { _schedules = []; }
  return _schedules;
}

async function _schedSave() {
  try {
    const st = await getStore();
    await st.set(_SCHED_KEY, _schedules || []);
    await st.save();
  } catch {}
}

/// 下一次该在什么时候跑。every_minutes = 周期；at = 每天的 HH:MM。
function _schedNextAt(task, from = Date.now()) {
  if (task.every_minutes > 0) return from + task.every_minutes * 60_000;
  const m = /^(\d{1,2}):(\d{2})$/.exec(String(task.at || ""));
  if (!m) return 0;
  const d = new Date(from);
  d.setHours(Number(m[1]), Number(m[2]), 0, 0);
  // 今天这个点已经过了就排到明天。用本地时区——用户说「早上 9 点」指的是他的 9 点。
  if (d.getTime() <= from) d.setDate(d.getDate() + 1);
  return d.getTime();
}

function _schedSummary(t) {
  const when = t.every_minutes > 0 ? `每 ${t.every_minutes} 分钟` : `每天 ${t.at}`;
  const next = t.nextAt ? new Date(t.nextAt).toLocaleString() : "未排期";
  const last = t.lastOutcome ? `；上次 ${t.lastOutcome}` : "";
  return `#${t.id} ${when} · 下次 ${next}${last}\n    ${String(t.prompt || "").slice(0, 120)}`;
}

/// 到点了就跑一次。串行：同一时刻只允许一个定时任务在跑，否则几个任务一起
/// 抢同一个会话和同一条审批链，结果互相踩。
async function _schedFireDue() {
  if (_schedFiring) return;
  const list = await _schedLoad();
  const now = Date.now();
  const due = list.find((t) => t && t.enabled !== false && t.nextAt > 0 && t.nextAt <= now);
  if (!due) return;
  _schedFiring = true;
  // 先把下一次排掉再跑。跑的过程中出任何岔子（异常、应用被关）都不会让这条任务
  // 卡在「已到期」上被反复触发。
  due.lastFiredAt = now;
  due.nextAt = _schedNextAt(due, now);
  await _schedSave();
  try {
    _setUnattendedRun(true);
    await sendPrompt(
      `[定时任务 #${due.id}]\n${due.prompt}\n\n`
        + `（这一轮是定时触发的，此刻没有人在电脑前。需要用户当面确认的操作会被自动拒绝并留给他，`
        + `你把不需要确认的部分做完，然后在总结里写清哪些等他回来处理。）`,
    );
    due.lastOutcome = "已执行";
  } catch (e) {
    due.lastOutcome = `失败：${String(e?.message || e).slice(0, 80)}`;
  } finally {
    _setUnattendedRun(false);
    _schedFiring = false;
    await _schedSave();
    // 铃铛是「人回来怎么知道」的唯一落点，所以这里必须发一条。
    try {
      showNotification({
        title: `定时任务 #${due.id} ${due.lastOutcome}`,
        message: String(due.prompt || "").slice(0, 120),
      });
    } catch {}
  }
}

async function _schedStart() {
  if (_schedTimer) return;
  const list = await _schedLoad();
  // 重启后补排期：存的 nextAt 可能已经是过去时（关机期间到点了）。
  let dirty = false;
  for (const t of list) {
    if (t && t.enabled !== false && !(t.nextAt > 0)) { t.nextAt = _schedNextAt(t); dirty = true; }
  }
  if (dirty) await _schedSave();
  _schedTimer = setInterval(() => { void _schedFireDue(); }, _SCHED_TICK_MS);
  void _schedFireDue();
}

// 定时任务的唤醒器。启动时会顺手补一次排期——关机期间到点的任务，开机后的第一次
// 检查就会认出来（判据是墙钟比较，不是靠 interval 的精度）。
//
// **位置必须在 _schedTimer 这些模块级 let 的声明之后。** 原来它写在上面一千行处，
// 注释解释的是"不放模块最顶上，因为要先能读到 store"——但它仍然在模块的顶层语句序列里，
// 而且排在 `let _schedTimer = null` 前面。_schedStart 的第一句就是 `if (_schedTimer) return;`，
// 于是模块求值走到那一行时命中 TDZ，抛 ReferenceError；`void` 把返回的 promise 丢掉，
// 只在控制台留下一条 unhandled rejection。结果是**整个定时任务功能从来没启动过**：
// 没有定时器、没有补排期，界面上照常能添加任务，只是永远不会触发。
// 反向守卫见 wiring.test.mjs「模块顶层调用的函数不许读到更靠后声明的模块级变量」。
void _schedStart();

// ---- Notification Center ----
const _notifHistory = [];
const MAX_NOTIF_HISTORY = 50;

const _origShowNotification = showNotification;
const _wrappedShowNotification = function(opts) {
  _notifHistory.unshift({ ...opts, time: Date.now() });
  if (_notifHistory.length > MAX_NOTIF_HISTORY) _notifHistory.pop();
  _updateNotifBadge();
  return _origShowNotification(opts);
};
// 这一行以前不存在，于是上面这个包装**从来没有被安装过**：定义了、也确实会往
// _notifHistory 里写，但没有任何调用点走它——所有通知走的都是原来那个函数。
// 结果就是通知历史恒为空、角标恒为 0、通知中心永远显示「没有通知」。
// showNotification 是函数声明，绑定可写；这行在两个声明之后执行，没有 TDZ 问题。
// 这也是「定时任务跑完了，人回来怎么知道」的落点：铃铛得先是活的。
showNotification = _wrappedShowNotification;

function _updateNotifBadge() {
  const badge = $("notifBadge");
  if (!badge) return;
  const unread = _notifHistory.filter(n => !n.read).length;
  badge.hidden = unread === 0;
  badge.textContent = unread > 9 ? "9+" : String(unread);
}

let _notifCenterClose = null;
function toggleNotifCenter() {
  let panel = document.querySelector(".notif-center");
  if (panel) { (_notifCenterClose || (() => panel.remove()))(); return; } // close via the abort path
  panel = document.createElement("div");
  panel.className = "notif-center";
  panel.innerHTML = `<div class="notif-center__head"><span>Notifications</span><button class="iconbtn" id="notifClearAll" title="Clear all"><svg class="ic"><use href="#i-close" /></svg></button></div><div class="notif-center__list"></div>`;
  const list = panel.querySelector(".notif-center__list");
  if (!_notifHistory.length) {
    list.innerHTML = '<div class="empty"><p>No notifications.</p></div>';
  } else {
    for (const n of _notifHistory) {
      n.read = true;
      const row = document.createElement("div");
      row.className = "notif-center__item";
      const ago = _timeAgo(n.time);
      row.innerHTML = `<div class="notif-center__title">${_escHtml(n.title || "")}</div><div class="notif-center__msg">${_escHtml(n.message || "")}</div><div class="notif-center__time">${ago}</div>`;
      list.appendChild(row);
    }
  }
  _updateNotifBadge();
  // One AbortController per open — closing via ANY path (bell toggle / Clear all / click-outside)
  // aborts it, so the document "dismiss" listener is ALWAYS removed and can't stack across opens.
  const ac = new AbortController();
  _notifCenterClose = () => { try { ac.abort(); } catch {} panel.remove(); _notifCenterClose = null; };
  panel.querySelector("#notifClearAll")?.addEventListener("click", () => {
    _notifHistory.length = 0;
    _updateNotifBadge();
    _notifCenterClose();
  }, { signal: ac.signal });
  document.body.appendChild(panel);
  requestAnimationFrame(() => panel.classList.add("notif-center--visible"));
  const dismiss = (e) => { if (!panel.contains(e.target) && e.target !== $("notifBellBtn")) _notifCenterClose(); };
  setTimeout(() => document.addEventListener("click", dismiss, { signal: ac.signal }), 50);
}

function _timeAgo(ts) {
  const s = Math.floor((Date.now() - ts) / 1000);
  if (s < 60) return "just now";
  if (s < 3600) return `${Math.floor(s / 60)}m ago`;
  if (s < 86400) return `${Math.floor(s / 3600)}h ago`;
  return `${Math.floor(s / 86400)}d ago`;
}

$("notifBellBtn")?.addEventListener("click", (e) => { e.stopPropagation(); toggleNotifCenter(); });

// ---- Workspace Trust ----
//
// 信任决定的是**要不要执行这个仓库提供的东西**，不是能不能读写它的文件。未信任的工作区
// 照常打开、编辑、跑你自己敲的命令；只是不会去执行仓库自带的可执行内容：
//
//   • 语言服务器不使用 `node_modules/.bin` / `.venv/bin` 里的版本（改用系统安装的）
//   • 仓库自带的 hooks 不运行
//
// 这道门存在的理由：打开一个从 GitHub clone 来的仓库，不应该等于执行它作者写的任意程序。
// 而"只用系统装的语言服务器"这个降级对绝大多数人是无感的。
let _workspaceTrusted = false;
const _workspaceTrustCache = new Map();

/// 当前工作区是否已信任（同步读，供 LSP 启动等同步路径使用）。
function isWorkspaceTrusted() {
  return _workspaceTrusted === true;
}

async function checkWorkspaceTrust(path) {
  path = _toPosix(path);
  // 浏览器版没有本地进程可执行，信任概念不适用。
  if (!inTauri) { _workspaceTrusted = true; return true; }
  if (!path) { _workspaceTrusted = true; return true; }
  if (_workspaceTrustCache.has(path)) {
    _workspaceTrusted = _workspaceTrustCache.get(path) === true;
    return _workspaceTrusted;
  }

  let trusted = [];
  try {
    const store = await getStore();
    trusted = (await store.get("trustedWorkspaces")) || [];
    if (!Array.isArray(trusted)) trusted = [];
  } catch { trusted = []; }

  // 已信任过的路径，或它的某个已信任祖先目录（信任一个仓库即信任其子目录）。
  const known = trusted.some((t) => {
    const tp = _toPosix(t).replace(/\/+$/, "");
    return tp === path || path.startsWith(tp + "/");
  });
  if (known) {
    _workspaceTrusted = true;
    _workspaceTrustCache.set(path, true);
    return true;
  }

  // 默认不再问：直接信任。和沙箱那条一样是所有者选的默认值，关掉就恢复逐个确认。
  if (_autoTrustWorkspaces()) {
    _workspaceTrusted = true;
    _workspaceTrustCache.set(path, true);
    try {
      const store = await getStore();
      trusted.push(path);
      await store.set("trustedWorkspaces", trusted);
    } catch { /* 存不下也不影响本次：下次照样自动信任 */ }
    return true;
  }

  const decision = await _toolApprovalDialog({
    title: "信任这个文件夹的作者吗？",
    detail: `${path}\n\n`
      + `信任后，Mr. Day One 会使用这个仓库自带的开发工具（例如 node_modules 里的\n`
      + `语言服务器版本），并允许它的 .mrdayone/hooks.json 运行。\n\n`
      + `不信任也能正常打开、阅读和编辑代码，你自己敲的命令照常执行——\n`
      + `只是不会去运行这个仓库提供的程序。\n\n`
      + `⚠️ 如果这是从网上 clone 来的、你还没读过的代码，请选择"不信任"。`,
  });
  const ok = decision !== "deny";
  _workspaceTrusted = ok;
  _workspaceTrustCache.set(path, ok);
  if (ok && decision === "always") {
    try {
      const store = await getStore();
      trusted.push(path);
      await store.set("trustedWorkspaces", trusted);
    } catch { /* 存不下就下次再问一遍，不影响本次决定 */ }
  }
  return ok;
}

// ---- Multi-file AI Composer ----
let _composerFiles = [];
let _composerOpen = false;

function openComposer() {
  _composerOpen = true;
  const panel = document.querySelector(".composer-panel") || _createComposerPanel();
  panel.hidden = false;
  panel.querySelector(".composer-input")?.focus();
}

function closeComposer() {
  _composerOpen = false;
  const panel = document.querySelector(".composer-panel");
  if (panel) panel.hidden = true;
}

function _createComposerPanel() {
  const panel = document.createElement("div");
  panel.className = "composer-panel";
  panel.innerHTML = `
    <div class="composer-panel__head">
      <span>AI Composer</span>
      <span class="composer-panel__files" id="composerFiles">0 files selected</span>
      <button class="iconbtn" id="composerClose" title="Close"><svg class="ic"><use href="#i-close" /></svg></button>
    </div>
    <div class="composer-panel__file-list" id="composerFileList"></div>
    <div class="composer-panel__input-wrap">
      <textarea class="composer-input" id="composerInput" placeholder="Describe changes across multiple files..." rows="3"></textarea>
      <button class="btn btn--primary" id="composerSend">Apply Changes</button>
    </div>
  `;
  document.body.appendChild(panel);
  panel.querySelector("#composerClose").addEventListener("click", closeComposer);
  panel.querySelector("#composerSend").addEventListener("click", () => runComposer());
  _updateComposerFileList();
  return panel;
}

function addFileToComposer(path) {
  if (!_composerFiles.includes(path)) _composerFiles.push(path);
  _updateComposerFileList();
}

function _updateComposerFileList() {
  const listEl = document.querySelector("#composerFileList");
  const countEl = document.querySelector("#composerFiles");
  if (!listEl) return;
  listEl.innerHTML = "";
  for (const f of _composerFiles) {
    const row = document.createElement("div");
    row.className = "composer-file";
    row.innerHTML = `<span>${_escHtml(f.split("/").pop())}</span>`;
    const removeBtn = document.createElement("button");
    removeBtn.className = "iconbtn";
    removeBtn.innerHTML = '<svg class="ic"><use href="#i-close" /></svg>';
    removeBtn.addEventListener("click", () => {
      _composerFiles = _composerFiles.filter(p => p !== f);
      _updateComposerFileList();
    });
    row.appendChild(removeBtn);
    listEl.appendChild(row);
  }
  if (countEl) countEl.textContent = `${_composerFiles.length} file(s)`;
}

async function runComposer() {
  const input = document.querySelector("#composerInput");
  const prompt = input?.value?.trim();
  if (!prompt || !_composerFiles.length) return;
  showToast(`AI Composer：处理 ${_composerFiles.length} 个文件…`);
  appendOutput("extensions", `[Composer] 开始：${_composerFiles.length} 个文件 — ${prompt}`);
  let changed = 0, failed = 0, nochange = 0;
  for (const filePath of _composerFiles) {
    const fileName = filePath.split("/").pop();
    try {
      const content = await backend.readTextFile(filePath); // was backend.readFile (doesn't exist) → composer read nothing
      const lang = extLang(fileName);
      const response = await _callAI(`You are a code editor assistant. Modify the following ${lang} file based on the user's instruction.\n\nFile: ${fileName}\n\`\`\`${lang}\n${content}\n\`\`\`\n\nInstruction: ${prompt}\n\nReturn ONLY the complete modified file, no explanations, no markdown fences.`);
      const code = (typeof _stripFence === "function" ? _stripFence(response || "") : (response || "")).replace(/\s+$/, "");
      if (code && code.trim() && code.trim() !== content.trim()) {
        // Apply to the editor as an UNSAVED buffer (multi-file safe + non-destructive):
        // the user reviews each tab and saves. The single global diff editor could only
        // ever show the LAST file, so we open them instead of overwriting one preview.
        await openFile(filePath, fileName).catch(() => {});
        const f = openFiles.get(filePath);
        if (f && f.model) {
          f.model.setValue(code);
          f.dirty = true;
          const tabEl = tabsEl.querySelector(`[data-path="${CSS.escape(filePath)}"]`);
          if (tabEl) tabEl.classList.add("dirty");
        }
        changed++;
        appendOutput("extensions", `[Composer] 已修改 ${fileName}（在编辑器里，未保存——检查后 ${shortcutLabel("mod+s")} 保存或撤销）`);
      } else {
        nochange++;
        appendOutput("extensions", `[Composer] ${fileName}: 无需改动`);
      }
    } catch (err) {
      failed++;
      appendOutput("extensions", `[Composer] ${fileName} 出错: ${err?.message || err}`);
    }
  }
  showToast(`AI Composer 完成：${changed} 改 / ${nochange} 无变化 / ${failed} 失败（改动在编辑器里，检查后保存）`);
}

async function _callAI(prompt) {
  try {
    const cfg = loadConfig();
    const model = cfg.model || "deepseek-chat";
    const apiKey = cfg.apiKey;
    const baseUrl = cfg.baseUrl || "https://api.deepseek.com";
    if (!apiKey) return null;
    const endpoint = _chatCompletionsUrl(baseUrl);
    if (!endpoint) return null;
    const res = await fetch(endpoint, {
      method: "POST",
      headers: { "Content-Type": "application/json", Authorization: `Bearer ${apiKey}` },
      body: JSON.stringify({ model, messages: [{ role: "user", content: prompt }], max_tokens: 4096, temperature: 0.3 }),
    });
    const data = await res.json();
    return data.choices?.[0]?.message?.content || null;
  } catch { return null; }
}

monacoEditor.addAction({
  id: "editor.addToComposer",
  label: "Add to AI Composer",
  keybindings: [monaco.KeyMod.CtrlCmd | monaco.KeyMod.Shift | monaco.KeyCode.KeyA],
  run: () => {
    if (activePath) {
      addFileToComposer(activePath);
      if (!_composerOpen) openComposer();
      showToast(`Added ${activePath.split("/").pop()} to Composer`);
    }
  },
});

